bundle["Interface"] = [=[
local importarModulo = ...
local cloneref = cloneref or clonereference or function(inst) return inst end

local CoreGui = cloneref(game:GetService("CoreGui"))
local GuiService = cloneref(game:GetService("GuiService"))
local Players = cloneref(game:GetService("Players"))
local RunService = cloneref(game:GetService("RunService"))
local SoundService = cloneref(game:GetService("SoundService"))
local UserInputService = cloneref(game:GetService("UserInputService"))
local TextService = cloneref(game:GetService("TextService"))
local Teams = cloneref(game:GetService("Teams"))
local TweenService = cloneref(game:GetService("TweenService"))
local Stats = cloneref(game:GetService("Stats"))
local HapticService = cloneref(game:GetService("HapticService"))
local HttpService = cloneref(game:GetService("HttpService"))

local getgenv = getgenv or function() return shared end
local gethui = gethui or function() return CoreGui end

-- Registrar atlas Lucide globalmente para o Sirius Gen2 renderizar todos os ícones nativamente
local Lucide = nil
pcall(function()
    Lucide = importarModulo("IconAtlas")
end)
if Lucide and Lucide.GetAsset then
    getgenv().__BrazukaLucide = function(nomeIcone)
        local ok, dados = pcall(Lucide.GetAsset, nomeIcone)
        if ok and dados and dados.Url then
            return dados
        end
        return nil
    end
end
getgenv().RAYFIELD_ANALYTICS = false

-- Carregar o motor Sirius Rayfield Gen2 modificado (ou fallback oficial da web se necessário)
local Rayfield = nil
pcall(function()
    Rayfield = importarModulo("SiriusGen2")
end)
if not Rayfield then
    Rayfield = loadstring(game:HttpGet("https://sirius.menu/gen2"))()
end
getgenv().Rayfield = Rayfield

