local function fonteComPeso(enumFonte, peso)
    local base = Font.fromEnum(enumFonte)
    return Font.new(base.Family, peso or Enum.FontWeight.Medium, base.Style)
end

local function clarearOuEscurecer(cor, fator)
    local lum = 0.299 * cor.R + 0.587 * cor.G + 0.114 * cor.B
    local alvo = if lum > 0.55 then Color3.new(0, 0, 0) else Color3.new(1, 1, 1)
    return cor:Lerp(alvo, math.clamp(fator, 0, 1))
end

local function corTextoContraste(cor)
    local lum = 0.299 * cor.R + 0.587 * cor.G + 0.114 * cor.B
    return if lum > 0.62 then Color3.fromRGB(16, 16, 20) else Color3.fromRGB(255, 255, 255)
end

local function construirTemaSirius(esquema, raioCantos)
    local bg = esquema.BackgroundColor or Color3.fromRGB(20, 20, 22)
    local main = esquema.MainColor or Color3.fromRGB(30, 30, 34)
    local acc = esquema.AccentColor or VERDE_BRASIL
    local out = esquema.OutlineColor or Color3.fromRGB(58, 58, 64)
    local fnt = esquema.FontColor or Color3.fromRGB(255, 255, 255)
    local lumBg = 0.299 * bg.R + 0.587 * bg.G + 0.114 * bg.B
    local ehClaro = lumBg > 0.55
    local fonteMedia = esquema.Font or fonteComPeso(Enum.Font.Gotham, Enum.FontWeight.Medium)
    local fonteTitulo = Font.new(fonteMedia.Family, Enum.FontWeight.SemiBold, fonteMedia.Style)
    local r = math.clamp(tonumber(raioCantos) or Library.CornerRadius or 12, 0, 24)

    return {
        CornerRoundness = UDim.new(0, math.max(8, r + 4)),
        ElementCornerRadius = UDim.new(0, math.max(4, r)),
        WindowColor = ColorSequence.new({
            ColorSequenceKeypoint.new(0, bg),
            ColorSequenceKeypoint.new(1, bg:Lerp(main, 0.65)),
        }),
        ShadowColor = if ehClaro then Color3.fromRGB(115, 122, 130) else Color3.fromRGB(8, 8, 10),
        SurfaceStroke = out,
        ElementGradient = ColorSequence.new({
            ColorSequenceKeypoint.new(0, main),
            ColorSequenceKeypoint.new(1, clarearOuEscurecer(main, 0.06)),
        }),
        ElementStroke = out,
        ElementStrokeGradient = ColorSequence.new({
            ColorSequenceKeypoint.new(0, out),
            ColorSequenceKeypoint.new(1, clarearOuEscurecer(out, 0.16)),
        }),
        ElementStrokeHover = out:Lerp(acc, 0.45),
        ElementTransparency = math.clamp(tonumber(Library.ElementTransparency) or 0, 0, 0.45),
        LiveAnimation = Library.LiveAnimation == true,
        ElementStrokeTransparency = if ehClaro then 0.1 else 0.15,
        ElementStrokeHoverTransparency = 0,
        DarkToggleOverlay = not ehClaro,
        TabColor = fnt,
        TabBackground = ColorSequence.new(main:Lerp(acc, 0.22), main),
        TabStroke = ColorSequence.new(out:Lerp(acc, 0.45), out),
        SliderBackground = clarearOuEscurecer(main, 0.12),
        SliderBackgroundHover = clarearOuEscurecer(main, 0.22),
        SliderProgress = ColorSequence.new(acc, acc:Lerp(Color3.new(1, 1, 1), 0.15)),
        SliderHandle = if ehClaro then Color3.fromRGB(45, 50, 56) else Color3.fromRGB(255, 255, 255),
        SliderStroke = out,
        AccentColor = acc,
        AccentStroke = acc:Lerp(Color3.new(1, 1, 1), 0.3),
        AccentGlow = if ehClaro then 0.8 else 0.45,
        ToggleTrack = if ehClaro then Color3.fromRGB(198, 204, 210) else Color3.fromRGB(10, 10, 12),
        ToggleTrackTransparency = if ehClaro then 0 else 0.4,
        ToggleKnobOff = fnt,
        ToggleKnobOffTransparency = if ehClaro then 0.1 else 0.65,
        FieldBackground = clarearOuEscurecer(main, 0.14),
        FieldTransparency = if ehClaro then 0 else 0.35,
        FieldGlow = acc,
        PlaceholderColor = fnt:Lerp(bg, 0.45),
        StatBackground = bg,
        ContentColor = fnt,
        ElementTextHoverColor = fnt,
        TitlingColor = fnt,
        ActionColor = fnt,
        DropdownHighlight = acc,
        NeutralButton = clarearOuEscurecer(main, 0.1),
        NeutralButtonHover = clarearOuEscurecer(main, 0.2),
        NeutralButtonStroke = out,
        ErrorColor = esquema.RedColor or Color3.fromRGB(195, 50, 50),
        ErrorStrokeColor = Color3.fromRGB(245, 80, 80),
        Font = fonteMedia,
        TitleFont = fonteTitulo,
    }
end

function Library:GiveSignal(conexao)
    if conexao then
        table.insert(Library.Signals, conexao)
    end
    return conexao
end

function Library:OnUnload(fn)
    table.insert(Library.UnloadSignals, fn)
end

function Library:AddToRegistry(inst, props)
    if inst then
        Library.Registry[inst] = props or {}
    end
end

local function aplicarTemaNosFlutuantes()
    local esq = Library.Scheme
    for _, item in ipairs(Library.FloatingFrames) do
        if item.Frame and item.Frame.Parent then
            item.Frame.BackgroundColor3 = esq.BackgroundColor
            if item.Grad then
                item.Grad.Color = ColorSequence.new(esq.BackgroundColor, esq.MainColor)
            end
            if item.Stroke then
                item.Stroke.Color = esq.OutlineColor
            end
            if item.AccentBar then
                item.AccentBar.BackgroundColor3 = esq.AccentColor
            end
            if item.Title then
                item.Title.TextColor3 = esq.FontColor
                item.Title.FontFace = esq.Font
            end
            if item.Corner then
                item.Corner.CornerRadius = UDim.new(0, math.max(6, Library.CornerRadius))
            end
        end
    end
    for _, card in ipairs(Library.CardFrames) do
        if card.Frame and card.Frame.Parent then
            card.Frame.BackgroundColor3 = esq.MainColor
            if card.Stroke then card.Stroke.Color = esq.OutlineColor end
            if card.Corner then card.Corner.CornerRadius = UDim.new(0, math.max(6, Library.CornerRadius)) end
            if card.Title then
                card.Title.TextColor3 = esq.FontColor
                card.Title.FontFace = Font.new(esq.Font.Family, Enum.FontWeight.SemiBold, esq.Font.Style)
            end
            if card.Icon and not card.IconIsAsset then
                card.Icon.ImageColor3 = esq.AccentColor
            end
            if card.Chevron then card.Chevron.TextColor3 = esq.FontColor end
            if card.Divider then card.Divider.BackgroundColor3 = esq.OutlineColor end
        end
    end
    for inst, mapa in pairs(Library.Registry) do
        if typeof(inst) == "Instance" and inst.Parent then
            for prop, chave in pairs(mapa) do
                if type(chave) == "string" and esq[chave] ~= nil then
                    pcall(function() inst[prop] = esq[chave] end)
                end
            end
        end
    end
    local tag = Library._versionTag
    if tag and tag.main and tag.main.Parent then
        local acc = esq.AccentColor or VERDE_BRASIL
        local txtCor = corTextoContraste(acc)
        tag.color = acc
        tag.main.BackgroundColor3 = acc
        if tag.title then tag.title.TextColor3 = txtCor end
        if tag.iconLabel then tag.iconLabel.ImageColor3 = txtCor end
    end
    if Library._headerPerfWidget and Library._headerPerfWidget.ApplyTheme then
        pcall(Library._headerPerfWidget.ApplyTheme, Library._headerPerfWidget)
    end
    for _, btnObj in ipairs(Library._mobileButtonsAtivos) do
        if btnObj and btnObj.ApplyTheme then
            pcall(btnObj.ApplyTheme, btnObj)
        end
    end
end

function Library:UpdateColorsUsingRegistry()
    if Library.RFWindow and not Library.Unloaded then
        pcall(function()
            Library.RFWindow:ChangeTheme(construirTemaSirius(Library.Scheme, Library.CornerRadius))
        end)
    end
    aplicarTemaNosFlutuantes()
end

function Library:SetFont(fonteEnum)
    local ok, f = pcall(function()
        if typeof(fonteEnum) == "Font" then return fonteEnum end
        if typeof(fonteEnum) == "EnumItem" then return fonteComPeso(fonteEnum, Enum.FontWeight.Medium) end
        if type(fonteEnum) == "string" and Enum.Font[fonteEnum] then return fonteComPeso(Enum.Font[fonteEnum], Enum.FontWeight.Medium) end
        return fonteComPeso(Enum.Font.Gotham, Enum.FontWeight.Medium)
    end)
    if ok and f then
        Library.Scheme.Font = f
        Library:UpdateColorsUsingRegistry()
    end
end

function Library:SetBackgroundImage(imagemUrl)
    Library.Scheme.BackgroundImage = tostring(imagemUrl or "")
    if Library._bgImageLabel then
        local url = Library.Scheme.BackgroundImage
        if url ~= "" and tonumber(url) then
            url = "rbxassetid://" .. url
        end
        Library._bgImageLabel.Image = url
        Library._bgImageLabel.ImageTransparency = 1 - math.clamp(tonumber(Library.BgImageOpacity) or 0.18, 0.02, 0.95)
        Library._bgImageLabel.Visible = (url ~= "")
    end
end

function Library:SetLiveAnimation(ativo)
    Library.LiveAnimation = ativo == true
    Library:UpdateColorsUsingRegistry()
end

function Library:SetElementTransparency(valor)
    local v = tonumber(valor) or 0
    if v > 1 then v = v / 100 end
    Library.ElementTransparency = math.clamp(v, 0, 0.45)
    Library:UpdateColorsUsingRegistry()
end

function Library:SetBgImageOpacity(opacidade)
    local v = tonumber(opacidade) or 0.18
    if v > 1 then v = v / 100 end
    Library.BgImageOpacity = math.clamp(v, 0.02, 0.95)
    if Library._bgImageLabel then
        Library._bgImageLabel.ImageTransparency = 1 - Library.BgImageOpacity
    end
end

function Library:SetNotifySide(lado)
    Library.NotifySide = tostring(lado or "Right")
    if Library.RFWindow and Library.RFWindow.SetNotifySide then
        Library.RFWindow:SetNotifySide(Library.NotifySide)
    end
end

function Library:SetDPIScale(escalaPct)
    local n = tonumber(escalaPct) or 100
    if n <= 4 then n = n * 100 end
    Library.DPIScale = math.clamp(n / 100, 0.5, 2)
    if Library.RFWindow and Library.RFWindow.SetDPIScale then
        Library.RFWindow:SetDPIScale(n)
    end
    if Library._overlayScale then
        Library._overlayScale.Scale = Library.DPIScale
    end
end

function Library:ChangeCursorIcon(icone)
    if Library._cursorImage then
        local str = tostring(icone or "")
        if str ~= "" and tonumber(str) then
            str = "rbxassetid://" .. str
        end
        Library._cursorImage.Image = str
    end
end

function Library:ChangeCursorIconSize(tamUDim2)
    if Library._cursorHolder and typeof(tamUDim2) == "UDim2" then
        Library._cursorHolder.Size = tamUDim2
    end
end

function Library:ChangeCursorIconColor(cor)
    if Library._cursorImage and typeof(cor) == "Color3" then
        Library._cursorImage.ImageColor3 = cor
    end
end

function Library:RefreshPlayerDropdowns()
    for _, reg in ipairs(Library._playerDropdowns) do
        if reg and reg.dd and reg.dd.Display then
            reg.dd:Display()
        end
    end
end

function Library:ResetCursorIcon()
    if Library._cursorImage then
        Library._cursorImage.Image = "rbxassetid://10889650707"
        Library._cursorImage.ImageColor3 = Color3.new(1, 1, 1)
    end
    if Library._cursorHolder then
        Library._cursorHolder.Size = UDim2.fromOffset(20, 20)
    end
end

function Library:Notify(tituloOuTabela, descOuTempo, tempoOpcional)
    if Library.Unloaded or not Library.RFWindow then return nil end

    local titulo = "Brazuka"
    local conteudo = ""
    local duracao = 5
    local icone = ICONE_BRASIL
    local somId = nil
    local volume = 1

    if type(tituloOuTabela) == "table" then
        titulo = tostring(tituloOuTabela.Title or tituloOuTabela.title or "Brazuka")
        conteudo = tostring(tituloOuTabela.Description or tituloOuTabela.Content or tituloOuTabela.Text or "")
        duracao = if tituloOuTabela.Persist then math.huge else (tonumber(tituloOuTabela.Time or tituloOuTabela.Duration) or 5)
        icone = tituloOuTabela.Icon or tituloOuTabela.BigIcon or ICONE_BRASIL
        somId = tituloOuTabela.SoundId
        volume = tonumber(tituloOuTabela.Volume) or 1
    else
        if type(descOuTempo) == "string" then
            titulo = tostring(tituloOuTabela or "Brazuka")
            conteudo = descOuTempo
            duracao = tonumber(tempoOpcional) or 5
        else
            conteudo = tostring(tituloOuTabela or "")
            duracao = tonumber(descOuTempo) or 5
        end
    end

    if somId and somId ~= "" and somId ~= 0 then
        task.spawn(function()
            local s = Instance.new("Sound")
            local sStr = tostring(somId)
            if tonumber(sStr) then
                sStr = "rbxassetid://" .. sStr
            end
            s.SoundId = sStr
            s.Volume = math.clamp(volume, 0, 10)
            s.Parent = SoundService
            pcall(function() s:Play() end)
            s.Ended:Once(function() pcall(function() s:Destroy() end) end)
            task.delay(8, function() if s and s.Parent then pcall(function() s:Destroy() end) end end)
        end)
    end

    local notifSirius = Library.RFWindow:Notify({
        title = titulo,
        content = conteudo,
        icon = icone,
        duration = duracao,
    })

    return {
        ChangeDescription = function(_, novoTexto)
            if notifSirius and notifSirius.descriptionLabel then
                notifSirius.descriptionLabel.Text = tostring(novoTexto or "")
            end
        end,
        Destroy = function()
            if notifSirius and notifSirius._dismiss then
                task.spawn(notifSirius._dismiss, notifSirius)
            end
        end,
    }
end

local function tornarArrastavel(guiObj, alcaInput)
    alcaInput = alcaInput or guiObj
    local arrastando = false
    local inicioMouse = Vector2.zero
    local inicioPos = UDim2.new()
    local connRender = nil
    local conns = {}

    local function pararArrasto()
        arrastando = false
        if connRender then
            connRender:Disconnect()
            connRender = nil
        end
    end

    table.insert(conns, Library:GiveSignal(alcaInput.InputBegan:Connect(function(inp, gpe)
        if gpe then return end
        if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
            arrastando = true
            inicioMouse = UserInputService:GetMouseLocation()
            inicioPos = guiObj.Position
            if connRender then connRender:Disconnect() end
            connRender = Library:GiveSignal(RunService.RenderStepped:Connect(function()
                if not arrastando or Library.Unloaded or not guiObj.Parent then
                    pararArrasto()
                    return
                end
                local delta = (UserInputService:GetMouseLocation() - inicioMouse) / math.max(Library.DPIScale, 0.5)
                local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080)
                local absTam = guiObj.AbsoluteSize
                local nx = inicioPos.X.Offset + delta.X
                local ny = inicioPos.Y.Offset + delta.Y
                if inicioPos.X.Scale == 0 and inicioPos.Y.Scale == 0 then
                    local minX = guiObj.AnchorPoint.X * absTam.X + 4
                    local maxX = math.max(minX, vp.X - (1 - guiObj.AnchorPoint.X) * absTam.X - 4)
                    local minY = guiObj.AnchorPoint.Y * absTam.Y + 4
                    local maxY = math.max(minY, vp.Y - (1 - guiObj.AnchorPoint.Y) * absTam.Y - 4)
                    nx = math.clamp(nx, minX, maxX)
                    ny = math.clamp(ny, minY, maxY)
                end
                guiObj.Position = UDim2.new(inicioPos.X.Scale, math.round(nx), inicioPos.Y.Scale, math.round(ny))
            end))
        end
    end)))

    table.insert(conns, Library:GiveSignal(UserInputService.InputEnded:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
            pararArrasto()
        end
    end)))

    table.insert(conns, Library:GiveSignal(UserInputService.WindowFocusReleased:Connect(pararArrasto)))

    return function()
        pararArrasto()
        for _, c in ipairs(conns) do
            pcall(function() c:Disconnect() end)
        end
        table.clear(conns)
    end
end

local function criarCartaoFlutuanteSirius(nome, tamanhoInicial, posicaoInicial)
    local pai = Library.OverlayRoot or Library.ScreenGui
    local quadro = Instance.new("Frame")
    quadro.Name = nome
    quadro.BackgroundColor3 = Library.Scheme.BackgroundColor
    quadro.BackgroundTransparency = 0.06
    quadro.BorderSizePixel = 0
    quadro.Size = tamanhoInicial
    quadro.Position = posicaoInicial
    quadro.ZIndex = 900
    quadro.Parent = pai

    local canto = Instance.new("UICorner")
    canto.CornerRadius = UDim.new(0, math.max(8, Library.CornerRadius))
    canto.Parent = quadro

    local grad = Instance.new("UIGradient")
    grad.Rotation = 270
    grad.Color = ColorSequence.new(Library.Scheme.BackgroundColor, Library.Scheme.MainColor)
    grad.Parent = quadro

    local borda = Instance.new("UIStroke")
    borda.Color = Library.Scheme.OutlineColor
    borda.Transparency = 0.25
    borda.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    borda.Parent = quadro

    local barra = Instance.new("Frame")
    barra.Name = "Accent"
    barra.BackgroundColor3 = Library.Scheme.AccentColor
    barra.BorderSizePixel = 0
    barra.Size = UDim2.new(0, 3, 1, -12)
    barra.Position = UDim2.new(0, 6, 0.5, 0)
    barra.AnchorPoint = Vector2.new(0, 0.5)
    barra.ZIndex = 902
    barra.Parent = quadro
    local cantoBarra = Instance.new("UICorner")
    cantoBarra.CornerRadius = UDim.new(1, 0)
    cantoBarra.Parent = barra

    local reg = { Frame = quadro, Corner = canto, Grad = grad, Stroke = borda, AccentBar = barra }
    table.insert(Library.FloatingFrames, reg)
    return quadro, reg
end

function Library:AddDraggableLabel(textoInicial, iconeOpcional)
    local quadro, reg = criarCartaoFlutuanteSirius(
        "SiriusFloatingLabel",
        UDim2.fromOffset(0, 32),
        UDim2.fromOffset(16, 62)
    )
    quadro.AutomaticSize = Enum.AutomaticSize.XY

    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 16)
    pad.PaddingRight = UDim.new(0, 14)
    pad.PaddingTop = UDim.new(0, 7)
    pad.PaddingBottom = UDim.new(0, 7)
    pad.Parent = quadro

    local lista = Instance.new("UIListLayout")
    lista.FillDirection = Enum.FillDirection.Horizontal
    lista.VerticalAlignment = Enum.VerticalAlignment.Center
    lista.Padding = UDim.new(0, 8)
    lista.SortOrder = Enum.SortOrder.LayoutOrder
    lista.Parent = quadro

    if iconeOpcional then
        local img = Instance.new("ImageLabel")
        img.BackgroundTransparency = 1
        img.Size = UDim2.fromOffset(18, 18)
        img.LayoutOrder = 1
        img.ZIndex = 902
        img.Image = type(iconeOpcional) == "number" and ("rbxassetid://" .. tostring(iconeOpcional)) or tostring(iconeOpcional)
        img.Parent = quadro
        local icCorner = Instance.new("UICorner")
        icCorner.CornerRadius = UDim.new(0, 5)
        icCorner.Parent = img
    end

    local txt = Instance.new("TextLabel")
    txt.BackgroundTransparency = 1
    txt.AutomaticSize = Enum.AutomaticSize.XY
    txt.Size = UDim2.fromOffset(0, 16)
    txt.RichText = true
    txt.FontFace = Library.Scheme.Font
    txt.TextColor3 = Library.Scheme.FontColor
    txt.TextSize = 14
    txt.TextXAlignment = Enum.TextXAlignment.Left
    txt.TextYAlignment = Enum.TextYAlignment.Center
    txt.Text = tostring(textoInicial or "")
    txt.LayoutOrder = 2
    txt.ZIndex = 902
    txt.Parent = quadro
    reg.Title = txt

    tornarArrastavel(quadro, quadro)

    local obj = { Label = quadro, TextLabel = txt }
    function obj:SetText(novoTexto)
        txt.Text = tostring(novoTexto or "")
    end
    function obj:SetVisible(visivel)
        quadro.Visible = visivel == true
    end
    function obj:Destroy()
        pcall(function() quadro:Destroy() end)
    end
    return obj
end

-- =========================================================================
-- COMPONENTE REUTILIZÁVEL: MobileActionButton (DESIGN PRÓPRIO + TEMA + ANEL 2S)
-- =========================================================================
local TEMPO_HOLD_EDICAO_MOBILE = 2.0

local function obterRaizMobile()
    return Library.MobileButtonsRoot or Library.OverlayRoot or Library.ScreenGui
end

local function obterMetricasRaizMobile()
    local cam = workspace.CurrentCamera
    local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720)
    local raiz = obterRaizMobile()
    local rootPos = Vector2.zero
    local rootSize = vp
    if raiz and raiz.AbsoluteSize.X > 0 and raiz.AbsoluteSize.Y > 0 then
        rootPos = raiz.AbsolutePosition
        rootSize = raiz.AbsoluteSize
    end
    return vp, rootPos, rootSize
end

local function calcularDiametroBotaoMobile()
    local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
    return math.clamp(math.round(math.min(vp.X, vp.Y) * 0.11), 44, 54)
end

local function obterAreaSeguraMobile(diametro)
    local vp, rootPos, rootSize = obterMetricasRaizMobile()
    local okInset, topInset, bottomInset = pcall(function() return GuiService:GetGuiInset() end)
    topInset = (okInset and typeof(topInset) == "Vector2") and topInset or Vector2.new(0, 58)
    bottomInset = (okInset and typeof(bottomInset) == "Vector2") and bottomInset or Vector2.zero

    local raio = diametro * 0.5
    local minAbsX = math.max(rootPos.X, 0) + 12 + raio
    local maxAbsX = math.min(rootPos.X + rootSize.X, vp.X) - 12 - raio
    local topoReal = math.max(rootPos.Y + 10, math.max(topInset.Y, 36) + 14)
    local baseReal = math.min(rootPos.Y + rootSize.Y, vp.Y - bottomInset.Y) - 12
    local minAbsY = topoReal + raio
    local maxAbsY = baseReal - raio

    if maxAbsX < minAbsX then
        local midX = vp.X * 0.5
        minAbsX, maxAbsX = midX, midX
    end
    if maxAbsY < minAbsY then
        local midY = vp.Y * 0.5
        minAbsY, maxAbsY = midY, midY
    end
    return minAbsX, maxAbsX, minAbsY, maxAbsY, vp, rootPos
end

local function clampCentroSeguroMobile(cx, cy, diametro)
    local minX, maxX, minY, maxY = obterAreaSeguraMobile(diametro)
    return math.clamp(cx, minX, maxX), math.clamp(cy, minY, maxY)
end

local function centroAbsParaUDim2(absX, absY)
    local _, rootPos = obterMetricasRaizMobile()
    return UDim2.fromOffset(math.round(absX - rootPos.X), math.round(absY - rootPos.Y))
end

local function udim2ParaCentroAbs(posUDim)
    local vp, rootPos, rootSize = obterMetricasRaizMobile()
    local lx = posUDim.X.Scale * rootSize.X + posUDim.X.Offset
    local ly = posUDim.Y.Scale * rootSize.Y + posUDim.Y.Offset
    return rootPos.X + lx, rootPos.Y + ly, vp
end

local function resolverIconeLucideMobile(nomeIcone)
    if type(nomeIcone) ~= "string" or nomeIcone == "" then
        nomeIcone = "circle-dot"
    end
    if nomeIcone:sub(1, 13) == "rbxassetid://" or nomeIcone:sub(1, 11) == "rbxthumb://" or nomeIcone:sub(1, 9) == "rbxasset://" then
        return { Url = nomeIcone, ImageRectSize = Vector2.zero, ImageRectOffset = Vector2.zero }
    end
    if Lucide and Lucide.GetAsset then
        local ok, dados = pcall(Lucide.GetAsset, nomeIcone)
        if ok and dados and dados.Url then
            return dados
        end
        local okFb, fb = pcall(Lucide.GetAsset, "circle-dot")
        if okFb and fb and fb.Url then
            return fb
        end
    end
    return nil
end

-- Reservas geométricas seguras (sem ler, clonar ou modificar botões do Roblox) + outros botões criados pelo script
local function coletarZonasExclusaoMobile(ignorarBtnObj, incluirReservaNativa)
    local zonas = {}
    local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
    local ehTouchOuCompacto = Library.IsMobile or UserInputService.TouchEnabled or vp.X <= 1150

    local function registrarRet(x1, y1, x2, y2)
        zonas[#zonas + 1] = {
            x1 = x1,
            y1 = y1,
            x2 = x2,
            y2 = y2,
            cx = (x1 + x2) * 0.5,
            cy = (y1 + y2) * 0.5,
        }
    end

    if incluirReservaNativa and ehTouchOuCompacto then
        -- Reserva geométrica aproximada para joystick (canto inf. esquerdo) e ações/pulo nativos (canto inf. direito)
        registrarRet(0, math.max(0, vp.Y - 205), math.min(vp.X * 0.30, 215), vp.Y)
        registrarRet(math.max(0, vp.X - math.min(vp.X * 0.25, 200)), math.max(0, vp.Y - 195), vp.X, vp.Y)
    end

    for _, outro in ipairs(Library._mobileButtonsAtivos) do
        if outro ~= ignorarBtnObj and outro.Button and outro.Button.Parent and outro.Button.Visible then
            local bPos, bSize = outro.Button.AbsolutePosition, outro.Button.AbsoluteSize
            if bSize.X > 0 and bSize.Y > 0 then
                registrarRet(bPos.X - 8, bPos.Y - 8, bPos.X + bSize.X + 8, bPos.Y + bSize.Y + 8)
            end
        end
    end

    return zonas
end

local function colideCentroComZonas(cx, cy, diametro, zonas)
    local raio = diametro * 0.5
    local x1, y1 = cx - raio, cy - raio
    local x2, y2 = cx + raio, cy + raio
    for _, z in ipairs(zonas) do
        if x1 < z.x2 and x2 > z.x1 and y1 < z.y2 and y2 > z.y1 then
            return true
        end
    end
    return false
end

local function encontrarPosicaoLivreMobile(alvoX, alvoY, diametro, ignorarBtnObj, incluirReservaNativa)
    local zonas = coletarZonasExclusaoMobile(ignorarBtnObj, incluirReservaNativa == true)
    local minX, maxX, minY, maxY = obterAreaSeguraMobile(diametro)
    local cx = math.clamp(alvoX, minX, maxX)
    local cy = math.clamp(alvoY, minY, maxY)
    if not colideCentroComZonas(cx, cy, diametro, zonas) then
        return cx, cy
    end

    local passoRaio = 12
    local maxRaio = math.max(maxX - minX, maxY - minY) + diametro * 2
    for raioBusca = passoRaio, maxRaio, passoRaio do
        local passosAngulo = raioBusca <= 96 and 16 or 24
        for i = 0, passosAngulo - 1 do
            local ang = (i / passosAngulo) * math.pi * 2
            local candX = math.clamp(cx + math.cos(ang) * raioBusca, minX, maxX)
            local candY = math.clamp(cy + math.sin(ang) * raioBusca, minY, maxY)
            if not colideCentroComZonas(candX, candY, diametro, zonas) then
                return candX, candY
            end
        end
    end
    return cx, cy
end

local function calcularPosicaoAutoMobile(diametro, ignorarBtnObj)
    local zonas = coletarZonasExclusaoMobile(ignorarBtnObj, true)
    local minX, maxX, minY, maxY, vp = obterAreaSeguraMobile(diametro)
    local ehTouchOuCompacto = Library.IsMobile or UserInputService.TouchEnabled or vp.X <= 1150

    local espaco = diametro + 12
    local candidatos = {}

    -- Arco elegante no canto inferior direito respeitando a reserva geométrica nativa
    local centroArcoX = vp.X - (ehTouchOuCompacto and 115 or 72)
    local centroArcoY = vp.Y - (ehTouchOuCompacto and 105 or 78)
    for _, raio in ipairs({ espaco * 1.65, espaco * 2.65, espaco * 3.65 }) do
        for _, angDeg in ipairs({ 172, 148, 198, 124, 218, 102 }) do
            local ang = math.rad(angDeg)
            candidatos[#candidatos + 1] = Vector2.new(
                centroArcoX + math.cos(ang) * raio,
                centroArcoY - math.sin(ang) * raio * 0.88
            )
        end
    end

    local baseGridX = vp.X - (ehTouchOuCompacto and 240 or 110)
    local baseGridY = vp.Y - 64
    for col = 0, 5 do
        for lin = 0, 3 do
            candidatos[#candidatos + 1] = Vector2.new(baseGridX - col * espaco, baseGridY - lin * espaco)
        end
    end

    for _, cand in ipairs(candidatos) do
        if cand.X >= minX and cand.X <= maxX and cand.Y >= minY and cand.Y <= maxY then
            if not colideCentroComZonas(cand.X, cand.Y, diametro, zonas) then
                return cand.X, cand.Y
            end
        end
    end

    return encontrarPosicaoLivreMobile(baseGridX, baseGridY, diametro, ignorarBtnObj, true)
end

local function atualizarLayoutResponsivoMobile()
    local diam = calcularDiametroBotaoMobile()
    local minX, maxX, minY, maxY, vp = obterAreaSeguraMobile(diam)
    for _, btnObj in ipairs(Library._mobileButtonsAtivos) do
        if btnObj and btnObj.Button and btnObj.Button.Parent and btnObj._normPos then
            btnObj.Button.Size = UDim2.fromOffset(diam, diam)
            local alvoX = btnObj._normPos.x * vp.X
            local alvoY = btnObj._normPos.y * vp.Y
            local foraDosLimites = (alvoX < minX or alvoX > maxX or alvoY < minY or alvoY > maxY)
            local fx, fy = alvoX, alvoY
            if foraDosLimites or colideCentroComZonas(alvoX, alvoY, diam, coletarZonasExclusaoMobile(btnObj, false)) then
                fx, fy = encontrarPosicaoLivreMobile(alvoX, alvoY, diam, btnObj, false)
                btnObj._normPos = { x = fx / math.max(vp.X, 1), y = fy / math.max(vp.Y, 1) }
            end
            btnObj.Button.Position = centroAbsParaUDim2(fx, fy)
        end
    end
end

local function desligarMonitorViewportMobile()
    for _, c in ipairs(Library._mobileViewportConns) do
        pcall(function() c:Disconnect() end)
    end
    table.clear(Library._mobileViewportConns)
    Library._mobileResizeMonitorAtivo = false
end

local function garantirMonitorViewportMobile()
    if Library._mobileResizeMonitorAtivo then return end
    Library._mobileResizeMonitorAtivo = true

    local connCamProp = nil
    local function vincularCamera(cam)
        if connCamProp then
            pcall(function() connCamProp:Disconnect() end)
            connCamProp = nil
        end
        if cam then
            connCamProp = Library:GiveSignal(cam:GetPropertyChangedSignal("ViewportSize"):Connect(atualizarLayoutResponsivoMobile))
            table.insert(Library._mobileViewportConns, connCamProp)
        end
    end

    vincularCamera(workspace.CurrentCamera)
    table.insert(Library._mobileViewportConns, Library:GiveSignal(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        if not Library.Unloaded and #Library._mobileButtonsAtivos > 0 then
            vincularCamera(workspace.CurrentCamera)
            atualizarLayoutResponsivoMobile()
        end
    end)))
end

local function tentarPulsoTatilMobile()
    pcall(function()
        if HapticService and HapticService:IsVibrationSupported(Enum.UserInputType.Gamepad1) then
            HapticService:SetMotor(Enum.UserInputType.Gamepad1, Enum.VibrationMotor.Small, 0.35)
            task.delay(0.06, function()
                pcall(function()
                    HapticService:SetMotor(Enum.UserInputType.Gamepad1, Enum.VibrationMotor.Small, 0)
                end)
            end)
        end
    end)
end

function Library:DestroyAllMobileButtons()
    local copia = table.clone(Library._mobileButtonsAtivos)
    for _, btnObj in ipairs(copia) do
        if btnObj and btnObj.Destroy then
            pcall(btnObj.Destroy, btnObj)
        end
    end
    table.clear(Library._mobileButtonsAtivos)
    desligarMonitorViewportMobile()
end

