    leftArc.Size = UDim2.new(2, -8, 1, -8)
    leftArc.BackgroundTransparency = 1
    leftArc.BorderSizePixel = 0
    leftArc.Parent = leftClip
    local leftCorner = Instance.new("UICorner")
    leftCorner.CornerRadius = UDim.new(1, 0)
    leftCorner.Parent = leftArc
    local leftStroke = Instance.new("UIStroke")
    leftStroke.Thickness = 3.6
    leftStroke.Transparency = 0
    leftStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    leftStroke.Parent = leftArc
    local leftGrad = Instance.new("UIGradient")
    leftGrad.Transparency = transparenciaMeioArco
    leftGrad.Rotation = 180
    leftGrad.Parent = leftStroke

    -- Ícone gráfico branco centralizado
    local iconImg = Instance.new("ImageLabel")
    iconImg.Name = "Icon"
    iconImg.BackgroundTransparency = 1
    iconImg.BorderSizePixel = 0
    iconImg.AnchorPoint = Vector2.new(0.5, 0.5)
    iconImg.Position = UDim2.fromScale(0.5, 0.5)
    iconImg.Size = UDim2.fromScale(0.52, 0.52)
    iconImg.ScaleType = Enum.ScaleType.Fit
    iconImg.ImageColor3 = Color3.new(1, 1, 1)
    iconImg.ImageTransparency = 0.04
    iconImg.ZIndex = 6
    iconImg.Parent = btn

    -- Indicador sutil de Toggle ativo
    local activeDot = Instance.new("Frame")
    activeDot.Name = "ActiveDot"
    activeDot.AnchorPoint = Vector2.new(0.5, 1)
    activeDot.Position = UDim2.new(0.5, 0, 1, -5)
    activeDot.Size = UDim2.fromOffset(6, 6)
    activeDot.BorderSizePixel = 0
    activeDot.Visible = false
    activeDot.ZIndex = 7
    activeDot.Parent = btn
    local activeDotCorner = Instance.new("UICorner")
    activeDotCorner.CornerRadius = UDim.new(1, 0)
    activeDotCorner.Parent = activeDot

    -- Selo de bloqueio para estado Indisponível
    local lockBadge = Instance.new("ImageLabel")
    lockBadge.Name = "LockBadge"
    lockBadge.BackgroundTransparency = 1
    lockBadge.BorderSizePixel = 0
    lockBadge.AnchorPoint = Vector2.new(1, 1)
    lockBadge.Position = UDim2.new(1, -2, 1, -2)
    lockBadge.Size = UDim2.fromOffset(15, 15)
    lockBadge.ScaleType = Enum.ScaleType.Fit
    lockBadge.ImageColor3 = Color3.fromRGB(248, 113, 113)
    lockBadge.Visible = false
    lockBadge.ZIndex = 8
    lockBadge.Parent = btn
    local lockInf = resolverIconeLucideMobile("lock")
    if lockInf then
        lockBadge.Image = lockInf.Url
        lockBadge.ImageRectOffset = lockInf.ImageRectOffset or Vector2.zero
        lockBadge.ImageRectSize = lockInf.ImageRectSize or Vector2.zero
    end

    local function atualizarProgressoAnel(p)
        local frac = math.clamp(p, 0, 1)
        local angTotal = frac * 360
        rightGrad.Rotation = math.clamp(angTotal, 0, 180)
        leftGrad.Rotation = math.clamp(angTotal, 180, 360)
    end
    atualizarProgressoAnel(0)

    local function aplicarIcone(novoIcone)
        local inf = resolverIconeLucideMobile(novoIcone or "circle-dot")
        if inf then
            iconImg.Image = inf.Url
            iconImg.ImageRectOffset = inf.ImageRectOffset or Vector2.zero
            iconImg.ImageRectSize = inf.ImageRectSize or Vector2.zero
            iconImg.Visible = true
        else
            iconImg.Visible = false
        end
    end
    aplicarIcone(iconeNome)

    local btnObj = setmetatable({
        Id = idBotao,
        Name = nomeBotao,
        Button = btn,
        Body = body,
        IconLabel = iconImg,
        ProgressRing = progressRing,
        _normPos = nil,
    }, MobileActionButton)

    local enabledState = (cfg.Enabled ~= false)
    local lockedState = (cfg.Locked == true)
    local activeState = (cfg.Active == true)
    local visualState = "Normal"
    local destruirFlag = false
    local activeInput = nil
    local pressToken = 0
    local holdCompleted = false
    local draggingNow = false
    local movedTooMuch = false
    local startPointer = Vector2.zero
    local lastPointer = Vector2.zero
    local pressStartClock = 0
    local startCenter = Vector2.zero
    local curCenter = Vector2.zero

    local connChanged = nil
    local connEnded = nil
    local connHoldRender = nil
    local tweenScale = nil
    local tweenPos = nil
    local tweenGlow = nil
    local tweenShadow = nil
    local tweenRingFade = nil

    local function atualizarTemaVisual()
        local esq = Library.Scheme or {}
        local acc = esq.AccentColor or VERDE_BRASIL
        local cinzaBase = Color3.fromRGB(108, 112, 120)
        local topoCor = Color3.fromRGB(142, 146, 154)
        local baseCor = Color3.fromRGB(78, 82, 90)
        local bordaNormal = Color3.fromRGB(58, 62, 70)

        body.BackgroundColor3 = cinzaBase
        bodyGrad.Color = ColorSequence.new(topoCor, baseCor)
        glowHalo.BackgroundColor3 = acc
        rightStroke.Color = acc
        leftStroke.Color = acc
        activeDot.BackgroundColor3 = acc
        innerRimStroke.Color = Color3.fromRGB(238, 240, 245)

        if visualState == "Pressed" or visualState == "Loading" or visualState == "ReadyToMove" or visualState == "Dragging" or visualState == "Released" then
            outerStroke.Color = acc
        elseif visualState == "Unavailable" then
            outerStroke.Color = Color3.fromRGB(220, 65, 65)
        elseif modo == "Toggle" and activeState then
            outerStroke.Color = acc
        else
            outerStroke.Color = bordaNormal
        end
    end

    local function aplicarEstadoVisual(novoEstado)
        if lockedState then
            visualState = "Unavailable"
        elseif not enabledState then
            visualState = "Disabled"
        else
            visualState = novoEstado or "Normal"
        end

        atualizarTemaVisual()
        lockBadge.Visible = (visualState == "Unavailable")
        activeDot.Visible = (modo == "Toggle" and activeState and visualState ~= "Unavailable")

        if tweenScale then pcall(function() tweenScale:Cancel() end) end
        if tweenGlow then pcall(function() tweenGlow:Cancel() end) end
        if tweenShadow then pcall(function() tweenShadow:Cancel() end) end

        if visualState == "Unavailable" then
            body.BackgroundTransparency = 0.42
            outerStroke.Thickness = 1.6
            outerStroke.Transparency = 0.28
            iconImg.ImageTransparency = 0.52
            shadow.BackgroundTransparency = 0.72
            shadow.Position = UDim2.new(0.5, 0, 0.5, 2)
            glowHalo.BackgroundTransparency = 1
            tweenScale = TweenService:Create(btnScale, TweenInfo.new(0.14, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Scale = 0.96 })
            tweenScale:Play()
        elseif visualState == "Disabled" then
            body.BackgroundTransparency = 0.48
            outerStroke.Thickness = 1.6
            outerStroke.Transparency = 0.45
            iconImg.ImageTransparency = 0.55
            shadow.BackgroundTransparency = 0.78
            shadow.Position = UDim2.new(0.5, 0, 0.5, 2)
            glowHalo.BackgroundTransparency = 1
            tweenScale = TweenService:Create(btnScale, TweenInfo.new(0.14, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Scale = 1 })
            tweenScale:Play()
        elseif visualState == "Pressed" or visualState == "Loading" then
            body.BackgroundTransparency = 0.18
            outerStroke.Thickness = 2.4
            outerStroke.Transparency = 0.05
            iconImg.ImageTransparency = 0
            tweenShadow = TweenService:Create(shadow, TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                BackgroundTransparency = 0.56,
                Position = UDim2.new(0.5, 0, 0.5, 2),
            })
            tweenShadow:Play()
            tweenGlow = TweenService:Create(glowHalo, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundTransparency = 0.86 })
            tweenGlow:Play()
            tweenScale = TweenService:Create(btnScale, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 0.94 })
            tweenScale:Play()
        elseif visualState == "ReadyToMove" or visualState == "Dragging" then
            local scaleAlvo = (visualState == "Dragging") and 1.15 or 1.11
            body.BackgroundTransparency = 0.14
            outerStroke.Thickness = 2.6
            outerStroke.Transparency = 0
            iconImg.ImageTransparency = 0
            tweenShadow = TweenService:Create(shadow, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                BackgroundTransparency = (visualState == "Dragging") and 0.40 or 0.46,
                Position = UDim2.new(0.5, 0, 0.5, (visualState == "Dragging") and 6 or 5),
            })
            tweenShadow:Play()
            tweenGlow = TweenService:Create(glowHalo, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                BackgroundTransparency = (visualState == "Dragging") and 0.68 or 0.74,
            })
            tweenGlow:Play()
            tweenScale = TweenService:Create(btnScale, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = scaleAlvo })
            tweenScale:Play()
        elseif visualState == "Released" then
            body.BackgroundTransparency = 0.22
            outerStroke.Thickness = 2.3
            outerStroke.Transparency = 0.06
            iconImg.ImageTransparency = 0
            glowHalo.BackgroundTransparency = 0.72
            tweenGlow = TweenService:Create(glowHalo, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { BackgroundTransparency = 1 })
            tweenGlow:Play()
            tweenShadow = TweenService:Create(shadow, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                BackgroundTransparency = 0.64,
                Position = UDim2.new(0.5, 0, 0.5, 3),
            })
            tweenShadow:Play()
            tweenScale = TweenService:Create(btnScale, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 })
            tweenScale:Play()
        else
            body.BackgroundTransparency = 0.28
            outerStroke.Thickness = 2.2
            outerStroke.Transparency = (modo == "Toggle" and activeState) and 0.06 or 0.14
            iconImg.ImageTransparency = 0.03
            tweenShadow = TweenService:Create(shadow, TweenInfo.new(0.16, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                BackgroundTransparency = 0.64,
                Position = UDim2.new(0.5, 0, 0.5, 3),
            })
            tweenShadow:Play()
            tweenGlow = TweenService:Create(glowHalo, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { BackgroundTransparency = 1 })
            tweenGlow:Play()
            tweenScale = TweenService:Create(btnScale, TweenInfo.new(0.16, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Scale = 1 })
            tweenScale:Play()
        end
    end

    local function pararLoopAnel(suave)
        if connHoldRender then
            pcall(function() connHoldRender:Disconnect() end)
            connHoldRender = nil
        end
        if tweenRingFade then
            pcall(function() tweenRingFade:Cancel() end)
            tweenRingFade = nil
        end
        if suave and progressRing.Visible then
            local tk = pressToken
            tweenRingFade = TweenService:Create(progressRing, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { GroupTransparency = 1 })
            tweenRingFade.Completed:Once(function()
                if pressToken == tk or activeInput == nil then
                    progressRing.Visible = false
                    progressRing.GroupTransparency = 0
                    atualizarProgressoAnel(0)
                end
            end)
            tweenRingFade:Play()
        else
            progressRing.Visible = false
            progressRing.GroupTransparency = 0
            atualizarProgressoAnel(0)
        end
    end

    table.insert(Library._mobileButtonsAtivos, btnObj)
    garantirMonitorViewportMobile()

    -- Posicionamento inicial inteligente ou restauração da posição personalizada
    local cxInicial, cyInicial
    local _, _, _, _, vpInicial = obterAreaSeguraMobile(diametro)
    if typeof(cfg.Position) == "UDim2" then
        local px, py = udim2ParaCentroAbs(cfg.Position)
        cxInicial, cyInicial = encontrarPosicaoLivreMobile(px, py, diametro, btnObj)
    elseif type(cfg.Position) == "table" and type(cfg.Position.x) == "number" and type(cfg.Position.y) == "number" then
        cxInicial, cyInicial = encontrarPosicaoLivreMobile(cfg.Position.x * vpInicial.X, cfg.Position.y * vpInicial.Y, diametro, btnObj)
    else
        cxInicial, cyInicial = calcularPosicaoAutoMobile(diametro, btnObj)
    end
    btn.Position = centroAbsParaUDim2(cxInicial, cyInicial)
    btnObj._normPos = { x = cxInicial / math.max(vpInicial.X, 1), y = cyInicial / math.max(vpInicial.Y, 1) }
    startCenter = Vector2.new(cxInicial, cyInicial)
    curCenter = startCenter
    aplicarEstadoVisual("Normal")

    local function cancelarTweens()
        if tweenScale then pcall(function() tweenScale:Cancel() end) tweenScale = nil end
        if tweenPos then pcall(function() tweenPos:Cancel() end) tweenPos = nil end
        if tweenGlow then pcall(function() tweenGlow:Cancel() end) tweenGlow = nil end
        if tweenShadow then pcall(function() tweenShadow:Cancel() end) tweenShadow = nil end
        if tweenRingFade then pcall(function() tweenRingFade:Cancel() end) tweenRingFade = nil end
    end

    local function desconectarEntrada()
        if connChanged then pcall(function() connChanged:Disconnect() end) connChanged = nil end
        if connEnded then pcall(function() connEnded:Disconnect() end) connEnded = nil end
    end

    local function finalizarEntrada(permitirAcao)
        local eraEdicao = holdCompleted or draggingNow
        local podeExecutar = permitirAcao and (not eraEdicao) and (not movedTooMuch) and enabledState and (not lockedState)
        activeInput = nil
        holdCompleted = false
        draggingNow = false
        movedTooMuch = false
        pressToken += 1
        desconectarEntrada()
        pararLoopAnel(true)

        if eraEdicao then
            local diamAtual = btn.AbsoluteSize.X > 0 and btn.AbsoluteSize.X or calcularDiametroBotaoMobile()
            local fx, fy = encontrarPosicaoLivreMobile(curCenter.X, curCenter.Y, diamAtual, btnObj, false)
            local vpAtual = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
            curCenter = Vector2.new(fx, fy)
            btnObj._normPos = { x = fx / math.max(vpAtual.X, 1), y = fy / math.max(vpAtual.Y, 1) }
            local destPos = centroAbsParaUDim2(fx, fy)
            if tweenPos then pcall(function() tweenPos:Cancel() end) end
            tweenPos = TweenService:Create(btn, TweenInfo.new(0.14, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Position = destPos })
            tweenPos:Play()
            if type(onPositionChanged) == "function" then
                pcall(onPositionChanged, destPos, btnObj._normPos)
            end
            aplicarEstadoVisual("Released")
            task.delay(0.22, function()
                if not destruirFlag and activeInput == nil then
                    aplicarEstadoVisual("Normal")
                end
            end)
        else
            aplicarEstadoVisual("Normal")
            if podeExecutar and type(aoClicar) == "function" then
                task.spawn(aoClicar)
            end
        end
    end

    local function entradaCorresponde(inp)
        if not activeInput then return false end
        if inp == activeInput then return true end
        if activeInput.UserInputType == Enum.UserInputType.MouseButton1 and inp.UserInputType == Enum.UserInputType.MouseMovement then
            return true
        end
        return false
    end

    local cBegan = Library:GiveSignal(btn.InputBegan:Connect(function(inp, gpe)
        if gpe or destruirFlag or activeInput ~= nil then return end
        if not enabledState or lockedState then return end
        local ehMouse = (inp.UserInputType == Enum.UserInputType.MouseButton1)
        local ehToque = (inp.UserInputType == Enum.UserInputType.Touch)
        if not (ehMouse or ehToque) then return end

        activeInput = inp
        pressToken += 1
        local tokenLocal = pressToken
        holdCompleted = false
        draggingNow = false
        movedTooMuch = false
        pressStartClock = os.clock()
        startPointer = Vector2.new(inp.Position.X, inp.Position.Y)
        lastPointer = startPointer
        local limiteMov = ehToque and 26 or 14

        local diamAtual = btn.AbsoluteSize.X > 0 and btn.AbsoluteSize.X or calcularDiametroBotaoMobile()
        local bPos, bSize = btn.AbsolutePosition, btn.AbsoluteSize
        if bSize.X > 0 and bSize.Y > 0 then
            startCenter = Vector2.new(bPos.X + bSize.X * 0.5, bPos.Y + bSize.Y * 0.5)
        else
            local ux, uy = udim2ParaCentroAbs(btn.Position)
            startCenter = Vector2.new(ux, uy)
        end
        curCenter = startCenter

        aplicarEstadoVisual("Loading")
        if tweenRingFade then pcall(function() tweenRingFade:Cancel() end) tweenRingFade = nil end
        progressRing.GroupTransparency = 0
        progressRing.Visible = true
        atualizarProgressoAnel(0)

        -- Loop temporário apenas enquanto pressionado para preencher o anel exatamente nos 2.0 segundos
        if connHoldRender then pcall(function() connHoldRender:Disconnect() end) end
        connHoldRender = RunService.Heartbeat:Connect(function()
            if destruirFlag or activeInput ~= inp or pressToken ~= tokenLocal or holdCompleted or movedTooMuch then
                if connHoldRender then pcall(function() connHoldRender:Disconnect() end) connHoldRender = nil end
                return
            end
            local elapsed = os.clock() - pressStartClock
            local progresso = math.clamp(elapsed / TEMPO_HOLD_EDICAO_MOBILE, 0, 1)
            atualizarProgressoAnel(progresso)
            if progresso >= 1 then
                holdCompleted = true
                startPointer = lastPointer
                startCenter = curCenter
                if connHoldRender then pcall(function() connHoldRender:Disconnect() end) connHoldRender = nil end
                pararLoopAnel(false)
                tentarPulsoTatilMobile()
                aplicarEstadoVisual("ReadyToMove")
            end
        end)

        desconectarEntrada()
        connChanged = UserInputService.InputChanged:Connect(function(movInp)
            if destruirFlag or activeInput ~= inp or not entradaCorresponde(movInp) then return end
            local ptr = Vector2.new(movInp.Position.X, movInp.Position.Y)
            lastPointer = ptr
            local delta = ptr - startPointer
            if not holdCompleted then
                if delta.Magnitude > limiteMov then
                    movedTooMuch = true
                    pressToken += 1
                    pararLoopAnel(true)
                    aplicarEstadoVisual("Normal")
                end
            else
                if not draggingNow then
                    draggingNow = true
                    aplicarEstadoVisual("Dragging")
                end
                local cx, cy = clampCentroSeguroMobile(startCenter.X + delta.X, startCenter.Y + delta.Y, diamAtual)
                curCenter = Vector2.new(cx, cy)
                if tweenPos then pcall(function() tweenPos:Cancel() end) tweenPos = nil end
                btn.Position = centroAbsParaUDim2(cx, cy)
            end
        end)

        connEnded = UserInputService.InputEnded:Connect(function(endInp)
            if destruirFlag or endInp ~= activeInput then return end
            finalizarEntrada(true)
        end)
    end))

    local cFocus = Library:GiveSignal(UserInputService.WindowFocusReleased:Connect(function()
        if activeInput then
            finalizarEntrada(false)
        end
    end))

    function btnObj:SetText(novoNome)
        btnObj.Name = tostring(novoNome or "")
    end

    function btnObj:SetIcon(novoIcone)
        aplicarIcone(novoIcone)
    end

    function btnObj:SetActive(ativo)
        activeState = (ativo == true)
        if activeInput == nil then
            aplicarEstadoVisual("Normal")
        end
    end

    function btnObj:SetEnabled(ativo)
        enabledState = (ativo == true)
        if not enabledState and activeInput then
            finalizarEntrada(false)
        else
            aplicarEstadoVisual("Normal")
        end
    end

    function btnObj:SetLocked(bloqueado)
        lockedState = (bloqueado == true)
        if lockedState and activeInput then
            finalizarEntrada(false)
        else
            aplicarEstadoVisual("Normal")
        end
    end

    function btnObj:ApplyTheme()
        atualizarTemaVisual()
    end

    function btnObj:GetNormalizedPos()
        return btnObj._normPos and { x = btnObj._normPos.x, y = btnObj._normPos.y } or nil
    end

    function btnObj:SetNormalizedPos(norm)
        if type(norm) ~= "table" or type(norm.x) ~= "number" or type(norm.y) ~= "number" then return end
        local diam = calcularDiametroBotaoMobile()
        local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
        local fx, fy = encontrarPosicaoLivreMobile(norm.x * vp.X, norm.y * vp.Y, diam, btnObj)
        curCenter = Vector2.new(fx, fy)
        btnObj._normPos = { x = fx / math.max(vp.X, 1), y = fy / math.max(vp.Y, 1) }
        btn.Size = UDim2.fromOffset(diam, diam)
        btn.Position = centroAbsParaUDim2(fx, fy)
    end

    function btnObj:Reposition()
        local ux, uy, vp = udim2ParaCentroAbs(btn.Position)
        local diam = calcularDiametroBotaoMobile()
        local fx, fy = encontrarPosicaoLivreMobile(ux, uy, diam, btnObj)
        curCenter = Vector2.new(fx, fy)
        btnObj._normPos = { x = fx / math.max(vp.X, 1), y = fy / math.max(vp.Y, 1) }
        btn.Size = UDim2.fromOffset(diam, diam)
        btn.Position = centroAbsParaUDim2(fx, fy)
    end

    function btnObj:Destroy()
        if destruirFlag then return end
        destruirFlag = true
        activeInput = nil
        pressToken += 1
        desconectarEntrada()
        pararLoopAnel(false)
        cancelarTweens()
        pcall(function() cBegan:Disconnect() end)
        pcall(function() cFocus:Disconnect() end)
        local idx = table.find(Library._mobileButtonsAtivos, btnObj)
        if idx then table.remove(Library._mobileButtonsAtivos, idx) end
        if #Library._mobileButtonsAtivos == 0 then
            desligarMonitorViewportMobile()
        end
        pcall(function() btn:Destroy() end)
    end

    return btnObj
end

function Library:AddDraggableButton(configOuNome, aoClicar)
    return MobileActionButton.new(configOuNome, aoClicar)
end

local function construirPainelAtalhosSirius()
    local quadro, reg = criarCartaoFlutuanteSirius(
        "SiriusKeybindsList",
        UDim2.fromOffset(210, 0),
        UDim2.new(0, 12, 0.5, 0)
    )
    quadro.AnchorPoint = Vector2.new(0, 0.5)
    quadro.AutomaticSize = Enum.AutomaticSize.XY
    quadro.Visible = false

    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 16)
    pad.PaddingRight = UDim.new(0, 14)
    pad.PaddingTop = UDim.new(0, 10)
    pad.PaddingBottom = UDim.new(0, 10)
    pad.Parent = quadro

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.Padding = UDim.new(0, 6)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Parent = quadro

    local titulo = Instance.new("TextLabel")
    titulo.BackgroundTransparency = 1
    titulo.AutomaticSize = Enum.AutomaticSize.XY
    titulo.Size = UDim2.fromOffset(160, 16)
    titulo.FontFace = Font.new(Library.Scheme.Font.Family, Enum.FontWeight.SemiBold)
    titulo.TextColor3 = Library.Scheme.FontColor
    titulo.TextSize = 14
    titulo.TextXAlignment = Enum.TextXAlignment.Left
    titulo.Text = "<b>Atalhos Ativos</b>"
    titulo.RichText = true
    titulo.LayoutOrder = 1
    titulo.ZIndex = 902
    titulo.Parent = quadro
    reg.Title = titulo

    local cont = Instance.new("Frame")
    cont.Name = "Container"
    cont.BackgroundTransparency = 1
    cont.AutomaticSize = Enum.AutomaticSize.XY
    cont.Size = UDim2.fromOffset(160, 0)
    cont.LayoutOrder = 2
    cont.Parent = quadro

    local lista = Instance.new("UIListLayout")
    lista.FillDirection = Enum.FillDirection.Vertical
    lista.Padding = UDim.new(0, 4)
    lista.SortOrder = Enum.SortOrder.LayoutOrder
    lista.Parent = cont

    tornarArrastavel(quadro, quadro)
    Library:GiveSignal(quadro:GetPropertyChangedSignal("Visible"):Connect(function()
        if quadro.Visible then
            for _, refreshFn in ipairs(Library.KeybindEntries) do
                pcall(refreshFn)
            end
        end
    end))
    Library.KeybindFrame = quadro
    Library.KeybindContainer = cont
end

local TECLAS_ESPECIAIS = {
    [Enum.UserInputType.MouseButton1] = "MB1",
    [Enum.UserInputType.MouseButton2] = "MB2",
    [Enum.UserInputType.MouseButton3] = "MB3",
}

local function resolverEnumTecla(val)
    if typeof(val) == "EnumItem" then return val end
    if type(val) ~= "string" or val == "" or val == "None" or val == "Unknown" then
        return nil
    end
    if val == "MB1" then return Enum.UserInputType.MouseButton1 end
    if val == "MB2" then return Enum.UserInputType.MouseButton2 end
    if val == "MB3" then return Enum.UserInputType.MouseButton3 end
    local ok, kc = pcall(function() return Enum.KeyCode[val] end)
    if ok and kc then return kc end
    local ok2, ut = pcall(function() return Enum.UserInputType[val] end)
    if ok2 and ut then return ut end
    return nil
end

local function nomeTeclaCurto(val)
    if typeof(val) == "EnumItem" then
        if val == Enum.KeyCode.Unknown then return "None" end
        return TECLAS_ESPECIAIS[val] or val.Name
    end
    if type(val) == "string" and val ~= "" then return val end
    return "None"
end

-- Anexar métodos de construção de elementos (compatíveis 100% com Runtime/Configs/Themes sobre Sirius Gen2)
local function anexarConstrutoresContainer(objetoContainer, obterGrupoSirius, estaVisivelPai)
    local function obterBarraAcessorios(rfElem, baseRightOffset)
        if not rfElem or not rfElem.main then return nil end
        local existing = rfElem.main:FindFirstChild("InlineAccessories")
        if existing then return existing end
        local bar = Instance.new("Frame")
        bar.Name = "InlineAccessories"
        bar.AnchorPoint = Vector2.new(1, 0.5)
        bar.Position = UDim2.new(1, -baseRightOffset, 0, rfElem._customHeight and 16 or 20)
        bar.AutomaticSize = Enum.AutomaticSize.X
        bar.Size = UDim2.fromOffset(0, 24)
        bar.BackgroundTransparency = 1
        bar.BorderSizePixel = 0
        bar.ZIndex = 20
        bar.Parent = rfElem.main

        local lay = Instance.new("UIListLayout")
        lay.FillDirection = Enum.FillDirection.Horizontal
        lay.HorizontalAlignment = Enum.HorizontalAlignment.Right
        lay.VerticalAlignment = Enum.VerticalAlignment.Center
        lay.Padding = UDim.new(0, 5)
        lay.SortOrder = Enum.SortOrder.LayoutOrder
        lay.Parent = bar

        local function ajustarTitulo()
            if rfElem.container and rfElem.container.Parent then
                rfElem.container.Size = UDim2.new(1, -(baseRightOffset + 24 + bar.AbsoluteSize.X), 0, 20)
            end
        end
        Library:GiveSignal(bar:GetPropertyChangedSignal("AbsoluteSize"):Connect(ajustarTitulo))
        task.defer(ajustarTitulo)
        return bar
    end

    local function garantirDespachanteAtalhos(w)
        if not w or w._keybinds then return end
        w._keybinds = {}
        w:Connect(UserInputService.InputBegan, function(p, q)
            if q then return end
            local rec = w._recordingKeybind
            if rec then
                if rec.recording then rec:_capture(p) end
                return
            end
            for _, kb in ipairs(w._keybinds) do
                if not kb.locked and kb:_matches(p) then
                    if kb.hold then
                        w:_siaUsed(kb, "press")
                        kb:_beginHold(p)
                    else
                        w:_runGuarded(kb, kb.callback, kb.value)
                    end
                end
            end
        end)
    end

    local function criarKeyPickerInterno(indice, info, elementoPai, rotuloAncora)
        info = type(info) == "table" and info or {}
        local texto = tostring(info.Text or (rotuloAncora and rotuloAncora._rawText) or (elementoPai and elementoPai.Text) or indice or "Atalho")
        local modoInicial = tostring(info.Mode or "Toggle")
        local enumInicial = resolverEnumTecla(info.Default)
        local nomeInicial = nomeTeclaCurto(enumInicial or info.Default)

        local ehMenuKey = (indice == "menukey")
        local grupoAlvo = obterGrupoSirius()

        -- Se foi encadeado em um AddLabel simples (sem Idx salvo em Labels), destruir o Text duplicado em vez de só ocultar
        if rotuloAncora and rotuloAncora._isPlainAnchor and rotuloAncora._rfText then
            local tInst = rotuloAncora._rfText
            rotuloAncora._rfText = nil
            local idxEl = table.find(grupoAlvo.elements, tInst)
            if idxEl then table.remove(grupoAlvo.elements, idxEl) end
            if Library.RFWindow and tInst.main then
                Library.RFWindow:DestroySubtree(tInst.main)
            end
        end

        local kp = {
            Type = "KeyPicker",
            Text = texto,
            Value = nomeInicial,
            DisplayValue = nomeInicial,
            Mode = modoInicial,
            Modifiers = {},
            Toggled = false,
            SyncToggleState = info.SyncToggleState == true,
            NoUI = info.NoUI == true,
            MenuVisible = not info.NoUI,
            Callback = info.Callback,
            ChangedCallback = info.ChangedCallback,
            Changed = info.Changed,
            Disabled = false,
        }

        -- Criar linha no painel flutuante de atalhos somente quando NoUI ~= true
        local linhaAtalho = nil
        if Library.KeybindContainer and not kp.NoUI then
            linhaAtalho = Instance.new("TextLabel")
            linhaAtalho.BackgroundTransparency = 1
            linhaAtalho.AutomaticSize = Enum.AutomaticSize.XY
            linhaAtalho.Size = UDim2.fromOffset(0, 15)
            linhaAtalho.RichText = true
            linhaAtalho.FontFace = Library.Scheme.Font
            linhaAtalho.TextSize = 13
            linhaAtalho.TextXAlignment = Enum.TextXAlignment.Left
            linhaAtalho.TextColor3 = Library.Scheme.FontColor
            linhaAtalho.TextTransparency = 0.35
            linhaAtalho.Visible = kp.MenuVisible
            linhaAtalho.ZIndex = 903
            linhaAtalho.Parent = Library.KeybindContainer
            Library:AddToRegistry(linhaAtalho, { TextColor3 = "FontColor", FontFace = "Font" })
        end

        local function atualizarLinhaPainel(forcar)
            if not linhaAtalho then return end
            if not forcar and Library.KeybindFrame and not Library.KeybindFrame.Visible then
                return
            end
            local modoPt = PTBR_MODOS_ATALHO[kp.Mode] or kp.Mode
            local ativo = kp:GetState()
            linhaAtalho.Text = string.format("[%s] %s (%s)", kp.Value == "None" and "-" or kp.Value, kp.Text, modoPt)
            linhaAtalho.TextColor3 = ativo and Library.Scheme.AccentColor or Library.Scheme.FontColor
            linhaAtalho.TextTransparency = ativo and 0 or 0.4
            linhaAtalho.Visible = (kp.MenuVisible ~= false) and (not kp.NoUI)
        end

        if linhaAtalho then
            table.insert(Library.KeybindEntries, function()
                atualizarLinhaPainel(true)
            end)
        end

        function kp:GetState()
            if kp.Mode == "Always" then return true end
            if kp.Mode == "Toggle" then return kp.Toggled == true end
            if kp.Value == "None" then return false end
            local kc = resolverEnumTecla(kp.Value)
            if not kc then return false end
            if kc.EnumType == Enum.KeyCode then
                return UserInputService:IsKeyDown(kc)
            elseif kc.EnumType == Enum.UserInputType then
                return UserInputService:IsMouseButtonPressed(kc)
            end
            return false
        end

        function kp:SetMenuVisibility(vis)
            kp.MenuVisible = vis == true
            atualizarLinhaPainel()
        end

        function kp:OnChanged(fn)
            kp.Changed = fn
        end

        function kp:RunChanged()
            local kc = resolverEnumTecla(kp.Value) or Enum.KeyCode.Unknown
            if kp.ChangedCallback then task.spawn(kp.ChangedCallback, kc) end
            if kp.Changed then task.spawn(kp.Changed, kc) end
        end

        local rfKeybind = nil
        local suprimirEventoSirius = false
        local keyBtn = nil
        local rfAdapter = nil

        function kp:Update()
            atualizarLinhaPainel()
            if keyBtn then
                keyBtn.Text = (kp.Value == "None" or kp.Value == "") and "None" or kp.Value
            end
            if ehMenuKey and Library.RFWindow then
                Library.RFWindow.settings.toggleKeybind = resolverEnumTecla(kp.Value) or Enum.KeyCode.Unknown
            end
        end

        local function dispararAcao(estado)
            if kp.Disabled or (elementoPai and elementoPai.Disabled) then return end
            if kp.SyncToggleState and elementoPai and elementoPai.Type == "Toggle" then
                elementoPai:SetValue(estado)
            else
                if kp.Callback then
                    task.spawn(kp.Callback, estado)
                end
            end
            atualizarLinhaPainel()
        end

        local function aoDispararAtalho()
            if ehMenuKey then return end
            if kp.Mode == "Always" then return end
            if kp.Mode == "Toggle" then
                if kp.SyncToggleState and elementoPai and elementoPai.Type == "Toggle" then
                    kp.Toggled = not (elementoPai.Value == true)
                else
                    kp.Toggled = not kp.Toggled
                end
                dispararAcao(kp.Toggled)
            elseif kp.Mode == "Press" then
                kp.Toggled = true
                dispararAcao(true)
                kp.Toggled = false
            elseif kp.Mode == "Hold" then
                kp.Toggled = true
                dispararAcao(true)
                local alvoEnum = resolverEnumTecla(kp.Value)
                local connSoltar
                connSoltar = UserInputService.InputEnded:Connect(function(inp)
                    if not alvoEnum then
                        connSoltar:Disconnect()
                        return
                    end
                    if inp.KeyCode == alvoEnum or inp.UserInputType == alvoEnum then
                        connSoltar:Disconnect()
                        kp.Toggled = false
                        dispararAcao(false)
                    end
                end)
            end
        end

        local rfPai = elementoPai and elementoPai._rfElem
        if rfPai and rfPai.main and not ehMenuKey then
            local baseRight = (elementoPai.Type == "Toggle") and 72 or 14
            local bar = obterBarraAcessorios(rfPai, baseRight)

            keyBtn = Instance.new("TextButton")
            keyBtn.Name = "InlineKeybind_" .. tostring(indice or "KB")
            keyBtn.AutoButtonColor = false
            keyBtn.AutomaticSize = Enum.AutomaticSize.X
            keyBtn.Size = UDim2.fromOffset(36, 22)
            keyBtn.BackgroundColor3 = Library.Scheme.MainColor
            keyBtn.BackgroundTransparency = 0.08
            keyBtn.BorderSizePixel = 0
            keyBtn.FontFace = Library.Scheme.Font
            keyBtn.TextSize = 12
            keyBtn.TextColor3 = Library.Scheme.FontColor
            keyBtn.TextTruncate = Enum.TextTruncate.AtEnd
            keyBtn.Text = (kp.Value == "None" or kp.Value == "") and "None" or kp.Value
            keyBtn.LayoutOrder = 2
            keyBtn.ZIndex = 21
            keyBtn.Parent = bar

            local kbConstraint = Instance.new("UISizeConstraint")
            kbConstraint.MinSize = Vector2.new(34, 22)
            kbConstraint.MaxSize = Vector2.new(92, 22)
            kbConstraint.Parent = keyBtn

            local kbPad = Instance.new("UIPadding")
            kbPad.PaddingLeft = UDim.new(0, 7)
            kbPad.PaddingRight = UDim.new(0, 7)
            kbPad.Parent = keyBtn

            local kbCorner = Instance.new("UICorner")
            kbCorner.CornerRadius = UDim.new(1, 0)
            kbCorner.Parent = keyBtn

            local kbStroke = Instance.new("UIStroke")
            kbStroke.Color = Library.Scheme.OutlineColor
            kbStroke.Transparency = 0.2
            kbStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            kbStroke.Parent = keyBtn

            Library:AddToRegistry(keyBtn, { BackgroundColor3 = "MainColor", TextColor3 = "FontColor", FontFace = "Font" })
            Library:AddToRegistry(kbStroke, { Color = "OutlineColor" })

            local w = Library.RFWindow
            garantirDespachanteAtalhos(w)

            rfAdapter = {
                name = texto,
                value = enumInicial or Enum.KeyCode.Unknown,
                hold = false,
                locked = false,
                recording = false,
                window = w,
                callback = aoDispararAtalho,
                _matches = function(self, inp)
                    local v = self.value
                    if typeof(v) ~= "EnumItem" or v == Enum.KeyCode.Unknown then return false end
                    if v.EnumType == Enum.KeyCode then return inp.KeyCode == v end
                    if v.EnumType == Enum.UserInputType then return inp.UserInputType == v end
                    return false
                end,
                _stopRecording = function(self)
                    self.recording = false
                    if w and w._recordingKeybind == self then
                        task.defer(function()
                            if w._recordingKeybind == self then w._recordingKeybind = nil end
                        end)
                    end
                    keyBtn.Text = (kp.Value == "None" or kp.Value == "") and "None" or kp.Value
                    kbStroke.Color = Library.Scheme.OutlineColor
                end,
                _capture = function(self, inp)
                    local novo = nil
                    if inp.UserInputType == Enum.UserInputType.Keyboard then
                        if inp.KeyCode == Enum.KeyCode.Escape then self:_stopRecording() return end
                        if inp.KeyCode == Enum.KeyCode.Backspace then novo = Enum.KeyCode.Unknown else novo = inp.KeyCode end
                    elseif inp.UserInputType == Enum.UserInputType.MouseButton2 or inp.UserInputType == Enum.UserInputType.MouseButton3 then
                        novo = inp.UserInputType
                    end
                    if not novo then return end
                    self.value = novo
                    self:_stopRecording()
                    kp:SetValue(nomeTeclaCurto(novo))
                end,
                _beginHold = function() end,
            }
            if w and w._keybinds then
                table.insert(w._keybinds, rfAdapter)
            end

            Library:GiveSignal(keyBtn.MouseButton1Click:Connect(function()
                if rfAdapter.recording then
                    rfAdapter:_stopRecording()
                else
                    if w and w._recordingKeybind and w._recordingKeybind ~= rfAdapter and w._recordingKeybind._stopRecording then
                        w._recordingKeybind:_stopRecording()
                    end
                    rfAdapter.recording = true
                    if w then w._recordingKeybind = rfAdapter end
                    keyBtn.Text = "..."
                    kbStroke.Color = Library.Scheme.AccentColor
                end
            end))
        else
            rfKeybind = grupoAlvo:CreateKeybind({
                name = texto,
                value = enumInicial or Enum.KeyCode.Unknown,
                isMenuToggle = ehMenuKey,
                forgetState = true,
                hold = false,
                onChanged = function(novoEnum)
                    if suprimirEventoSirius then return end
                    kp.Value = nomeTeclaCurto(novoEnum)
                    kp.DisplayValue = kp.Value
                    kp:Update()
                    kp:RunChanged()
                    if ehMenuKey and Library.RFWindow and Library.RFWindow.SaveSettings then
                        pcall(Library.RFWindow.SaveSettings, Library.RFWindow)
                    end
                end,
                callback = aoDispararAtalho,
            })
        end

        function kp:SetValue(dados)
            local novaTecla = dados
            if type(dados) == "table" then
                novaTecla = dados[1]
                if dados[2] then kp.Mode = tostring(dados[2]) end
                if type(dados[3]) == "table" then kp.Modifiers = table.clone(dados[3]) end
            end
            local enumResolvido = resolverEnumTecla(novaTecla)
            kp.Value = nomeTeclaCurto(enumResolvido or novaTecla)
            kp.DisplayValue = kp.Value
            if rfAdapter then
                rfAdapter.value = enumResolvido or Enum.KeyCode.Unknown
            end
            if rfKeybind then
                suprimirEventoSirius = true
                rfKeybind:Set(enumResolvido or Enum.KeyCode.Unknown, true)
                suprimirEventoSirius = false
            end
            kp:Update()
            kp:RunChanged()
        end

        function kp:SetVisible(vis)
            if keyBtn then
                keyBtn.Visible = vis == true
            elseif rfKeybind and rfKeybind.SetVisible then
                rfKeybind:SetVisible(vis == true)
            end
        end

        if elementoPai and elementoPai.Type == "Toggle" and kp.SyncToggleState then
            kp.Toggled = elementoPai.Value == true
        end
        kp:Update()

        if indice then
            Opcoes[indice] = kp
        end
        return elementoPai or kp
    end

    local function criarColorPickerInterno(indice, info, rotuloAncora, elementoPai)
        info = type(info) == "table" and info or {}
        local titulo = tostring(info.Title or info.Text or (rotuloAncora and rotuloAncora._rawText) or indice or "Cor")
        local corPadrao = typeof(info.Default) == "Color3" and info.Default or Color3.new(1, 1, 1)
        local transpPadrao = tonumber(info.Transparency) or 0

        local grupoAlvo = obterGrupoSirius()
        if rotuloAncora and rotuloAncora._isPlainAnchor and rotuloAncora._rfText then
            local tInst = rotuloAncora._rfText
            rotuloAncora._rfText = nil
            local idxEl = table.find(grupoAlvo.elements, tInst)
            if idxEl then table.remove(grupoAlvo.elements, idxEl) end
            if Library.RFWindow and tInst.main then
                Library.RFWindow:DestroySubtree(tInst.main)
            end
        end

        local suprimir = false
        local cp = {
            Type = "ColorPicker",
            Title = titulo,
            Value = corPadrao,
            Default = corPadrao,
            Transparency = transpPadrao,
            Callback = info.Callback,
            Changed = info.Changed,
        }

        local rfPicker = nil
        local swatchBtn = nil
        local rfPai = elementoPai and elementoPai._rfElem

        local function atualizarSwatch()
            if swatchBtn then
                swatchBtn.BackgroundColor3 = cp.Value
                swatchBtn.BackgroundTransparency = math.clamp(cp.Transparency * 0.75, 0, 0.85)
            end
        end

        local function criarSiriusPicker(ocultoInicial)
            if rfPicker then return rfPicker end
            rfPicker = grupoAlvo:CreateColorPicker({
                name = titulo,
                color = cp.Value,
                alpha = 1 - math.clamp(cp.Transparency, 0, 1),
                forgetState = true,
                callback = function(cor, alfa)
                    cp.Value = cor
                    if type(alfa) == "number" then
                        cp.Transparency = math.clamp(1 - alfa, 0, 1)
                    end
                    atualizarSwatch()
                    if suprimir then return end
                    if cp.Callback then task.spawn(cp.Callback, cp.Value) end
                    if cp.Changed then task.spawn(cp.Changed, cp.Value) end
                end,
            })
            if ocultoInicial and rfPicker and rfPicker.main then
                if rfPai and rfPai.main then
                    rfPicker.main.LayoutOrder = (rfPai.main.LayoutOrder or 0) + 1
                end
                rfPicker.main.Visible = false
                if rfPicker._close then
                    local origClose = rfPicker._close
                    rfPicker._close = function(self)
                        origClose(self)
                        task.delay(0.32, function()
                            if not self._isOpen and self.main then
                                self.main.Visible = false
                            end
                        end)
                    end
                end
            end
            return rfPicker
        end

        if rfPai and rfPai.main then
            local bar = obterBarraAcessorios(rfPai, 72)
            swatchBtn = Instance.new("TextButton")
            swatchBtn.Name = "InlineSwatch_" .. tostring(indice or "CP")
            swatchBtn.AutoButtonColor = false
            swatchBtn.Size = UDim2.fromOffset(24, 18)
            swatchBtn.Text = ""
            swatchBtn.BorderSizePixel = 0
            swatchBtn.LayoutOrder = 1
            swatchBtn.ZIndex = 21
            swatchBtn.Parent = bar

            local swCorner = Instance.new("UICorner")
            swCorner.CornerRadius = UDim.new(0, 6)
            swCorner.Parent = swatchBtn

            local swStroke = Instance.new("UIStroke")
            swStroke.Color = Library.Scheme.OutlineColor
            swStroke.Transparency = 0.15
            swStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            swStroke.Parent = swatchBtn

            Library:AddToRegistry(swStroke, { Color = "OutlineColor" })
            atualizarSwatch()

            Library:GiveSignal(swatchBtn.MouseButton1Click:Connect(function()
                local pk = criarSiriusPicker(true)
                if not pk then return end
                if pk._isOpen then
                    pk:_close()
                else
                    if pk.main then pk.main.Visible = true end
                    pk:_open()
                end
            end))
        else
            criarSiriusPicker(false)
        end

        function cp:OnChanged(fn) cp.Changed = fn end
        function cp:RunChanged()
            if cp.Callback then task.spawn(cp.Callback, cp.Value) end
            if cp.Changed then task.spawn(cp.Changed, cp.Value) end
        end
        function cp:SetValueRGB(cor, transp)
            if typeof(cor) == "Color3" then
                cp.Value = cor
            end
            if type(transp) == "number" then
                cp.Transparency = math.clamp(transp, 0, 1)
            end
            atualizarSwatch()
            if rfPicker then
                suprimir = true
                if type(transp) == "number" then
                    rfPicker:SetAlpha(1 - cp.Transparency, true)
                end
                rfPicker:Set(cp.Value, true)
                suprimir = false
            end
            cp:RunChanged()
        end
        function cp:SetValue(cor, transp)
            cp:SetValueRGB(cor, transp)
        end
        function cp:SetVisible(vis)
            if swatchBtn then
                swatchBtn.Visible = vis == true
            end
            if rfPicker and rfPicker.SetVisible then
                if vis == false and rfPicker._close and rfPicker._isOpen then rfPicker:_close() end
                if not swatchBtn then rfPicker:SetVisible(vis == true) end
            end
        end

        if indice then
            Opcoes[indice] = cp
        end
        return cp
    end

    function objetoContainer:AddDivider(texto)
        local g = obterGrupoSirius()
        local div = g:CreateDivider({
            text = type(texto) == "string" and texto or "",
            line = true,
        })
        return div
    end

    function objetoContainer:AddLabel(indiceOuTexto, infoOuQuebra)
        local indice = nil
        local texto = ""
        if type(indiceOuTexto) == "table" then
            texto = tostring(indiceOuTexto.Text or "")
        elseif type(infoOuQuebra) == "table" then
            indice = tostring(indiceOuTexto)
            texto = tostring(infoOuQuebra.Text or "")
        else
            texto = tostring(indiceOuTexto or "")
        end

        local g = obterGrupoSirius()
        local rfText = g:CreateText({
            name = "",
            text = texto,
        })
        if rfText and rfText.body then
            rfText.body.TextTransparency = 0.12
        end

        local rot = {
            Type = "Label",
            Text = texto,
            _rawText = texto,
            _isPlainAnchor = (indice == nil),
            _rfText = rfText,
            TextLabel = rfText and rfText.body or Instance.new("TextLabel"),
            Destroyed = false,
        }

        function rot:SetText(novoTexto)
            rot.Text = tostring(novoTexto or "")
            if rfText then
                rfText:Set(rot.Text)
                if rfText.body and estaVisivelPai() then
                    rfText.body.TextTransparency = 0.12
                end
            end
        end

        function rot:SetVisible(vis)
            if rfText and rfText.SetVisible then
                rfText:SetVisible(vis == true)
            end
        end

        function rot:AddColorPicker(cIdx, cInfo)
            criarColorPickerInterno(cIdx, cInfo, rot)
            return rot
        end

        function rot:AddKeyPicker(kIdx, kInfo)
            criarKeyPickerInterno(kIdx, kInfo, nil, rot)
            return rot
        end

        if indice then
            Rotulos[indice] = rot
        end
        return rot
    end

    function objetoContainer:AddImage(indice, info)
        info = type(info) == "table" and info or {}
        local altura = tonumber(info.Height) or 76
        local g = obterGrupoSirius()

        local holder = Instance.new("Frame")
        holder.Name = tostring(indice or "ImageHolder")
        holder.BackgroundTransparency = 1
        holder.Size = UDim2.new(1, -20, 0, altura + 8)
        holder.LayoutOrder = (#g.elements + 1) * 10
        holder.Parent = g.tabPage

        local img = Instance.new("ImageLabel")
        img.Name = "Image"
        img.AnchorPoint = Vector2.new(0.5, 0.5)
        img.Position = UDim2.fromScale(0.5, 0.5)
        img.Size = UDim2.fromOffset(altura, altura)
        img.BackgroundTransparency = info.BackgroundTransparency or 1
        img.Image = tostring(info.Image or "")
        img.ImageColor3 = info.Color or Color3.new(1, 1, 1)
        img.ImageTransparency = info.Transparency or 0
        img.ScaleType = info.ScaleType or Enum.ScaleType.Fit
        img.Parent = holder

        local canto = Instance.new("UICorner")
        canto.CornerRadius = UDim.new(1, 0)
        canto.Parent = img

        local borda = Instance.new("UIStroke")
        borda.Color = Library.Scheme.AccentColor
        borda.Transparency = 0.35
        borda.Thickness = 1.5
        borda.Parent = img
        Library:AddToRegistry(borda, { Color = "AccentColor" })

        return {
            Holder = holder,
            ImageLabel = img,
            Image = img.Image,
            Destroyed = false,
            Destroy = function(self)
                self.Destroyed = true
                pcall(function() holder:Destroy() end)
            end,
        }
    end

    function objetoContainer:AddButton(textoOuInfo, funcaoCallback)
        local info = {}
        if type(textoOuInfo) == "table" then
            info = textoOuInfo
        else
            info = { Text = textoOuInfo, Func = funcaoCallback }
        end

        local texto = tostring(info.Text or "Botão")
        local cb = info.Func or info.Callback or function() end
        local dica = info.Tooltip
        local icone = info.Icon
        local g = obterGrupoSirius()

        local btnWrapper = {
            Type = "Button",
            Text = texto,
            DoubleClick = info.DoubleClick == true,
            Disabled = info.Disabled == true,
            _confirmando = false,
            _rfElem = nil,
        }

        local rfBtn
        rfBtn = g:CreateButton({
            name = texto,
            description = dica,
            icon = icone,
            callback = function()
                if btnWrapper.Disabled then return end
                if btnWrapper.DoubleClick and not btnWrapper._confirmando then
                    btnWrapper._confirmando = true
                    if rfBtn and rfBtn.title then
                        rfBtn.title.Text = "Tem certeza? (Clique novamente)"
                    end
                    task.delay(2.5, function()
                        if btnWrapper._confirmando then
                            btnWrapper._confirmando = false
                            if rfBtn and rfBtn.title then
                                rfBtn.title.Text = btnWrapper.Text
                            end
                        end
                    end)
                    return
                end
                if btnWrapper._confirmando then
                    btnWrapper._confirmando = false
                    if rfBtn and rfBtn.title then
                        rfBtn.title.Text = btnWrapper.Text
                    end
                end
                cb()
            end,
        })
        btnWrapper._rfElem = rfBtn

        if btnWrapper.Disabled and rfBtn and rfBtn.Lock then
            rfBtn:Lock(info.DisabledTooltip)
        end

        function btnWrapper:SetText(novoTexto)
            btnWrapper.Text = tostring(novoTexto or "")
            if rfBtn and rfBtn.title then
                rfBtn.title.Text = btnWrapper.Text
            end
        end
        function btnWrapper:SetDisabled(desat)
            btnWrapper.Disabled = desat == true
            if rfBtn then
                if btnWrapper.Disabled then rfBtn:Lock(info.DisabledTooltip) else rfBtn:Unlock() end
            end
        end
        function btnWrapper:SetVisible(vis)
            if rfBtn and rfBtn.SetVisible then rfBtn:SetVisible(vis == true) end
        end
        function btnWrapper:AddKeyPicker(kIdx, kInfo)
            criarKeyPickerInterno(kIdx, kInfo, btnWrapper, nil)
            return btnWrapper
        end
        function btnWrapper:AddButton(subTextoOuInfo, subFunc)
            return objetoContainer:AddButton(subTextoOuInfo, subFunc)
        end
        function btnWrapper:AddTooltip() return btnWrapper end

        return btnWrapper
    end

    function objetoContainer:AddButtonRow(listaBotoes)
        if type(listaBotoes) ~= "table" or #listaBotoes == 0 then
            return {}
        end
        local g = obterGrupoSirius()
        local grupoLinha = g:CreateGroup({ direction = "row" })
        local itens = {}
        for _, bInfo in ipairs(listaBotoes) do
            if type(bInfo) == "table" then
                local texto = tostring(bInfo.Text or "Botão")
                local cb = bInfo.Func or bInfo.Callback or function() end
                local rfBtn = grupoLinha:CreateButton({
                    name = texto,
                    description = bInfo.Tooltip,
                    icon = bInfo.Icon,
                    callback = function()
                        cb()
                    end,
                })
                table.insert(itens, rfBtn)
            end
        end
        return itens
    end

    function objetoContainer:AddToggle(indice, info)
        info = type(info) == "table" and info or {}
        local texto = tostring(info.Text or indice or "Alternador")
        local padrao = info.Default == true
        local g = obterGrupoSirius()
        local suprimir = false

        local tog = {
            Type = "Toggle",
            Text = texto,
            Value = padrao,
            Default = padrao,
            Disabled = info.Disabled == true,
            Callback = info.Callback,
            Changed = info.Changed,
            _onChangedList = {},
            _syncedKeyPickers = {},
            _depListeners = {},
            _rfElem = nil,
        }

        local rfToggle = g:CreateToggle({
            name = texto,
            description = info.Tooltip,
            icon = info.Icon,
            value = padrao,
            forgetState = true,
            callback = function(val)
                tog.Value = val == true
                if suprimir then return end
                for _, kp in ipairs(tog._syncedKeyPickers) do
                    if kp.SyncToggleState then
                        kp.Toggled = tog.Value
                        kp:Update()
                    end
                end
                if tog.Callback then task.spawn(tog.Callback, tog.Value) end
                if tog.Changed then task.spawn(tog.Changed, tog.Value) end
                for _, fn in ipairs(tog._onChangedList) do task.spawn(fn, tog.Value) end
                for _, fn in ipairs(tog._depListeners) do pcall(fn) end
            end,
        })
        tog._rfElem = rfToggle

        if tog.Disabled and rfToggle and rfToggle.Lock then
            rfToggle:Lock(info.DisabledTooltip)
        end

        function tog:OnChanged(fn)
            if type(fn) == "function" then
                table.insert(tog._onChangedList, fn)
            end
        end
        function tog:RunChanged()
            if tog.Callback then task.spawn(tog.Callback, tog.Value) end
            if tog.Changed then task.spawn(tog.Changed, tog.Value) end
            for _, fn in ipairs(tog._onChangedList) do task.spawn(fn, tog.Value) end
            for _, fn in ipairs(tog._depListeners) do pcall(fn) end
        end
        function tog:SetValue(val)
            local b = val == true
            tog.Value = b
            if rfToggle then
                suprimir = true
                rfToggle:Set(b, true)
                suprimir = false
            end
            for _, kp in ipairs(tog._syncedKeyPickers) do
                if kp.SyncToggleState then
                    kp.Toggled = b
                    kp:Update()
                end
            end
            tog:RunChanged()
        end
        function tog:SetText(novoTexto)
            tog.Text = tostring(novoTexto or "")
            if rfToggle and rfToggle.title then
                rfToggle.title.Text = tog.Text
            end
        end
        function tog:SetDisabled(desat)
            tog.Disabled = desat == true
            if rfToggle then
                if tog.Disabled then rfToggle:Lock(info.DisabledTooltip) else rfToggle:Unlock() end
            end
        end
        function tog:SetVisible(vis)
            if rfToggle and rfToggle.SetVisible then rfToggle:SetVisible(vis == true) end
        end
        function tog:AddKeyPicker(kIdx, kInfo)
            criarKeyPickerInterno(kIdx, kInfo, tog, nil)
            if kIdx and Opcoes[kIdx] then
                Opcoes[kIdx]._parentToggle = tog
                table.insert(tog._syncedKeyPickers, Opcoes[kIdx])
            end
            return tog
        end
        function tog:AddColorPicker(cIdx, cInfo)
            criarColorPickerInterno(cIdx, cInfo, nil, tog)
            return tog
        end

        if indice then
            Alternadores[indice] = tog
        end
        if info.Visible == false then
            tog:SetVisible(false)
        end
        return tog
    end

    function objetoContainer:AddToggleSlider(togIdx, togInfo, sldIdx, sldInfo)
        togInfo = type(togInfo) == "table" and togInfo or {}
        sldInfo = type(sldInfo) == "table" and sldInfo or {}
        local textoTog = tostring(togInfo.Text or togIdx or "Função")
        local padraoTog = togInfo.Default == true
        local minV = tonumber(sldInfo.Min) or 0
        local maxV = tonumber(sldInfo.Max) or 100
        local arred = tonumber(sldInfo.Rounding) or 0
        local inc = 10 ^ (-math.clamp(arred, 0, 5))
        local padraoSld = math.clamp(tonumber(sldInfo.Default) or minV, math.min(minV, maxV), math.max(minV, maxV))
        local sufixo = tostring(sldInfo.Suffix or ""):gsub("^%s+", "")
        local g = obterGrupoSirius()
        local suprimirTog = false

        local tog = {
            Type = "Toggle",
            Text = textoTog,
            Value = padraoTog,
            Default = padraoTog,
            Disabled = togInfo.Disabled == true,
            Callback = togInfo.Callback,
            Changed = togInfo.Changed,
            _onChangedList = {},
            _syncedKeyPickers = {},
            _depListeners = {},
            _rfElem = nil,
        }

        local rfToggle = g:CreateToggle({
            name = textoTog,
            description = togInfo.Tooltip,
            icon = togInfo.Icon,
            value = padraoTog,
            forgetState = true,
            callback = function(val)
                tog.Value = val == true
                if suprimirTog then return end
                for _, kp in ipairs(tog._syncedKeyPickers) do
                    if kp.SyncToggleState then
                        kp.Toggled = tog.Value
                        kp:Update()
                    end
                end
                if tog.Callback then task.spawn(tog.Callback, tog.Value) end
                if tog.Changed then task.spawn(tog.Changed, tog.Value) end
                for _, fn in ipairs(tog._onChangedList) do task.spawn(fn, tog.Value) end
                for _, fn in ipairs(tog._depListeners) do pcall(fn) end
            end,
        })
        tog._rfElem = rfToggle

        if rfToggle and rfToggle.main then
            rfToggle._customHeight = 56
            rfToggle.main.Size = UDim2.new(1, -20, 0, 56)
            if rfToggle.container then
                rfToggle.container.AnchorPoint = Vector2.new(0, 0.5)
                rfToggle.container.Position = UDim2.new(0, 16, 0, 16)
            end
            if rfToggle.functionContainer then
                rfToggle.functionContainer.Position = UDim2.new(1, -15, 0, 16)
            end
            if rfToggle.interact then
                rfToggle.interact.AnchorPoint = Vector2.zero
                rfToggle.interact.Position = UDim2.fromScale(0, 0)
                rfToggle.interact.Size = UDim2.new(1, 0, 0, 32)
            end
        end

        local sld = {
            Type = "Slider",
            Text = tostring(sldInfo.Text or sldIdx or textoTog),
            Value = padraoSld,
            Default = padraoSld,
            Min = minV,
            Max = maxV,
            Rounding = arred,
            Disabled = sldInfo.Disabled == true,
            Callback = sldInfo.Callback,
            Changed = sldInfo.Changed,
        }

        local function formatarNum(n)
            local fmt = string.format("%." .. tostring(math.clamp(arred, 0, 5)) .. "f", n)
            return sufixo ~= "" and (fmt .. " " .. sufixo) or fmt
        end

        local sliderHost = Instance.new("Frame")
        sliderHost.Name = "InlineSlider"
        sliderHost.BackgroundTransparency = 1
        sliderHost.Position = UDim2.new(0, 14, 0, 34)
        sliderHost.Size = UDim2.new(1, -28, 0, 16)
        sliderHost.ZIndex = 12
        sliderHost.Parent = rfToggle.main

        local valLbl = Instance.new("TextLabel")
        valLbl.BackgroundTransparency = 1
        valLbl.AnchorPoint = Vector2.new(1, 0.5)
        valLbl.Position = UDim2.new(1, 0, 0.5, 0)
        valLbl.Size = UDim2.fromOffset(56, 16)
        valLbl.FontFace = Library.Scheme.Font
        valLbl.TextSize = 12
        valLbl.TextColor3 = Library.Scheme.FontColor
        valLbl.TextTransparency = 0.25
        valLbl.TextXAlignment = Enum.TextXAlignment.Right
        valLbl.TextTruncate = Enum.TextTruncate.AtEnd
        valLbl.Text = formatarNum(padraoSld)
        valLbl.ZIndex = 14
        valLbl.Parent = sliderHost
        Library:AddToRegistry(valLbl, { TextColor3 = "FontColor", FontFace = "Font" })

        local track = Instance.new("Frame")
        track.Name = "Track"
        track.AnchorPoint = Vector2.new(0, 0.5)
        track.Position = UDim2.new(0, 0, 0.5, 0)
        track.Size = UDim2.new(1, -62, 0, 8)
        track.BackgroundColor3 = Library.Scheme.OutlineColor
        track.BackgroundTransparency = 0.4
        track.BorderSizePixel = 0
        track.ZIndex = 13
        track.Parent = sliderHost
        local trCorner = Instance.new("UICorner")
        trCorner.CornerRadius = UDim.new(1, 0)
        trCorner.Parent = track
        Library:AddToRegistry(track, { BackgroundColor3 = "OutlineColor" })

        local fill = Instance.new("Frame")
        fill.Name = "Fill"
        fill.AnchorPoint = Vector2.new(0, 0.5)
        fill.Position = UDim2.fromScale(0, 0.5)
        fill.Size = UDim2.fromScale(0, 1)
        fill.BackgroundColor3 = Library.Scheme.AccentColor
        fill.BorderSizePixel = 0
        fill.ZIndex = 14
        fill.Parent = track
        local flCorner = Instance.new("UICorner")
        flCorner.CornerRadius = UDim.new(1, 0)
        flCorner.Parent = fill
        Library:AddToRegistry(fill, { BackgroundColor3 = "AccentColor" })

        local knob = Instance.new("Frame")
        knob.Name = "Knob"
        knob.AnchorPoint = Vector2.new(0.5, 0.5)
        knob.Position = UDim2.fromScale(1, 0.5)
        knob.Size = UDim2.fromOffset(13, 13)
        knob.BackgroundColor3 = Color3.new(1, 1, 1)
        knob.BorderSizePixel = 0
        knob.ZIndex = 16
        knob.Parent = fill
        local knCorner = Instance.new("UICorner")
        knCorner.CornerRadius = UDim.new(1, 0)
        knCorner.Parent = knob
        local knStroke = Instance.new("UIStroke")
        knStroke.Color = Library.Scheme.OutlineColor
        knStroke.Transparency = 0.25
        knStroke.Parent = knob

        local hit = Instance.new("TextButton")
        hit.BackgroundTransparency = 1
        hit.Text = ""
        hit.Size = UDim2.new(1, 6, 1, 8)
        hit.AnchorPoint = Vector2.new(0.5, 0.5)
        hit.Position = UDim2.fromScale(0.5, 0.5)
        hit.ZIndex = 18
        hit.Parent = track

        local function renderizarSlider(val)
            local span = math.max(maxV - minV, 1e-6)
            local pct = math.clamp((val - minV) / span, 0, 1)
            fill.Size = UDim2.fromScale(pct, 1)
            valLbl.Text = formatarNum(val)
        end
        renderizarSlider(padraoSld)

        local draggingSld = false
        local connSld = nil
        local function atualizarDoMouse()
            local wAbs = track.AbsoluteSize.X
            if wAbs <= 1 then return end
            local mx = UserInputService:GetMouseLocation().X
            local pct = math.clamp((mx - track.AbsolutePosition.X) / wAbs, 0, 1)
            local bruto = minV + pct * (maxV - minV)
            local snapped = math.clamp(minV + math.round((bruto - minV) / inc) * inc, minV, maxV)
            if snapped ~= sld.Value then
                sld.Value = snapped
                renderizarSlider(snapped)
                if sld.Callback then task.spawn(sld.Callback, snapped) end
                if sld.Changed then task.spawn(sld.Changed, snapped) end
            end
        end
        local function pararDragSld()
            draggingSld = false
            if connSld then connSld:Disconnect(); connSld = nil end
        end

        Library:GiveSignal(hit.InputBegan:Connect(function(inp)
            if sld.Disabled then return end
            if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                draggingSld = true
                atualizarDoMouse()
                if connSld then connSld:Disconnect() end
                connSld = Library:GiveSignal(RunService.RenderStepped:Connect(function()
                    if not draggingSld or Library.Unloaded or not track.Parent then pararDragSld() return end
                    atualizarDoMouse()
                end))
            end
        end))
        Library:GiveSignal(UserInputService.InputEnded:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                pararDragSld()
            end
        end))
        Library:GiveSignal(UserInputService.WindowFocusReleased:Connect(pararDragSld))

        function tog:OnChanged(fn)
            if type(fn) == "function" then table.insert(tog._onChangedList, fn) end
        end
        function tog:RunChanged()
            if tog.Callback then task.spawn(tog.Callback, tog.Value) end
            if tog.Changed then task.spawn(tog.Changed, tog.Value) end
            for _, fn in ipairs(tog._onChangedList) do task.spawn(fn, tog.Value) end
            for _, fn in ipairs(tog._depListeners) do pcall(fn) end
        end
        function tog:SetValue(val)
            local b = val == true
            tog.Value = b
            if rfToggle then
                suprimirTog = true
                rfToggle:Set(b, true)
                suprimirTog = false
            end
            for _, kp in ipairs(tog._syncedKeyPickers) do
                if kp.SyncToggleState then
                    kp.Toggled = b
                    kp:Update()
                end
            end
            tog:RunChanged()
        end
        function tog:SetText(novoTexto)
            tog.Text = tostring(novoTexto or "")
            if rfToggle and rfToggle.title then rfToggle.title.Text = tog.Text end
        end
        function tog:SetDisabled(desat)
            tog.Disabled = desat == true
            if rfToggle then
                if tog.Disabled then rfToggle:Lock(togInfo.DisabledTooltip) else rfToggle:Unlock() end
            end
        end
        function tog:SetVisible(vis)
            if rfToggle and rfToggle.SetVisible then rfToggle:SetVisible(vis == true) end
        end
        function tog:AddKeyPicker(kIdx, kInfo)
            criarKeyPickerInterno(kIdx, kInfo, tog, nil)
            if kIdx and Opcoes[kIdx] then
                Opcoes[kIdx]._parentToggle = tog
                table.insert(tog._syncedKeyPickers, Opcoes[kIdx])
            end
            return tog
        end
        function tog:AddColorPicker(cIdx, cInfo)
            criarColorPickerInterno(cIdx, cInfo, nil, tog)
            return tog
        end

        function sld:OnChanged(fn) sld.Changed = fn end
        function sld:RunChanged()
            if sld.Callback then task.spawn(sld.Callback, sld.Value) end
            if sld.Changed then task.spawn(sld.Changed, sld.Value) end
        end
        function sld:SetValue(val)
            local n = tonumber(val)
            if not n then return end
            n = math.clamp(n, math.min(minV, maxV), math.max(minV, maxV))
            sld.Value = n
            renderizarSlider(n)
            sld:RunChanged()
        end
        function sld:SetDisabled(desat) sld.Disabled = desat == true end
        function sld:SetVisible(vis)
            if sliderHost then sliderHost.Visible = vis == true end
        end

        if togIdx then Alternadores[togIdx] = tog end
        if sldIdx then Opcoes[sldIdx] = sld end
        if togInfo.Visible == false then tog:SetVisible(false) end
        return tog, sld
    end

    function objetoContainer:AddSlider(indice, info)
        info = type(info) == "table" and info or {}
        local texto = tostring(info.Text or indice or "Controle")
        local minV = tonumber(info.Min) or 0
        local maxV = tonumber(info.Max) or 100
        local arred = tonumber(info.Rounding) or 0
        local inc = 10 ^ (-math.clamp(arred, 0, 5))
        local padrao = math.clamp(tonumber(info.Default) or minV, math.min(minV, maxV), math.max(minV, maxV))
        local sufixo = tostring(info.Suffix or ""):gsub("^%s+", "")
        local g = obterGrupoSirius()
        local suprimir = false

        local sld = {
            Type = "Slider",
            Text = texto,
            Value = padrao,
            Default = padrao,
            Min = minV,
            Max = maxV,
            Rounding = arred,
            Disabled = info.Disabled == true,
            Callback = info.Callback,
            Changed = info.Changed,
        }

        local rfSlider = g:CreateSlider({
            name = texto,
            description = info.Tooltip,
            range = { minV, maxV },
            increment = inc,
            value = padrao,
            suffix = sufixo,
            compact = info.Compact == true,
            forgetState = true,
            callback = function(val)
                sld.Value = val
                if suprimir then return end
                if sld.Callback then task.spawn(sld.Callback, val) end
                if sld.Changed then task.spawn(sld.Changed, val) end
            end,
        })

        if sld.Disabled and rfSlider and rfSlider.Lock then
            rfSlider:Lock(info.DisabledTooltip)
        end

        function sld:OnChanged(fn) sld.Changed = fn end
        function sld:RunChanged()
            if sld.Callback then task.spawn(sld.Callback, sld.Value) end
            if sld.Changed then task.spawn(sld.Changed, sld.Value) end
        end
        function sld:SetValue(val)
            local n = tonumber(val)
            if not n then return end
            n = math.clamp(n, math.min(minV, maxV), math.max(minV, maxV))
            sld.Value = n
            if rfSlider then
                suprimir = true
                rfSlider:Set(n, true)
                suprimir = false
            end
            sld:RunChanged()
        end
        function sld:SetDisabled(desat)
            sld.Disabled = desat == true
            if rfSlider then
                if sld.Disabled then rfSlider:Lock(info.DisabledTooltip) else rfSlider:Unlock() end
            end
        end
        function sld:SetVisible(vis)
            if rfSlider and rfSlider.SetVisible then rfSlider:SetVisible(vis == true) end
        end

        if indice then
            Opcoes[indice] = sld
        end
        if info.Visible == false then
            sld:SetVisible(false)
        end
        return sld
    end

    function objetoContainer:AddInput(indice, info)
        info = type(info) == "table" and info or {}
        local texto = tostring(info.Text or indice or "Entrada")
        local padrao = tostring(info.Default or "")
        local g = obterGrupoSirius()
        local suprimir = false

        local inp = {
            Type = "Input",
            Text = texto,
            Value = padrao,
            Default = padrao,
            AllowEmpty = info.AllowEmpty ~= false,
            EmptyReset = tostring(info.EmptyReset or padrao),
            Disabled = info.Disabled == true,
            Callback = info.Callback,
            Changed = info.Changed,
        }

        local rfInput
        rfInput = g:CreateInput({
            name = texto,
            description = info.Tooltip,
            value = padrao,
            placeholder = tostring(info.Placeholder or ""),
            numeric = info.Numeric == true,
            clearOnFocus = info.ClearTextOnFocus == true,
            forgetState = true,
            callback = function(txt)
                local finalTxt = tostring(txt or "")
                if not inp.AllowEmpty and finalTxt:match("^%s*$") then
                    finalTxt = inp.EmptyReset
                    if rfInput then
                        suprimir = true
                        rfInput:Set(finalTxt, true)
                        suprimir = false
                    end
                end
                inp.Value = finalTxt
                if suprimir then return end
                if inp.Callback then task.spawn(inp.Callback, finalTxt) end
                if inp.Changed then task.spawn(inp.Changed, finalTxt) end
            end,
        })

        if rfInput and rfInput.input then
            Library:GiveSignal(rfInput.input:GetPropertyChangedSignal("Text"):Connect(function()
                local liveTxt = tostring(rfInput.input.Text or "")
                if inp.AllowEmpty or not liveTxt:match("^%s*$") then
                    inp.Value = liveTxt
                else
                    inp.Value = ""
                end
            end))
        end

        if inp.Disabled and rfInput and rfInput.Lock then
            rfInput:Lock(info.DisabledTooltip)
        end

        function inp:OnChanged(fn) inp.Changed = fn end
        function inp:RunChanged()
            if inp.Callback then task.spawn(inp.Callback, inp.Value) end
            if inp.Changed then task.spawn(inp.Changed, inp.Value) end
        end
        function inp:SetValue(val)
            local s = tostring(val ~= nil and val or "")
            if not inp.AllowEmpty and s:match("^%s*$") then
                s = inp.EmptyReset
            end
            inp.Value = s
            if rfInput then
                suprimir = true
                rfInput:Set(s, true)
                suprimir = false
            end
            inp:RunChanged()
        end
        function inp:SetDisabled(desat)
            inp.Disabled = desat == true
            if rfInput then
                if inp.Disabled then rfInput:Lock(info.DisabledTooltip) else rfInput:Unlock() end
            end
        end
        function inp:SetVisible(vis)
            if rfInput and rfInput.SetVisible then rfInput:SetVisible(vis == true) end
        end

        if indice then
            Opcoes[indice] = inp
        end
        if info.Visible == false then
            inp:SetVisible(false)
        end
        return inp
    end

    function objetoContainer:AddDropdown(indice, info)
        info = type(info) == "table" and info or {}
        local texto = tostring(info.Text or indice or "Seletor")
        local ehMulti = info.Multi == true
        local g = obterGrupoSirius()
        local suprimir = false

        local fmtDispOrig = info.FormatDisplayValue or info.FormatListValue

        local function obterListaJogadores()
            local res = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if not (info.ExcludeLocalPlayer and p == JogadorLocal) then
                    table.insert(res, p)
                end
            end
            return res
        end

        local valoresBrutos = {}
        if info.SpecialType == "Player" then
            valoresBrutos = obterListaJogadores()
        elseif info.SpecialType == "Team" then
            valoresBrutos = Teams:GetTeams()
        elseif type(info.Values) == "table" then
            for _, v in pairs(info.Values) do
                table.insert(valoresBrutos, v)
            end
        end

        local dd = {
            Type = "Dropdown",
            Text = texto,
            Multi = ehMulti,
            Values = valoresBrutos,
            DisabledValues = type(info.DisabledValues) == "table" and table.clone(info.DisabledValues) or {},
            Value = ehMulti and {} or nil,
            Default = nil,
            SpecialType = info.SpecialType,
            Disabled = info.Disabled == true,
            Callback = info.Callback,
            Changed = info.Changed,
            _depListeners = {},
            _labelToRaw = {},
            _rawToLabel = {},
            _labelToIcon = {},
        }

        local function formatarRotuloOpcao(itemBruto)
            local base
            if fmtDispOrig then
                local ok, r = pcall(fmtDispOrig, itemBruto)
                base = (ok and r ~= nil) and tostring(r) or tostring(itemBruto)
            elseif typeof(itemBruto) == "Instance" then
                if itemBruto:IsA("Player") then
                    base = string.format("%s (@%s)", itemBruto.DisplayName, itemBruto.Name)
                else
                    base = itemBruto.Name
                end
            else
                base = tostring(itemBruto)
            end
            base = (base:gsub("\n", " "))
            return PTBR_OPCOES_DROPDOWN[base] or PTBR_OPCOES_DROPDOWN[tostring(itemBruto)] or base
        end

        local function resolverIconeOpcao(raw, lbl)
            if info.SpecialType == "Player" and typeof(raw) == "Instance" and raw:IsA("Player") then
                if Alternadores.StreamerMode and Alternadores.StreamerMode.Value and not string.find(lbl, "@" .. raw.Name, 1, true) then
                    return "user"
                end
                return string.format("rbxthumb://type=AvatarHeadShot&id=%d&w=48&h=48", raw.UserId)
            end
            if type(info.ValueImages) == "table" then
                return info.ValueImages[raw] or info.ValueImages[tostring(raw)] or info.ValueImages[lbl]
            end
            return nil
        end

        local function reconstruirMapaOpcoes()
            table.clear(dd._labelToRaw)
            table.clear(dd._rawToLabel)
            table.clear(dd._labelToIcon)
            local listaLabels = {}
            local usados = {}
            for _, raw in ipairs(dd.Values) do
                if not table.find(dd.DisabledValues, raw) then
                    local lbl = formatarRotuloOpcao(raw)
                    if lbl == "" then lbl = "---" end
                    if usados[lbl] and dd._labelToRaw[lbl] ~= raw then
                        local c = 2
                        while usados[lbl .. " #" .. c] do c += 1 end
                        lbl = lbl .. " #" .. c
                    end
                    usados[lbl] = true
                    dd._labelToRaw[lbl] = raw
                    dd._rawToLabel[raw] = lbl
                    local ic = resolverIconeOpcao(raw, lbl)
                    if ic then dd._labelToIcon[lbl] = ic end
                    table.insert(listaLabels, lbl)
                end
            end
            return listaLabels
        end

        local opcoesIniciaisLabels = reconstruirMapaOpcoes()

        -- Resolver valor inicial
        if ehMulti then
            if type(info.Default) == "table" then
                local ehArray = (#info.Default > 0)
                if ehArray then
                    for _, item in ipairs(info.Default) do
                        if type(item) == "number" and dd.Values[item] ~= nil then
                            dd.Value[dd.Values[item]] = true
                        else
                            dd.Value[item] = true
                        end
                    end
                else
                    for k, v in pairs(info.Default) do
                        if v then dd.Value[k] = true end
                    end
                end
            end
            dd.Default = table.clone(dd.Value)
        else
            if type(info.Default) == "number" and dd.Values[info.Default] ~= nil then
                dd.Value = dd.Values[info.Default]
            elseif info.Default ~= nil then
                dd.Value = info.Default
            elseif not info.AllowNull and dd.Values[1] ~= nil then
                dd.Value = dd.Values[1]
            end
            dd.Default = dd.Value
        end

        local function selecaoAtualParaSirius()
            if ehMulti then
                local arr = {}
                for raw, ativo in pairs(dd.Value) do
                    if ativo and dd._rawToLabel[raw] then
                        table.insert(arr, dd._rawToLabel[raw])
                    end
                end
                return arr
            else
                if dd.Value ~= nil and dd._rawToLabel[dd.Value] then
                    return dd._rawToLabel[dd.Value]
                end
                return {}
            end
        end

        local rfDropdown = g:CreateDropdown({
            name = texto,
            description = info.Tooltip,
            icon = info.Icon,
            options = opcoesIniciaisLabels,
            optionIcons = dd._labelToIcon,
            value = selecaoAtualParaSirius(),
            multiSelect = ehMulti,
            placeholder = "---",
            forgetState = true,
            callback = function(selecionadoSirius)
                if ehMulti then
                    table.clear(dd.Value)
                    if type(selecionadoSirius) == "table" then
                        for _, lbl in ipairs(selecionadoSirius) do
                            local raw = dd._labelToRaw[lbl]
                            if raw ~= nil then
                                dd.Value[raw] = true
                            end
                        end
                    end
                else
                    if type(selecionadoSirius) == "string" then
                        dd.Value = dd._labelToRaw[selecionadoSirius]
                    else
                        dd.Value = nil
                    end
                end
                if suprimir then return end
                if dd.Callback then task.spawn(dd.Callback, dd.Value) end
                if dd.Changed then task.spawn(dd.Changed, dd.Value) end
                for _, fn in ipairs(dd._depListeners) do pcall(fn) end
            end,
        })

        if dd.Disabled and rfDropdown and rfDropdown.Lock then
            rfDropdown:Lock(info.DisabledTooltip)
        end

        function dd:OnChanged(fn) dd.Changed = fn end
        function dd:RunChanged()
            if dd.Callback then task.spawn(dd.Callback, dd.Value) end
            if dd.Changed then task.spawn(dd.Changed, dd.Value) end
            for _, fn in ipairs(dd._depListeners) do pcall(fn) end
        end

        function dd:SetValues(novosValores)
            dd.Values = {}
            if type(novosValores) == "table" then
                for _, v in pairs(novosValores) do
                    table.insert(dd.Values, v)
                end
            end
            local novosLabels = reconstruirMapaOpcoes()
            if rfDropdown then
                suprimir = true
                rfDropdown:Refresh(novosLabels, dd._labelToIcon)
                rfDropdown:Set(selecaoAtualParaSirius(), true)
                suprimir = false
            end
        end

        function dd:AddValues(adicionais)
            if type(adicionais) ~= "table" then adicionais = { adicionais } end
            for _, v in pairs(adicionais) do
                if not table.find(dd.Values, v) then
                    table.insert(dd.Values, v)
                end
            end
            dd:SetValues(dd.Values)
        end

        function dd:SetDisabledValues(desativados)
            dd.DisabledValues = type(desativados) == "table" and table.clone(desativados) or {}
            dd:SetValues(dd.Values)
        end

        local function resolverItemValor(item)
            if dd._labelToRaw[item] ~= nil then
                return dd._labelToRaw[item]
            end
            if info.SpecialType == "Player" and type(item) == "string" then
                return Players:FindFirstChild(item)
            end
            return item
        end

        function dd:SetValue(novoVal)
            if ehMulti then
                table.clear(dd.Value)
                if type(novoVal) == "table" then
                    if #novoVal > 0 then
                        for _, item in ipairs(novoVal) do
                            local r = resolverItemValor(item)
                            if r ~= nil then dd.Value[r] = true end
                        end
                    else
                        for k, v in pairs(novoVal) do
                            if v then
                                local r = resolverItemValor(k)
                                if r ~= nil then dd.Value[r] = true end
                            end
                        end
                    end
                elseif novoVal ~= nil then
                    local r = resolverItemValor(novoVal)
                    if r ~= nil then dd.Value[r] = true end
                end
            else
                if novoVal == nil then
                    dd.Value = nil
                else
                    dd.Value = resolverItemValor(novoVal)
                end
            end
            if rfDropdown then
                suprimir = true
                rfDropdown:Set(selecaoAtualParaSirius(), true)
                suprimir = false
            end
            dd:RunChanged()
        end

        function dd:GetActiveValues()
            if ehMulti then
                local arr = {}
                for k, v in pairs(dd.Value) do
                    if v then table.insert(arr, k) end
                end
                return arr
            end
            return dd.Value ~= nil and { dd.Value } or {}
        end

        function dd:Display()
            if rfDropdown then
                suprimir = true
                rfDropdown:Refresh(reconstruirMapaOpcoes(), dd._labelToIcon)
                rfDropdown:Set(selecaoAtualParaSirius(), true)
                suprimir = false
            end
        end

        function dd:SetDisabled(desat)
            dd.Disabled = desat == true
            if rfDropdown then
                if dd.Disabled then rfDropdown:Lock(info.DisabledTooltip) else rfDropdown:Unlock() end
            end
        end

        function dd:SetVisible(vis)
            if rfDropdown and rfDropdown.SetVisible then rfDropdown:SetVisible(vis == true) end
        end

        if info.SpecialType == "Player" then
            table.insert(Library._playerDropdowns, {
                dd = dd,
                ehMulti = ehMulti,
                getLista = obterListaJogadores,
            })
            if not Library._playerListenersStarted then
                Library._playerListenersStarted = true
                Library:GiveSignal(Players.PlayerAdded:Connect(function()
                    if Library.Unloaded then return end
                    for _, reg in ipairs(Library._playerDropdowns) do
                        reg.dd:SetValues(reg.getLista())
                    end
                end))
                Library:GiveSignal(Players.PlayerRemoving:Connect(function(plr)
                    if Library.Unloaded then return end
                    for _, reg in ipairs(Library._playerDropdowns) do
                        if reg.ehMulti then reg.dd.Value[plr] = nil elseif reg.dd.Value == plr then reg.dd.Value = nil end
                    end
                    task.defer(function()
                        if Library.Unloaded then return end
                        for _, reg in ipairs(Library._playerDropdowns) do
                            reg.dd:SetValues(reg.getLista())
                        end
                    end)
                end))
            end
        end

        if indice then
            Opcoes[indice] = dd
        end
        if info.Visible == false then
            dd:SetVisible(false)
        end
        return dd
    end

    function objetoContainer:AddDependencyBox()
        local gPai = obterGrupoSirius()
        local depGrupo = gPai:CreateGroup({ direction = "column" })
        local depBox = {
            Type = "DependencyBox",
            Visible = true,
            Dependencies = {},
            Container = depGrupo.main,
            _childDeps = {},
        }

        local function verificarVisibilidade()
            local okPai = estaVisivelPai()
            local okPropria = true
            for _, par in ipairs(depBox.Dependencies) do
                local ctrl, esperado = par[1], par[2]
                if ctrl then
                    if type(esperado) == "table" then
                        local achou = false
                        if ctrl.Type == "Dropdown" and ctrl.Multi and type(ctrl.Value) == "table" then
                            for _, item in ipairs(esperado) do
                                if ctrl.Value[item] == true then achou = true; break end
                            end
                        else
                            for _, item in ipairs(esperado) do
                                if ctrl.Value == item then achou = true; break end
                            end
                        end
                        if not achou then okPropria = false; break end
                    elseif ctrl.Type == "Dropdown" and ctrl.Multi and type(ctrl.Value) == "table" then
                        if (ctrl.Value[esperado] == true) ~= true then
                            okPropria = false
                            break
                        end
                    else
                        if ctrl.Value ~= esperado then
                            okPropria = false
                            break
                        end
                    end
                end
            end
            depBox.Visible = okPai and okPropria
            if depGrupo and depGrupo.SetVisible then
                depGrupo:SetVisible(depBox.Visible)
            end
            for _, filho in ipairs(depBox._childDeps) do
                filho:Update()
            end
        end

        function depBox:Update()
            verificarVisibilidade()
        end

        function depBox:SetupDependencies(deps)
            depBox.Dependencies = type(deps) == "table" and deps or {}
            for _, par in ipairs(depBox.Dependencies) do
                local ctrl = par[1]
                if ctrl and ctrl._depListeners then
                    table.insert(ctrl._depListeners, verificarVisibilidade)
                end
            end
            verificarVisibilidade()
        end

        if objetoContainer._childDeps then
            table.insert(objetoContainer._childDeps, depBox)
        end

        anexarConstrutoresContainer(depBox, function() return depGrupo end, function() return depBox.Visible end)
        table.insert(Library.DependencyBoxes, depBox)
        return depBox
    end
end

function Library:CreateWindow(infoJanela)
    infoJanela = type(infoJanela) == "table" and infoJanela or {}
    if infoJanela.CornerRadius then
        Library.CornerRadius = tonumber(infoJanela.CornerRadius) or 12
    end
    if infoJanela.ToggleKeybind then
        Library.ToggleKeybind = infoJanela.ToggleKeybind
    end

    local temaInicial = construirTemaSirius(Library.Scheme, Library.CornerRadius)

    local rfWindow = Rayfield:CreateWindow({
        name = "Brazuka",
        subtitle = "FTAP • Edição Sirius Gen2",
        icon = infoJanela.Icon or ICONE_BRASIL,
        showName = "Brazuka",
        showIcon = infoJanela.Icon or ICONE_BRASIL,
        sidebarLayout = true,
        profile = "Projeto Brazuka PT-BR",
        locale = "pt-br",
        translations = SIRIUS_LOCALE_PTBR,
        theme = temaInicial,
    })

    if typeof(Library.ToggleKeybind) == "EnumItem" then
        rfWindow.settings.toggleKeybind = Library.ToggleKeybind
    end

    pcall(function()
        Library._versionTag = rfWindow:CreateTag({
            text = "13/22 • PT-BR",
            color = Library.Scheme.AccentColor or VERDE_BRASIL,
            order = 1,
        })
    end)

    Library.RFWindow = rfWindow
    Library.ScreenGui = rfWindow.screenGui

    -- Componente reutilizável: Indicadores de Desempenho no Cabeçalho (FPS • MS • PING • TEMP)
    Library._headerPerfConfig = Library._headerPerfConfig or {
        Enabled = true,
        FPS = true,
        MS = true,
        Ping = true,
        Temp = true,
    }

    local function construirIndicadoresCabecalho()
        local topbar = rfWindow.topbar
        if not topbar then return nil end

        local pill = Instance.new("Frame")
        pill.Name = "BrazukaHeaderPerf"
        pill.AnchorPoint = Vector2.new(1, 0.5)
        pill.Position = UDim2.new(1, -138, 0.5, 0)
        pill.Size = UDim2.fromOffset(0, 24)
        pill.AutomaticSize = Enum.AutomaticSize.X
        pill.BackgroundColor3 = Library.Scheme.MainColor
        pill.BackgroundTransparency = 0.25
        pill.BorderSizePixel = 0
        pill.ZIndex = 12
        pill.Parent = topbar

        local pillCorner = Instance.new("UICorner")
        pillCorner.CornerRadius = UDim.new(1, 0)
        pillCorner.Parent = pill

        local pillStroke = Instance.new("UIStroke")
        pillStroke.Color = Library.Scheme.OutlineColor
        pillStroke.Transparency = 0.42
        pillStroke.Thickness = 1
        pillStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        pillStroke.Parent = pill

        local pillPad = Instance.new("UIPadding")
        pillPad.PaddingLeft = UDim.new(0, 9)
        pillPad.PaddingRight = UDim.new(0, 9)
        pillPad.Parent = pill

        local pillList = Instance.new("UIListLayout")
        pillList.FillDirection = Enum.FillDirection.Horizontal
        pillList.VerticalAlignment = Enum.VerticalAlignment.Center
        pillList.HorizontalAlignment = Enum.HorizontalAlignment.Center
        pillList.Padding = UDim.new(0, 8)
        pillList.SortOrder = Enum.SortOrder.LayoutOrder
        pillList.Parent = pill

        local function criarItem(ordem, textoInicial)
            local holder = Instance.new("Frame")
            holder.BackgroundTransparency = 1
            holder.AutomaticSize = Enum.AutomaticSize.X
            holder.Size = UDim2.fromOffset(0, 18)
            holder.LayoutOrder = ordem
            holder.ZIndex = 13
            holder.Parent = pill

            local hList = Instance.new("UIListLayout")
            hList.FillDirection = Enum.FillDirection.Horizontal
            hList.VerticalAlignment = Enum.VerticalAlignment.Center
            hList.Padding = UDim.new(0, 4)
            hList.SortOrder = Enum.SortOrder.LayoutOrder
            hList.Parent = holder

            local dot = Instance.new("Frame")
            dot.Size = UDim2.fromOffset(5, 5)
            dot.BackgroundColor3 = Library.Scheme.AccentColor or VERDE_BRASIL
            dot.BorderSizePixel = 0
            dot.LayoutOrder = 1
            dot.ZIndex = 14
            dot.Parent = holder
            local dotCorner = Instance.new("UICorner")
            dotCorner.CornerRadius = UDim.new(1, 0)
            dotCorner.Parent = dot

            local lbl = Instance.new("TextLabel")
            lbl.BackgroundTransparency = 1
            lbl.AutomaticSize = Enum.AutomaticSize.X
            lbl.Size = UDim2.fromOffset(0, 16)
            lbl.FontFace = Font.new(Library.Scheme.Font.Family, Enum.FontWeight.Medium, Library.Scheme.Font.Style)
            lbl.TextSize = 11
            lbl.TextColor3 = Library.Scheme.FontColor
            lbl.TextTransparency = 0.08
            lbl.Text = textoInicial
            lbl.LayoutOrder = 2
            lbl.ZIndex = 14
            lbl.Parent = holder

            return { Frame = holder, Dot = dot, Label = lbl, State = "good" }
        end

        local itemFPS = criarItem(1, "60 FPS")
        local itemMS = criarItem(2, "16 ms")
        local itemPing = criarItem(3, "-- ping")
        local itemTemp = criarItem(4, "-- °C")

        local widget = {
            Root = pill,
            Items = { FPS = itemFPS, MS = itemMS, Ping = itemPing, Temp = itemTemp },
        }

        local function corPorEstado(estado)
            local acc = Library.Scheme.AccentColor or VERDE_BRASIL
            local lumAcc = 0.299 * acc.R + 0.587 * acc.G + 0.114 * acc.B
            local boaCor = (lumAcc < 0.18) and Color3.fromRGB(52, 211, 153) or acc
            if estado == "good" then
                return boaCor
            elseif estado == "warn" then
                return Color3.fromRGB(251, 191, 36)
            elseif estado == "bad" then
                return Color3.fromRGB(248, 113, 113)
            end
            return (Library.Scheme.FontColor or Color3.new(1, 1, 1)):Lerp(Library.Scheme.MainColor or Color3.fromRGB(30, 30, 34), 0.45)
        end

        function widget:ApplyTheme()
            local esq = Library.Scheme
            pill.BackgroundColor3 = esq.MainColor
            pillStroke.Color = esq.OutlineColor
            for _, it in pairs(self.Items) do
                it.Label.TextColor3 = esq.FontColor
                it.Label.FontFace = Font.new(esq.Font.Family, Enum.FontWeight.Medium, esq.Font.Style)
                it.Dot.BackgroundColor3 = corPorEstado(it.State)
            end
        end

        local function definirEstadoItem(it, estado)
            it.State = estado
            it.Dot.BackgroundColor3 = corPorEstado(estado)
        end

        function widget:RefreshLayout()
            local cfg = Library._headerPerfConfig
            local actW = (rfWindow.actionContainer and rfWindow.actionContainer.AbsoluteSize.X > 0) and rfWindow.actionContainer.AbsoluteSize.X or 116
            pill.Position = UDim2.new(1, -(actW + 28), 0.5, 0)

            local barW = topbar.AbsoluteSize.X > 0 and topbar.AbsoluteSize.X or 820
            local leftEndX = 0
            if rfWindow.topContainer and rfWindow.topContainer.Parent then
                leftEndX = rfWindow.topContainer.AbsolutePosition.X + rfWindow.topContainer.AbsoluteSize.X - topbar.AbsolutePosition.X
            end
            if leftEndX <= 0 then leftEndX = 290 end
            local disponivel = math.max(0, (barW - actW - 38) - (leftEndX + 12))

            local mostrarTemp = cfg.Temp == true and disponivel >= 255
            local mostrarPing = cfg.Ping == true and disponivel >= 190
            local mostrarMS = cfg.MS == true and disponivel >= 135
            local mostrarFPS = cfg.FPS == true and disponivel >= 76

            itemFPS.Frame.Visible = mostrarFPS
            itemMS.Frame.Visible = mostrarMS
            itemPing.Frame.Visible = mostrarPing
            itemTemp.Frame.Visible = mostrarTemp

            local temAlgum = mostrarFPS or mostrarMS or mostrarPing or mostrarTemp
            pill.Visible = (cfg.Enabled == true) and temAlgum
        end

        if rfWindow.topbar then
            Library:GiveSignal(rfWindow.topbar:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                widget:RefreshLayout()
            end))
        end
        if rfWindow.actionContainer then
            Library:GiveSignal(rfWindow.actionContainer:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                widget:RefreshLayout()
            end))
        end
        if rfWindow.topContainer then
            Library:GiveSignal(rfWindow.topContainer:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                widget:RefreshLayout()
            end))
        end

        -- Temperatura climática real em °C (Open-Meteo + Geolocalização por IP sem chave privada, com fallbacks)
        local tempCacheValor = nil
        local tempProximoFetch = 0
        local tempEmAndamento = false

        local function httpGetTextoSeguro(url)
            local reqFn = request or http_request or (http and http.request)
            if type(reqFn) == "function" then
                local okReq, res = pcall(reqFn, {
                    Url = url,
                    Method = "GET",
                    Headers = {
                        ["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
                        ["Accept"] = "application/json, text/plain",
                    },
                })
                if okReq and type(res) == "table" and type(res.Body) == "string" and res.Body ~= "" then
                    local status = tonumber(res.StatusCode or res.Status) or 200
                    if status >= 200 and status < 300 then
                        return res.Body
                    end
                end
            end
            local okHttp, body = pcall(function()
                return game:HttpGet(url)
            end)
            if okHttp and type(body) == "string" and body ~= "" then
                return body
            end
            return nil
        end

        local function decodificarJsonSeguro(txt)
            if type(txt) ~= "string" or txt == "" then return nil end
            local ok, tbl = pcall(HttpService.JSONDecode, HttpService, txt)
            if ok and type(tbl) == "table" then
                return tbl
            end
            return nil
        end

        local function atualizarLabelTemp()
            if type(tempCacheValor) == "number" then
                itemTemp.Label.Text = string.format("%d °C", tempCacheValor)
                if tempCacheValor <= 30 then
                    definirEstadoItem(itemTemp, "good")
                elseif tempCacheValor <= 38 then
                    definirEstadoItem(itemTemp, "warn")
                else
                    definirEstadoItem(itemTemp, "bad")
                end
            else
                itemTemp.Label.Text = "-- °C"
                definirEstadoItem(itemTemp, "muted")
            end
        end

        local function obterCoordenadasPorIP()
            local provedoresGeo = {
                {
                    url = "https://ipwho.is/",
                    ler = function(d)
                        return tonumber(d.latitude), tonumber(d.longitude)
                    end,
                },
                {
                    url = "https://get.geojs.io/v1/ip/geo.json",
                    ler = function(d)
                        return tonumber(d.latitude), tonumber(d.longitude)
                    end,
                },
                {
                    url = "http://ip-api.com/json/?fields=status,lat,lon",
                    ler = function(d)
                        if d.status ~= "success" then return nil, nil end
                        return tonumber(d.lat), tonumber(d.lon)
                    end,
                },
            }
            for _, prov in ipairs(provedoresGeo) do
                local dados = decodificarJsonSeguro(httpGetTextoSeguro(prov.url))
                if dados then
                    local lat, lon = prov.ler(dados)
                    if lat and lon then
                        return lat, lon
                    end
                end
            end
            return nil, nil
        end

        local function buscarTemperaturaAsync()
            if tempEmAndamento or Library.Unloaded then return end
            local agora = os.clock()
            if agora < tempProximoFetch then return end
            tempEmAndamento = true

            task.spawn(function()
                local novaTemp = nil

                -- Provedor 1: Geolocalização por IP + Open-Meteo (JSON estável, sem API key)
                local lat, lon = obterCoordenadasPorIP()
                if lat and lon then
                    local meteoUrl = string.format(
                        "https://api.open-meteo.com/v1/forecast?latitude=%s&longitude=%s&current=temperature_2m&current_weather=true&temperature_unit=celsius",
                        tostring(lat),
                        tostring(lon)
                    )
                    local meteo = decodificarJsonSeguro(httpGetTextoSeguro(meteoUrl))
                    if meteo then
                        local t = (type(meteo.current) == "table" and tonumber(meteo.current.temperature_2m))
                            or (type(meteo.current_weather) == "table" and tonumber(meteo.current_weather.temperature))
                        if t then
                            novaTemp = math.round(t)
                        end
                    end
                end

                -- Provedor 2 (fallback): wttr.in JSON
                if not novaTemp then
                    local wttrJson = decodificarJsonSeguro(httpGetTextoSeguro("https://wttr.in/?format=j1"))
                    if wttrJson and type(wttrJson.current_condition) == "table" and type(wttrJson.current_condition[1]) == "table" then
                        local tC = tonumber(wttrJson.current_condition[1].temp_C)
                        if tC then
                            novaTemp = math.round(tC)
                        end
                    end
                end

                -- Provedor 3 (fallback final): wttr.in texto com remoção segura do símbolo UTF-8 °
                if not novaTemp then
                    local rawTxt = httpGetTextoSeguro("https://wttr.in/?format=%t")
                    if rawTxt then
                        local limpo = rawTxt:gsub("\194\176", ""):gsub("°", "")
                        local numStr, unidade = limpo:match("([%+%-]?%d+%.?%d*)%s*([CcFf])")
                        local num = tonumber(numStr)
                        if num then
                            if unidade and unidade:upper() == "F" then
                                num = (num - 32) * 5 / 9
                            end
                            novaTemp = math.round(num)
                        end
                    end
                end

                tempEmAndamento = false
                if novaTemp then
                    tempCacheValor = novaTemp
                    tempProximoFetch = os.clock() + 900
                    if not Library.Unloaded then
                        atualizarLabelTemp()
                    end
                else
                    tempProximoFetch = os.clock() + 25
                end
            end)
        end
        buscarTemperaturaAsync()

        local framesAcum = 0
        local tempoAcum = 0
        Library:GiveSignal(RunService.RenderStepped:Connect(function(dt)
            if Library.Unloaded then return end
            framesAcum += 1
            tempoAcum += dt
            if tempoAcum < 0.55 then return end

            local fpsReal = math.max(1, math.round(framesAcum / math.max(tempoAcum, 0.001)))
            local msQuadro = (tempoAcum / math.max(framesAcum, 1)) * 1000
            framesAcum = 0
            tempoAcum = 0

            if not pill.Visible then return end

            itemFPS.Label.Text = string.format("%d FPS", fpsReal)
            if fpsReal >= 50 then
                definirEstadoItem(itemFPS, "good")
            elseif fpsReal >= 30 then
                definirEstadoItem(itemFPS, "warn")
            else
                definirEstadoItem(itemFPS, "bad")
            end

            itemMS.Label.Text = (msQuadro < 10) and string.format("%.1f ms", msQuadro) or string.format("%d ms", math.round(msQuadro))
            if msQuadro <= 20 then
                definirEstadoItem(itemMS, "good")
            elseif msQuadro <= 35 then
                definirEstadoItem(itemMS, "warn")
            else
                definirEstadoItem(itemMS, "bad")
            end

            local pingMs = nil
            local okStat, statPing = pcall(function()
                return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
            end)
            if okStat and type(statPing) == "number" and statPing == statPing and statPing >= 0 then
                pingMs = math.round(statPing)
            else
                local okPlr, netPing = pcall(function()
                    return JogadorLocal and JogadorLocal:GetNetworkPing()
                end)
                if okPlr and type(netPing) == "number" and netPing == netPing and netPing >= 0 then
                    pingMs = math.round(netPing * 1000)
                end
            end

            if pingMs then
                itemPing.Label.Text = string.format("%d ping", pingMs)
                if pingMs <= 90 then
                    definirEstadoItem(itemPing, "good")
                elseif pingMs <= 165 then
                    definirEstadoItem(itemPing, "warn")
                else
                    definirEstadoItem(itemPing, "bad")
                end
            else
                itemPing.Label.Text = "-- ping"
                definirEstadoItem(itemPing, "muted")
            end

            atualizarLabelTemp()
            if type(tempCacheValor) ~= "number" and os.clock() >= tempProximoFetch then
                buscarTemperaturaAsync()
            end
        end))

        widget:ApplyTheme()
        task.defer(function()
            if not Library.Unloaded then widget:RefreshLayout() end
        end)
        return widget
    end

