    function WindowWrapper:SetAnimations(estados, duracao, distancia, direcao)
        if not rfWindow.elementsLayout then return end
        if type(estados) == "table" and estados.TabSwitch ~= nil then
            Library._animTabEnabled = estados.TabSwitch == true
        end
        if type(duracao) == "number" then
            Library._animDuration = math.clamp(duracao, 0, 1.5)
        end
        rfWindow.elementsLayout.TweenTime = Library._animTabEnabled and Library._animDuration or 0
        if type(distancia) == "number" then
            rfWindow.elementsLayout.SlideDistance = math.clamp(distancia, 1, 120)
        end
        if type(direcao) == "string" then
            local d = string.lower(direcao)
            rfWindow.elementsLayout.SlideFrom = d
            if d == "left" or d == "right" then
                rfWindow.elementsLayout.FillDirection = Enum.FillDirection.Horizontal
            else
