    function WindowWrapper:AddDialog(_, opcoesDialogo)
        opcoesDialogo = type(opcoesDialogo) == "table" and opcoesDialogo or {}
        local listaBotoes = {}
        local botoesBrutos = opcoesDialogo.FooterButtons or {}

        local ordenados = {}
        for chave, btn in pairs(botoesBrutos) do
            if type(btn) == "table" then
                table.insert(ordenados, { key = chave, data = btn, order = tonumber(btn.Order) or 99 })
            end
        end
        table.sort(ordenados, function(a, b) return a.order < b.order end)

        local handleDialogo = { Dismiss = function() end }

        for _, item in ipairs(ordenados) do
            local b = item.data
            local variante = tostring(b.Variant or "")
            local estilo = "primary"
            if variante == "Destructive" then
                estilo = "danger"
            elseif variante == "Ghost" or variante == "Secondary" or item.key == "Cancel" then
                estilo = "neutral"
            end
            table.insert(listaBotoes, {
                text = tostring(b.Title or b.Text or "OK"),
                style = estilo,
                callback = function()
                    if type(b.Callback) == "function" then
                        b.Callback(handleDialogo)
                    end
                end,
            })
        end

        local popup = rfWindow:Popup({
            title = tostring(opcoesDialogo.Title or "Confirmação"),
            content = tostring(opcoesDialogo.Description or ""),
            dismissable = opcoesDialogo.OutsideClickDismiss ~= false,
            options = listaBotoes,
        })

        handleDialogo.Dismiss = function()
            if popup and popup.Close then popup:Close() end
        end
        return handleDialogo
    end

    local function aplicarIconeSecao(imgLabel, icone)
        if not icone or icone == "" then imgLabel.Visible = false; return false end
        if type(icone) == "number" or (type(icone) == "string" and tonumber(icone)) then
            imgLabel.Image = "rbxassetid://" .. tostring(icone)
            imgLabel.ImageRectOffset = Vector2.zero
            imgLabel.ImageRectSize = Vector2.zero
            imgLabel.ImageColor3 = Color3.new(1, 1, 1)
            imgLabel.Visible = true
            return true
        end
        local str = tostring(icone)
        if str:sub(1, 13) == "rbxassetid://" or str:sub(1, 11) == "rbxthumb://" or str:sub(1, 4) == "http" then
            imgLabel.Image = str
            imgLabel.ImageRectOffset = Vector2.zero
            imgLabel.ImageRectSize = Vector2.zero
            imgLabel.ImageColor3 = Color3.new(1, 1, 1)
            imgLabel.Visible = true
            return true
        end
        local fn = getgenv and getgenv().__BrazukaLucide
        local d = type(fn) == "function" and fn(str) or nil
        if d and d.Url then
            imgLabel.Image = d.Url
            imgLabel.ImageRectOffset = d.ImageRectOffset or Vector2.zero
            imgLabel.ImageRectSize = d.ImageRectSize or Vector2.zero
            imgLabel.ImageColor3 = Library.Scheme.AccentColor
            imgLabel.Visible = true
            return false
        end
        imgLabel.Visible = false
        return false
    end

    local function envolverAbaSirius(rfTab, nomeAba, descAba)
        if type(descAba) == "string" and descAba ~= "" then
            rfTab:CreateText({ name = "", text = descAba })
        end

        local columnsRow = rfTab:CreateGroup({ direction = "row", _isLayoutGroup = true })
        local leftCol = columnsRow:CreateGroup({ direction = "column", _isLayoutGroup = true })
        local rightCol = columnsRow:CreateGroup({ direction = "column", _isLayoutGroup = true })
        columnsRow._reflowRow = function() end
        columnsRow.layout.Padding = UDim.new(0, 10)
        columnsRow.layout.VerticalAlignment = Enum.VerticalAlignment.Top
        columnsRow.main.Size = UDim2.new(1, -16, 0, 0)
        leftCol.layout.Padding = UDim.new(0, 10)
        rightCol.layout.Padding = UDim.new(0, 10)

        local leftFlex = leftCol.main:FindFirstChildOfClass("UIFlexItem")
        local rightFlex = rightCol.main:FindFirstChildOfClass("UIFlexItem")
        local leftCount, rightCount = 0, 0

        local function atualizarLayoutColunas(forcar)
            if not forcar and Library.RFWindow and Library.RFWindow.animating then
                return
            end
            if not forcar and rfTab.tabPage and not rfTab.tabPage.Visible then
                return
            end
            if leftCount == 0 and rightCount == 0 then
                leftCol.main.Visible = false
                rightCol.main.Visible = false
                return
            elseif rightCount == 0 then
                rightCol.main.Visible = false
                leftCol.main.Visible = true
                columnsRow.layout.FillDirection = Enum.FillDirection.Vertical
                if leftFlex then leftFlex.FlexMode = Enum.UIFlexMode.None end
                leftCol.main.Size = UDim2.new(1, 0, 0, 0)
            elseif leftCount == 0 then
                leftCol.main.Visible = false
                rightCol.main.Visible = true
                columnsRow.layout.FillDirection = Enum.FillDirection.Vertical
                if rightFlex then rightFlex.FlexMode = Enum.UIFlexMode.None end
                rightCol.main.Size = UDim2.new(1, 0, 0, 0)
            else
                leftCol.main.Visible = true
                rightCol.main.Visible = true
                local wAbs = rfTab.tabPage and rfTab.tabPage.AbsoluteSize.X or 600
                if wAbs <= 0 or wAbs >= 560 then
                    columnsRow.layout.FillDirection = Enum.FillDirection.Horizontal
                    if leftFlex then leftFlex.FlexMode = Enum.UIFlexMode.Fill end
                    if rightFlex then rightFlex.FlexMode = Enum.UIFlexMode.Fill end
                    leftCol.main.Size = UDim2.new(0, 0, 0, 0)
                    rightCol.main.Size = UDim2.new(0, 0, 0, 0)
                else
                    columnsRow.layout.FillDirection = Enum.FillDirection.Vertical
                    if leftFlex then leftFlex.FlexMode = Enum.UIFlexMode.None end
                    if rightFlex then rightFlex.FlexMode = Enum.UIFlexMode.None end
                    leftCol.main.Size = UDim2.new(1, 0, 0, 0)
                    rightCol.main.Size = UDim2.new(1, 0, 0, 0)
                end
            end
        end

        rfTab._refreshColumns = function()
            atualizarLayoutColunas(true)
        end

        if rfTab.tabPage then
            Library:GiveSignal(rfTab.tabPage:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                atualizarLayoutColunas(false)
            end))
            Library:GiveSignal(rfTab.tabPage:GetPropertyChangedSignal("Visible"):Connect(function()
                if rfTab.tabPage.Visible then
                    atualizarLayoutColunas(true)
                end
            end))
        end

        local abaObj = {
            Name = tostring(nomeAba or "Aba"),
            RFTab = rfTab,
            Groupboxes = {},
            Tabboxes = {},
            Container = rfTab.tabPage,
        }

        function abaObj:Show()
            rfTab:Select()
        end

        local function criarCartaoSecao(nomeTitulo, iconeTitulo, lado)
            local ehDir = (lado == "Right")
            local colAlvo = ehDir and rightCol or leftCol
            if ehDir then rightCount += 1 else leftCount += 1 end
            atualizarLayoutColunas(true)

            local ordemCard = (ehDir and rightCount or leftCount) * 10

            local card = Instance.new("Frame")
            card.Name = "Card_" .. tostring(nomeTitulo or "Secao")
            card.AutomaticSize = Enum.AutomaticSize.Y
            card.Size = UDim2.new(1, 0, 0, 0)
            card.BackgroundColor3 = Library.Scheme.MainColor
