            cList.HorizontalAlignment = Enum.HorizontalAlignment.Center
            cList.Padding = UDim.new(0, 6)
            cList.SortOrder = Enum.SortOrder.LayoutOrder
            cList.Parent = card

            local cPad = Instance.new("UIPadding")
            cPad.PaddingTop = UDim.new(0, 8)
            cPad.PaddingBottom = UDim.new(0, 8)
            cPad.Parent = card

            local headerBtn = Instance.new("TextButton")
            headerBtn.Name = "Header"
            headerBtn.AutoButtonColor = false
            headerBtn.BackgroundTransparency = 1
            headerBtn.BorderSizePixel = 0
            headerBtn.Size = UDim2.new(1, -16, 0, 24)
            headerBtn.Text = ""
            headerBtn.LayoutOrder = 1
            headerBtn.ZIndex = 6
            headerBtn.Parent = card

            local hList = Instance.new("UIListLayout")
            hList.FillDirection = Enum.FillDirection.Horizontal
            hList.VerticalAlignment = Enum.VerticalAlignment.Center
            hList.Padding = UDim.new(0, 7)
            hList.SortOrder = Enum.SortOrder.LayoutOrder
            hList.Parent = headerBtn

            local hIcon = Instance.new("ImageLabel")
            hIcon.BackgroundTransparency = 1
