            hTitle.FontFace = Font.new(Library.Scheme.Font.Family, Enum.FontWeight.SemiBold, Library.Scheme.Font.Style)
            hTitle.TextSize = 14
            hTitle.TextColor3 = Library.Scheme.FontColor
            hTitle.TextXAlignment = Enum.TextXAlignment.Left
            hTitle.TextTruncate = Enum.TextTruncate.AtEnd
            hTitle.RichText = true
            hTitle.Text = "<b>" .. nomeLimpo .. "</b>"
            hTitle.LayoutOrder = 1
            hTitle.ZIndex = 7
            hTitle.Parent = headerBtn

            local flexTitle = Instance.new("UIFlexItem")
            flexTitle.FlexMode = Enum.UIFlexMode.Fill
            flexTitle.Parent = hTitle

            local hChev = Instance.new("TextLabel")
            hChev.BackgroundTransparency = 1
            hChev.Size = UDim2.fromOffset(18, 18)
            hChev.FontFace = Library.Scheme.Font
            hChev.TextSize = 13
            hChev.TextColor3 = Library.Scheme.FontColor
            hChev.TextTransparency = 0.4
            hChev.Text = "v"
            hChev.LayoutOrder = 2
            hChev.ZIndex = 7
            hChev.Parent = headerBtn

            local div = Instance.new("Frame")
            div.Name = "Divider"
            div.BackgroundColor3 = Library.Scheme.OutlineColor
            div.BackgroundTransparency = 0.45
            div.BorderSizePixel = 0
            div.Size = UDim2.new(1, -16, 0, 1)
            div.LayoutOrder = 2
            div.Parent = card

            local grupoCorpo = colAlvo:CreateGroup({ direction = "column" })
            grupoCorpo.main.Parent = card
            grupoCorpo.main.LayoutOrder = 3
            grupoCorpo.main.Size = UDim2.new(1, 0, 0, 0)

            table.insert(Library.CardFrames, {
                Frame = card,
                Stroke = cStroke,
                Corner = cCorner,
                Title = hTitle,
                Icon = hIcon,
                IconIsAsset = ehAsset,
                Chevron = hChev,
                Divider = div,
            })

            local colapsado = false
            local function definirColapsado(estado)
                colapsado = estado == true
                grupoCorpo.main.Visible = not colapsado
                div.Visible = not colapsado
                hChev.Text = colapsado and ">" or "v"
            end

            Library:GiveSignal(headerBtn.MouseButton1Click:Connect(function()
                definirColapsado(not colapsado)
            end))

            return card, grupoCorpo, definirColapsado
        end

        local function criarGroupboxSirius(nomeSecao, iconeSecao, lado)
            local card, grupoColuna, definirColapsado = criarCartaoSecao(nomeSecao, iconeSecao, lado)
            local gb = {
                Type = "Groupbox",
                Name = tostring(nomeSecao or "Seção"),
                Collapsed = false,
                PopOutEnabled = false,
                PoppedOut = false,
                Elements = {},
                Container = grupoColuna.main,
                Card = card,
                Resize = function() end,
                SetCollapsed = function(self, c)
                    self.Collapsed = c == true
                    definirColapsado(self.Collapsed)
                end,
                SetPoppedOut = function() end,
            }
            anexarConstrutoresContainer(gb, function() return grupoColuna end, function() return true end)
            abaObj.Groupboxes[gb.Name] = gb
            return gb
        end

        function abaObj:AddLeftGroupbox(nome, icone)
            return criarGroupboxSirius(nome, icone, "Left")
        end

        function abaObj:AddRightGroupbox(nome, icone)
            return criarGroupboxSirius(nome, icone, "Right")
        end

        function abaObj:AddGroupbox(info)
            info = type(info) == "table" and info or { Name = tostring(info or "Seção") }
            local side = (info.Side == "Right") and "Right" or "Left"
            return criarGroupboxSirius(info.Name, info.IconName or info.Icon, side)
        end

        local contadorTabbox = 0
        local function criarTabboxSirius(nomeTabbox, iconeTabbox, lado)
            contadorTabbox += 1
            local _, grupoCorpo = criarCartaoSecao(nomeTabbox, iconeTabbox, lado)

            local barraBotoes = grupoCorpo:CreateGroup({ direction = "row" })
            local conteinerPaginas = grupoCorpo:CreateGroup({ direction = "column" })
            local subAbas = {}
            local indiceSub = 0
            local subAtivaAtual = nil

            local tb = {
                Type = "Tabbox",
                Name = (type(nomeTabbox) == "string" and nomeTabbox ~= "") and nomeTabbox or ("SubAbas_" .. tostring(contadorTabbox)),
                PopOutEnabled = false,
                PoppedOut = false,
                Tabs = subAbas,
                SetPoppedOut = function() end,
            }

            local function aplicarVisualBotaoSub(s, ativo)
                local b = s and s._botao
                if not b or not b.stroke then return end
                b.stroke.Color = ativo and Library.Scheme.AccentColor or Library.Scheme.OutlineColor
                b.stroke.Transparency = ativo and 0.1 or 0.7
            end

            local function selecionarSubAba(subAlvo)
                if subAtivaAtual == subAlvo then
                    aplicarVisualBotaoSub(subAlvo, true)
                    return
                end
                local anterior = subAtivaAtual
                subAtivaAtual = subAlvo
                if anterior then
                    anterior._ativa = false
                    if anterior._grupo and anterior._grupo.SetVisible then
                        anterior._grupo:SetVisible(false)
                    end
                    aplicarVisualBotaoSub(anterior, false)
                end
                subAlvo._ativa = true
                if subAlvo._grupo and subAlvo._grupo.SetVisible then
                    subAlvo._grupo:SetVisible(true)
                end
                aplicarVisualBotaoSub(subAlvo, true)
                task.delay(0.13, function()
                    if subAtivaAtual == subAlvo then aplicarVisualBotaoSub(subAlvo, true) end
                end)
                if subAlvo._childDeps then
                    for _, d in ipairs(subAlvo._childDeps) do d:Update() end
                end
            end

            function tb:AddTab(subNome, subIcone)
                indiceSub += 1
                local rotuloSub = (type(subNome) == "string" and subNome ~= "") and subNome or ("Aba " .. tostring(indiceSub))
                local grupoPagina = conteinerPaginas:CreateGroup({ direction = "column" })

                local subObj = {
                    Type = "SubTab",
                    Name = rotuloSub,
                    Container = grupoPagina.main,
                    _grupo = grupoPagina,
                    _ativa = false,
                    _childDeps = {},
                }

                local rfSubBtn = barraBotoes:CreateButton({
                    name = (type(subNome) == "string" and subNome ~= "") and subNome or "",
                    icon = subIcone,
                    callback = function()
                        selecionarSubAba(subObj)
                    end,
                })
                if rfSubBtn and rfSubBtn.title and rfSubBtn.name == "" then
                    rfSubBtn.title.Visible = false
                end
                if rfSubBtn and rfSubBtn.main then
                    Library:GiveSignal(rfSubBtn.main.MouseLeave:Connect(function()
                        task.defer(aplicarVisualBotaoSub, subObj, subObj._ativa)
                    end))
                end
                subObj._botao = rfSubBtn

                anexarConstrutoresContainer(subObj, function() return grupoPagina end, function() return subObj._ativa end)
                table.insert(subAbas, subObj)

                if #subAbas == 1 then
                    selecionarSubAba(subObj)
                else
                    grupoPagina:SetVisible(false)
                end

                return subObj
            end

            abaObj.Tabboxes[tb.Name] = tb
            return tb
        end

        function abaObj:AddLeftTabbox(nome, icone)
            return criarTabboxSirius(nome, icone, "Left")
        end

        function abaObj:AddRightTabbox(nome, icone)
            return criarTabboxSirius(nome, icone, "Right")
        end

        Library.Tabs[abaObj.Name] = abaObj
        return abaObj
    end

    local settingsTabWrapper = nil
    function WindowWrapper:GetSettingsTab()
        if settingsTabWrapper then
            return settingsTabWrapper
        end
        settingsTabWrapper = envolverAbaSirius(rfWindow.rfSettings, "Configurações", nil)
        return settingsTabWrapper
    end

    function WindowWrapper:AddTab(nomeAba, iconeAba, descAba)
        local nomeLimpo = tostring(nomeAba or "Aba"):gsub("<[^>]->", "")
        if nomeLimpo == "Configurações" or nomeLimpo == "UI Settings" then
            local sw = WindowWrapper:GetSettingsTab()
            Library.Tabs[tostring(nomeAba or "Configurações")] = sw
            return sw
        end
        local rfTab = rfWindow:CreateTab({
            name = tostring(nomeAba or "Aba"),
            icon = iconeAba,
        })
        return envolverAbaSirius(rfTab, nomeAba, descAba)
    end

    Library.Window = WindowWrapper
    return WindowWrapper
end

function Library:Unload()
    if Library.Unloaded then return end
    Library.Unloaded = true

    for _, fn in ipairs(Library.UnloadSignals) do
        pcall(fn)
    end

    pcall(function() Library:DestroyAllMobileButtons() end)
    if Library._mobileGui then
        pcall(function() Library._mobileGui:Destroy() end)
        Library._mobileGui = nil
    end
    Library._thirdPersonUnlock = false

    for _, s in ipairs(Library.Signals) do
        pcall(function() s:Disconnect() end)
    end
    table.clear(Library.Signals)
    table.clear(Library.CardFrames)

    pcall(function()
        UserInputService.MouseIconEnabled = Library.OriginalMouseIconEnabled
    end)

    if Library.RFWindow then
        pcall(function() Library.RFWindow:Unload() end)
    end
end

getgenv().Library = Library
return Library
]=]
