								estadoCompartilhado.PacketData[arg] = tabela16
							end

							local agora3 = tick()
							local ultimoTamanho = #texto6
							local previa = string.sub(texto6, 1, 15)
							local valor24 = api.FormatarJogador(arg)
							local texto7 = string.format("%.2f", funcao21(texto6))
							local texto8

							if arg3 == "CGL" then
