					filaMetodos.Enfileirar = function(arg, arg2, arg3, arg4)
						if not (arg and arg2 and arg3) then
							return
						end
						arg4 = arg4 or arg
						local tabela16 = filaMetodos.Trabalhadores[arg]

						if not tabela16 then
							tabela16 = { Items = {}, Pending = {}, Head = 1, Tail = 0, Running = false }
							filaMetodos.Trabalhadores[arg] = tabela16
						end

						local numero36 = filaMetodos.Geracoes[arg4] or 0
						local valor24 = tabela16.Pending[arg3]
						if valor24 and valor24.Owner == arg4 and valor24.Epoch == filaMetodos.Epoca and valor24.Generation == numero36 then
							return
						end
						local tabela17 = { Callback = arg2, Player = arg3, Owner = arg4, Epoch = filaMetodos.Epoca, Generation = numero36 }
						tabela16.Tail = tabela16.Tail + 1
						tabela16.Items[tabela16.Tail] = tabela17
						tabela16.Pending[arg3] = tabela17
						if tabela16.Running then
							return
						end
						tabela16.Running = true

						task.spawn(function()
							while not descarregado do
								local valor25 = tabela16.Items[tabela16.Head]

								if valor25 then
									tabela16.Items[tabela16.Head] = nil
									tabela16.Head = tabela16.Head + 1
									local estado12 = valor25.Epoch == filaMetodos.Epoca

									if estado12 then
										estado12 = valor25.Generation == (filaMetodos.Geracoes[valor25.Owner] or 0)
									end

									if estado12 and valor25.Player.Parent then
										local sucesso, resultado = pcall(valor25.Callback, valor25.Player)

										if not sucesso then
											warn(("[Brazuka] %s failed: %s"):format(arg, tostring(resultado)))
										end

										task.wait()
									end

									if tabela16.Pending[valor25.Player] == valor25 then
										tabela16.Pending[valor25.Player] = nil
									end

									if tabela16.Head > 128 and tabela16.Head > tabela16.Tail / 2 then
										filaMetodos.Compactar(tabela16)
									end

									continue
								end

								break
							end

							tabela16.Items = {}
							tabela16.Pending = {}
							tabela16.Head = 1
							tabela16.Tail = 0
							tabela16.Running = false
						end)
					end

