					local cameraTipo = cameraAtual2.CameraType
					local numero36 = 0
					local posicao = valor25.Position
					local rotacao = valor25.CFrame.Rotation
					local autoGirar = valor26.AutoRotate
					local numero37

					if gatilhoManobra == "720 Spin" then
						numero37 = 2
					else
						numero37 = 1
					end

					local valor30 = numero37
					local numero38 = 0.175 * valor30 / math.clamp(miraConfiguracoes.TriggerTrickSpeed, 0.75, 2)

					local sucesso, resultado = pcall(function()
						miraConfiguracoes.TriggerSpinning = true
						local valor31 = valor26
						cameraAtual2.CameraType = Enum.CameraType.Scriptable
						valor31.AutoRotate = false

						repeat
							numero36 += RunService.RenderStepped:Wait()
							if descarregado or valor26.Health <= 0 or not miraConfiguracoes.TriggerbotEnabled or not miraConfiguracoes.TriggerTricks or miraConfiguracoes.TriggerVersion ~= arg or jogadorLocal.Character ~= valor24 or workspace:FindFirstChild("GrabParts") then
								return false
							end

							if workspace.CurrentCamera ~= cameraAtual2 or arg2.Character ~= valor27 or not valor28.Parent or valor29.Health <= 0 then
								return false
							end

							if UserInputService:GetFocusedTextBox() or api.EhJogadorProtegido(arg2, true) or estadoFuncoes.SilentAim and not api.EhAlvoMiraSilenciosa(arg2) or (valor28.Position - valor25.Position).Magnitude > miraConfiguracoes.TriggerDist then
								return false
							end
							local numero39 = math.min(numero36 / numero38, 1)
							local numero40 = cQuadro2.Position + valor25.Position - posicao
							if (valor28.Position - numero40).Magnitude < 0.001 then
								return false
							end
							local valor32 = cQuadro2.Rotation:Lerp(CFrame.lookAt(numero40, valor28.Position).Rotation, numero39)
							local numero41

							if gatilhoManobra == "180 Flick" then
								numero41 = math.sin(numero39 * 3.1415926535897931) * 3.1415926535897931
							else
								numero41 = numero39 * 3.1415926535897931 * 2 * valor30
							end

							cameraAtual2.CFrame = CFrame.new(numero40) * CFrame.Angles(0, numero41, 0) * valor32
							local numero42 = cameraAtual2.CFrame.LookVector * Vector3.new(1, 0, 1)

							if numero42.Magnitude > 0.001 then
								valor25.CFrame = CFrame.lookAt(valor25.Position, valor25.Position + numero42)
							end
						until numero36 >= numero38

						return true
					end)

					miraConfiguracoes.TriggerSpinning = false

					if valor26.Parent then
						valor26.AutoRotate = autoGirar
					end

					if not (sucesso and resultado) and valor25.Parent then
						valor25.CFrame = CFrame.new(valor25.Position) * rotacao
					end

					if cameraAtual2.Parent then
						if not (sucesso and resultado) then
							cameraAtual2.CFrame = cQuadro2 + valor25.Position - posicao
						end

						cameraAtual2.CameraType = cameraTipo
					end

					return sucesso and resultado
				end

				api.AtualizarTriggerbot = function()
					local miraConfiguracoes = estadoCompartilhado.AimSettings
					if miraConfiguracoes.TriggerBotDebounce then
						return
					end
					local valor24 = api.ObterAlvoGatilho()
					if not valor24 then
						return
					end
					local personagem = jogadorLocal.Character
					local gatilhoVersao = miraConfiguracoes.TriggerVersion
					miraConfiguracoes.TriggerBotDebounce = true

					task.spawn(function()
						pcall(function()
							task.wait(miraConfiguracoes.TriggerDelay)
							if miraConfiguracoes.TriggerVersion ~= gatilhoVersao or jogadorLocal.Character ~= personagem or api.ObterAlvoGatilho() ~= valor24 then
								return
							end

							if miraConfiguracoes.TriggerTricks then
								if not api.ExecutarManobraGatilho(gatilhoVersao, valor24) then
									return
								end
								RunService.Heartbeat:Wait()
							end

							if miraConfiguracoes.TriggerVersion ~= gatilhoVersao or jogadorLocal.Character ~= personagem or api.ObterAlvoGatilho() ~= valor24 then
								return
							end
							local gatilhoChanceAcerto = miraConfiguracoes.TriggerbotHitchance or 100

						if gatilhoChanceAcerto < 100 and math.random(1, 100) > gatilhoChanceAcerto then
							task.wait(miraConfiguracoes.TriggerCooldown or 0.4)
							return
						end

						api.Clicar()
						task.wait(0.2)

							while not descarregado and miraConfiguracoes.TriggerbotEnabled and miraConfiguracoes.TriggerVersion == gatilhoVersao and jogadorLocal.Character == personagem and workspace:FindFirstChild("GrabParts") do
								task.wait()
							end

							if not descarregado and miraConfiguracoes.TriggerVersion == gatilhoVersao then
								task.wait(miraConfiguracoes.TriggerCooldown)
							end
						end)

						miraConfiguracoes.TriggerBotDebounce = false
					end)
				end

				api.AtualizarAssistenciaMira = function()
					local miraConfiguracoes = estadoCompartilhado.AimSettings
					local agarraoPartes = workspace:FindFirstChild("GrabParts")
					local areaVisaoTamanho = cameraAtual.ViewportSize
					local vetor2 = Vector2.new(areaVisaoTamanho.X / 2, areaVisaoTamanho.Y / 2)
					local quadro2 = sobreposicaoZoom.Frame

					if miraConfiguracoes.FOVEnabled then
						local numero36 = miraConfiguracoes.FOVRadius * 2
						local udim2 = UDim2.fromOffset(numero36, numero36)
						local udim22 = UDim2.fromOffset(vetor2.X, vetor2.Y)

						if not quadro2.Visible then
							quadro2.Visible = true
						end

						if quadro2.Size ~= udim2 then
							quadro2.Size = udim2
						end

						if quadro2.Position ~= udim22 then
							quadro2.Position = udim22
						end
					elseif quadro2.Visible then
						quadro2.Visible = false
					end

					if agarraoPartes and not miraConfiguracoes.AimDebounce then
						local agarraoParte = agarraoPartes:FindFirstChild("GrabPart")
						agarraoParte = agarraoParte and agarraoParte:FindFirstChild("WeldConstraint")
						agarraoParte = agarraoParte and agarraoParte.Part1

						if agarraoParte and agarraoParte.Parent and Players:GetPlayerFromCharacter(agarraoParte.Parent) then
							miraConfiguracoes.AimDebounce = true

							task.spawn(function()
								while true do
									task.wait()
									if not (descarregado or not agarraoPartes.Parent) then
										continue
									end
									break
								end

								task.wait(0.3)
								miraConfiguracoes.AimDebounce = false
							end)
						end

						return
					end

					if miraConfiguracoes.AimbotEnabled and not miraConfiguracoes.AimDebounce and not miraConfiguracoes.TriggerSpinning then
						local sempreAo = miraConfiguracoes.AlwaysOn

						if not sempreAo then
							local miraAutoAtalho = opcoes.AimbotKeybind

							if miraAutoAtalho and miraAutoAtalho.Toggled then
								sempreAo = true
							elseif typeof(miraConfiguracoes.AimKey) == "EnumItem" then
								if miraConfiguracoes.AimKey.EnumType == Enum.KeyCode then
									sempreAo = UserInputService:IsKeyDown(miraConfiguracoes.AimKey)
								elseif miraConfiguracoes.AimKey.EnumType == Enum.UserInputType then
									sempreAo = UserInputService:IsMouseButtonPressed(miraConfiguracoes.AimKey)
								end
							end
						end

						local valor24 = sempreAo and api.ObterAlvoMira()

						if valor24 and valor24.Character and valor24.Character:FindFirstChild(miraConfiguracoes.TargetPart) then
							local suavidade = miraConfiguracoes.Smoothness
							cameraAtual.CFrame = cameraAtual.CFrame:Lerp(CFrame.new(cameraAtual.CFrame.Position, valor24.Character[miraConfiguracoes.TargetPart].Position), suavidade)
						end
					end

					if miraConfiguracoes.TriggerbotEnabled and not agarraoPartes then
						api.AtualizarTriggerbot()
					end
				end

				api.AtualizarConexaoMira = function()
