					local valor24, valor25 = api.ObterPersonagem(arg)
					local silenciosaMiraEstado = estadoCompartilhado.SilentAimState
					local valor26 = silenciosaMiraEstado.Players[arg]
					local estado12 = estadoFuncoes.SilentAim and not silenciosaMiraEstado.RaycastActive and api.EhAlvoMiraSilenciosa(arg)

					if valor26 and (not estado12 or valor26.Root ~= valor25) then
