				api.ObterImpactoMiraSilenciosa = function(arg, arg2, arg3)
					local cameraAtual2 = workspace.CurrentCamera
					if not cameraAtual2 or type(arg) ~= "number" or arg <= 0 then
						return
					end
					arg3 = arg3 or cameraAtual2.CFrame.Position
					local numero36 = cameraAtual2.ViewportSize / 2
					local numero37 = valoresConfig.SAIMRadius ^ 2
					local valor24 = nil

					for _, valor25 in ipairs(estadoCompartilhado.PlayerList) do
						if api.EhAlvoMiraSilenciosa(valor25) then
							local valor26, valor27, valor28 = api.ObterPersonagem(valor25)

							if valor27 and valor28 and valor28.Health > 0 then
								local valor29, valor30 = cameraAtual2:WorldToViewportPoint(valor27.Position)

								if valor30 then
									local numero38 = valor29.X - numero36.X
									local numero39 = valor29.Y - numero36.Y
									local numero40 = numero38 * numero38 + numero39 * numero39
									local numero41 = valor27.Position - arg3
									local magnitude = numero41.Magnitude

									if numero40 <= numero37 and magnitude > 0.001 and magnitude <= arg + valor27.Size.Magnitude / 2 then
										local impacto = workspace:Raycast(arg3, numero41.Unit * math.min(arg, magnitude + valor27.Size.Magnitude / 2), arg2)

										if impacto and impacto.Instance:IsDescendantOf(valor26) then
											numero37 = numero40
											valor24 = impacto
										end
									end
								end
							end
						end
					end

					return valor24
				end

				api.DefinirMiraSilenciosa = function(arg)
					local silenciosaMiraEstado = estadoCompartilhado.SilentAimState
					arg = arg and not descarregado

					if arg then
						silenciosaMiraEstado.Failed = nil
					end

					silenciosaMiraEstado.Hit = nil
					silenciosaMiraEstado.HitTime = nil
					api.DefinirAlternadorExecucao("SilentAim", arg)

					api.DefinirConexaoExecucao("SilentAimStatus", RunService.Heartbeat, not descarregado, function()
						if silenciosaMiraEstado.Dirty then
							silenciosaMiraEstado.Dirty = nil
							api.RecarregarMiraSilenciosa()
						end
					end)

					if descarregado then
						local correcao = silenciosaMiraEstado.Patch

						if correcao and getrawmetatable then
							local sucesso, resultado = pcall(getrawmetatable, game)

							if sucesso and resultado.__namecall == correcao.Wrapper then
								pcall(hookmetamethod, game, "__namecall", correcao.Original)
							end
						end

						silenciosaMiraEstado.Patch = nil
						silenciosaMiraEstado.Dirty = nil
						silenciosaMiraEstado.Failed = nil
					elseif not silenciosaMiraEstado.Patch and type(hookmetamethod) == "function" and type(getnamecallmethod) == "function" then
						local correcao = {}

						local function envoltorio(arg2, ...)
							local valor24 = table.pack(...)
							if descarregado or not estadoFuncoes.SilentAim or not silenciosaMiraEstado.RaycastActive or arg2 ~= workspace or getnamecallmethod() ~= "Raycast" or checkcaller and checkcaller() then
								return correcao.Original(arg2, ...)
							end
							local valor25 = ...
							local valor = select(2, ...)
							local valor2 = select(3, ...)
							local cameraAtual2 = workspace.CurrentCamera
							if not cameraAtual2 or typeof(valor25) ~= "Vector3" or typeof(valor) ~= "Vector3" or valor.Magnitude <= 0 or (valor25 - cameraAtual2.CFrame.Position).Magnitude >= 0.1 or valor.Unit:Dot(cameraAtual2.CFrame.LookVector) <= 0.999 then
								return correcao.Original(arg2, table.unpack(valor24, 1, valor24.n))
							end
							local sucesso, resultado = pcall(getcallingscript)
							if sucesso and resultado and resultado.Name ~= "GrabbingScript" and resultado.Name ~= "RaycastModule" then
								return correcao.Original(arg2, table.unpack(valor24, 1, valor24.n))
							end
							local sucesso2, impacto = pcall(api.ObterImpactoMiraSilenciosa, valor.Magnitude, valor2, valor25)

							if sucesso2 and impacto then
								local valor26 = silenciosaMiraEstado
								local valor27 = silenciosaMiraEstado
								local agora3 = os.clock()
								valor26.Hit = impacto
								valor27.HitTime = agora3
								return impacto
							end

							if not sucesso2 then
								silenciosaMiraEstado.Failed = true
								silenciosaMiraEstado.RaycastActive = false
								silenciosaMiraEstado.Dirty = true
							end

							local valor26 = workspace.Raycast(arg2, table.unpack(valor24, 1, valor24.n))
							local valor27 = silenciosaMiraEstado
							local valor28 = silenciosaMiraEstado
							local agora3 = os.clock()
							valor27.Hit = valor26
							valor28.HitTime = agora3
							return valor26
						end

						if newcclosure then
							envoltorio = newcclosure(envoltorio)
						end

						correcao.Wrapper = envoltorio
						local sucesso, original = pcall(hookmetamethod, game, "__namecall", correcao.Wrapper)

						if sucesso and type(original) == "function" then
							correcao.Original = original
							silenciosaMiraEstado.Patch = correcao
						end
					end

					silenciosaMiraEstado.RaycastActive = not descarregado and silenciosaMiraEstado.Patch ~= nil and not silenciosaMiraEstado.Failed
					api.RecarregarMiraSilenciosa()
				end

				api.RastrearJogadorMiraSilenciosa = function(arg)
					bibliotecaUI:GiveSignal(arg.CharacterAdded:Connect(function(personagem)
						local valor24 = descarregado
						local estado12

						if descarregado then
							estado12 = valor24
						else
							estado12 = not estadoFuncoes.SilentAim
						end

						if estado12 then
							return
						end

						if not personagem:WaitForChild("HumanoidRootPart", 5) then
							return
						end

						if not descarregado then
							api.AplicarMiraSilenciosaJogador(arg)
						end
					end))
				end

				api.DerrubarRagdoll = function(arg)
					if not arg or not arg.Parent or estadoCompartilhado.States.Ragdolling then
						return
					end
					local cabeca = arg:FindFirstChild("Head")
					local tronco = cabeca and arg:FindFirstChild("Torso")
					local humanoide = tronco and arg:FindFirstChild("Humanoid")
					humanoide = humanoide and humanoide:FindFirstChild("Ragdolled")

					if humanoide and humanoide.Value == false then
						estadoCompartilhado.States.Ragdolling = true
						local ragdollRSC = pastaBrinquedos:FindFirstChild("RagdollRSC") or api.GerarBrinquedo("PalletLightBrown")
						local somParte = ragdollRSC and ragdollRSC:WaitForChild("SoundPart", 0.5)
						local principal = somParte and ragdollRSC:WaitForChild("Main", 0.5)
						if not principal or not api.DefinirDonoRede(somParte) then
							estadoCompartilhado.States.Ragdolling = false
							return api.DestruirBrinquedo(ragdollRSC)
						end
						ragdollRSC.Name = "RagdollRSC"

						for _, filho in pairs(ragdollRSC:GetChildren()) do
							if filho:IsA("BasePart") then
								filho.CanCollide = false
							end
						end

						if not principal:FindFirstChild("RagdollBP") then
							local corpoPosicao = Instance.new("BodyPosition")
							corpoPosicao.Name = "RagdollBP"
							corpoPosicao.D = 1500
							corpoPosicao.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
							corpoPosicao.Position = Vector3.new(0, 100000, 0)
							corpoPosicao.Parent = principal
						end

						local agora3 = tick()

						while true do
							somParte.Position = tronco.Position
							somParte.Velocity = Vector3.new(0, -10, 0)
							task.wait(0.1)
							if not (humanoide.Value or not principal.Parent or not arg.Parent or not cabeca:FindFirstChild("PartOwner") or tick() - agora3 > 0.5) then
								continue
							end
							break
						end

						estadoCompartilhado.States.Ragdolling = false
						return humanoide.Value
					end
				end

				api.RemoverGrudento = function(arg, arg2)
					if not arg or not arg.Parent then
						return
					end

					for _, valor24 in pairs(arg:QueryDescendants("BasePart")) do
						if valor24.Parent then
							for _, valor25 in pairs(valor24:GetConnectedParts()) do
								if valor25.Name == "StickyPart" then
									for _, filho in pairs(valor25:GetChildren()) do
										if filho:IsA("TouchInterest") then
											filho:Destroy()
										end
									end

									local pai2 = valor25.Parent and api.EncontrarParteIdeal(valor25.Parent)

									if pai2 then
										if not pai2:IsDescendantOf(workspace.PlotItems) then
											api.Segurar(pai2)
										end
									end
								end
							end
						end
					end

					if arg2 then
						return
					end
					local jogadorDePersonagem = Players:GetPlayerFromCharacter(arg)
					if not jogadorDePersonagem then
						return
					end
					local valor24 = api.ObterInventario(jogadorDePersonagem)
					if not valor24 then
						return
					end
					local parteRaizHumanoide = arg:FindFirstChild("HumanoidRootPart") or arg:FindFirstChild("Torso")
					if not parteRaizHumanoide then
						return
					end

					for _, valor25 in valor24:GetChildren() do
						if valor25:IsA("Model") then
							local posicao = parteRaizHumanoide.Position

							if (valor25:GetPivot().Position - posicao).Magnitude < 10 then
								local valor26 = api.EncontrarParteIdeal(valor25)

								if valor26 then
									api.AlternarColisoes(valor25, false)
									api.Segurar(valor26)

									if not valor25:FindFirstChild("StickyPart") then
										if not valor26:FindFirstChild("RscBV") then
											local corpoVelocidade2 = Instance.new("BodyVelocity")
											corpoVelocidade2.Velocity = Vector3.new(0, -50000, 0)
											corpoVelocidade2.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
											corpoVelocidade2.Name = "RscBV"
											corpoVelocidade2.Parent = valor26
										end

										api.MoverPivoPara(valor25, CFrame.new(0, -50000, 0))
										task.delay(1, api.LiberarDonoRede, valor26)
									end
								end
							end
						end
					end
				end

				api.ArrancarMembro = function(arg, arg2)
					local estado12 = arg == jogadorLocal
					if estado12 and estadoFuncoes.GucciAntiGrab then
						return notificar("Não é possível arrancar membros enquanto estiver no modo Gucci!")
					end
					local valor24, valor25, valor26 = api.ObterPersonagem(arg)
					local emRagdoll = valor26 and valor26:FindFirstChild("Ragdolled")
					if not (valor25 and valor26 and valor26.Health ~= 0 and emRagdoll) then
						return
					end
