					api.ConsumirComida = function(arg, arg2)
						local valor22, valor23, valor24 = api.ObterPersonagem()
						local segurarParte = arg and arg:WaitForChild("HoldPart", 0.15)
						local comestivelParte = arg and arg:WaitForChild("EdiblePart", 0.15)

						if segurarParte and valor23 and valor24 and valor24.Health > 0 then
							if not comestivelParte then
								return arg
							end
							local segurarItemRemotoFuncao = segurarParte:WaitForChild("HoldItemRemoteFunction", 0.15)
							local soltarItemRemotoFuncao = segurarParte:WaitForChild("DropItemRemoteFunction", 0.15)
							if not (segurarItemRemotoFuncao and soltarItemRemotoFuncao) then
								return
							end

							task.spawn(function()
								segurarItemRemotoFuncao:InvokeServer(arg, valor22)
							end)

							local agora3 = tick()

							while true do
								task.wait()
								if not (segurarParte.AssemblyRootPart == valor23 or not segurarParte.Parent or valor24.Health == 0 or tick() - agora3 > 0.7) then
									continue
								end
								break
							end

							if not (segurarParte.AssemblyRootPart == valor23) then
								return
							end
							remotos.UsarComida:FireServer(arg, valor22)
							local agora4 = tick()

							while true do
								task.wait()
								if not (not comestivelParte.Parent or not segurarParte.Parent or not (segurarParte.AssemblyRootPart == valor23) or valor24.Health == 0 or tick() - agora4 > 4) then
									continue
								end
								break
							end

							if not segurarParte.Parent or not (segurarParte.AssemblyRootPart == valor23) or tick() - agora4 > 4 then
								task.spawn(function()
									soltarItemRemotoFuncao:InvokeServer(arg)
								end)

								return
							end

							task.spawn(function()
								if arg2 then
									soltarItemRemotoFuncao:InvokeServer(arg)
								else
									soltarItemRemotoFuncao:InvokeServer(arg, segurarParte.CFrame, Vector3.new())
								end
							end)

							local agora5 = tick()

							while true do
								task.wait()
								if not (not (segurarParte.AssemblyRootPart == valor23) or tick() - agora5 > 0.7) then
									continue
								end
								break
							end

							for _, valor25 in valor24:GetPlayingAnimationTracks() do
								local correspondencia = valor25.Animation and valor25.Animation.AnimationId:match("%d+")

								if not (correspondencia and estadoCompartilhado.AnimationWhitelist[correspondencia]) then
									valor25:Stop()
								end
							end

							if not (segurarParte.AssemblyRootPart == valor23) then
								return arg
							end
						end
					end

