								end
							end

							wedge = parteImpactoDetector and wedge

							if wedge then
								if arg2 ~= "BallSnowball" then
									if typeof(arg) == "Instance" then
										remotos.Explodir:FireServer({ Hitbox = parteImpactoDetector, PositionPart = arg }, arg.Position)
									elseif typeof(arg) == "Vector3" then
										remotos.Explodir:FireServer({
