								local tabela18 = {}
								local numero37

								if arg3 then
									numero37 = #arg
								else
									numero37 = #arg - 1
								end

								local numero38 = 0

								for i = 1, numero37 do
									local magnitude = (arg[i % #arg + 1] - arg[i]).Magnitude
