									tabela17.MovePhase = tabela17.MovePhase + (brinquedosAuraConfiguracoes.MoveSpeed or 1) * arg
									tabela17.MovePhase = tabela17.MovePhase % numero38
								else
									tabela17.MovePhase = 0
								end

								if brinquedosAuraConfiguracoes.Bob then
									tabela17.BobPhase = (tabela17.BobPhase + (brinquedosAuraConfiguracoes.BobSpeed or 0) * arg) % 6.2831853071795862
								else
									tabela17.BobPhase = 0
								end

								local valor25 = registroPersonagem.ObterCentro(valor23)

								if brinquedosAuraConfiguracoes.Bob then
									valor25 *= CFrame.new(0, math.sin(tabela17.BobPhase) * (brinquedosAuraConfiguracoes.BobHeight or 0), 0)
								end

								local valor26 = registroPersonagem.ObterForma(numero38)
								local numero39 = #valor26
								if numero39 == 0 then
									return
								end
								local cframe = CFrame.identity

								if brinquedosAuraConfiguracoes.AutoRotate then
									cframe = CFrame.Angles(0, tabela17.ShapePhase, 0)
								end

								for i = 1, numero38 do
									local numero40

									if brinquedosAuraConfiguracoes.AutoMove and numero39 > 1 then
										local numero41 = i + tabela17.MovePhase
										local numero42 = math.floor(numero41)
										numero40 = valor26[(numero42 - 1) % numero39 + 1]:Lerp(valor26[(numero42 + 1 - 1) % numero39 + 1], numero41 - numero42)
									else
										numero40 = valor26[(i - 1) % numero39 + 1]
									end

									if brinquedosAuraConfiguracoes.AutoRotate then
										numero40 = cframe * numero40
									end

									local faceCentro = brinquedosAuraConfiguracoes.FaceCenter
									local posicao = valor25.Position
									registroPersonagem.AtualizarFisica(valido[i], raizes[i], valor25 * CFrame.new(registroPersonagem.ObterDeslocamento(numero40)), faceCentro, posicao)
								end
							end

