				api.RemoverGucci = function(arg)
					local valor22, valor23, valor24 = api.ObterPersonagem()
					local valor25, valor26, valor27 = api.ObterPersonagem(arg)
					local valor28, valor29 = api.ObterInventario(arg)
					local gucciAntiAgarrao = estadoFuncoes.GucciAntiGrab

