					if not gucciAntiAgarrao then
						gucciAntiAgarrao = not (valor24 and valor24.Health > 0 and valor23 and valor28)
					end

					if gucciAntiAgarrao then
						return false
					end

					local function funcao21(arg2)
						if not (arg2 and arg2.Parent) or fracoCache2[arg2] then
							return
						end

						if fracoCache[arg2] then
							return
						end

						if (arg2:IsA("VehicleSeat") or arg2:IsA("Seat")) and not arg2.Occupant then
							fracoCache2[arg2] = true

							if estadoFuncoes.RagdollInRG and valor26 then
