							local conexao = arg2.ChildAdded:Connect(function(filho)
								if filho.Name == "SeatWeld" then
									filho.Enabled = false
									filho:Destroy()
									estado12 = true
								end
							end)

							while true do
								arg2:Sit(valor24)
								aguardarNoMinimo()
								if not (estado12 or tick() - agora3 > 0.5 or not arg2.Parent or valor24.Health <= 0 or descarregado) then
									continue
								end
								break
