		api.PararControlePersonagem = function(arg)
			local controlePersonagem = arg or estadoCompartilhado.States.ControlCharacter
			if not controlePersonagem then
				estadoFuncoes.ControllingSomeone = false
				return
			end

			if controlePersonagem.Cleaned then
				return
			end
			controlePersonagem.Active = false
			controlePersonagem.Cleaned = true

			if controlePersonagem.JumpConnection then
				controlePersonagem.JumpConnection:Disconnect()
			end

			for k, valor22 in controlePersonagem.Parts, nil, nil do
				if k.Parent then
					k.CanCollide = valor22.CanCollide
					k.CanQuery = valor22.CanQuery
				end
			end

			if controlePersonagem.Humanoid.Parent then
				controlePersonagem.Humanoid:Move(Vector3.zero, false)
				controlePersonagem.Humanoid.Jump = false
				controlePersonagem.Humanoid.AutoRotate = controlePersonagem.AutoRotate
			end

			if controlePersonagem.Root.Parent then
				api.LiberarDonoRede(controlePersonagem.Root)
			end

			local valor22, valor23, valor24 = api.ObterPersonagem()

			if valor24 then
				cameraAtual.CameraSubject = valor24
			elseif controlePersonagem.CameraSubject and controlePersonagem.CameraSubject.Parent then
				cameraAtual.CameraSubject = controlePersonagem.CameraSubject
			end

			if controlePersonagem.LocalRoot.Parent and controlePersonagem.LocalHumanoid.Parent and controlePersonagem.LocalHumanoid.Health > 0 then
				api.Teleportar(controlePersonagem.LocalRoot, controlePersonagem.ReturnCFrame)
			end

			if estadoCompartilhado.States.ControlCharacter == controlePersonagem then
				estadoCompartilhado.States.ControlCharacter = nil
				estadoFuncoes.ControllingSomeone = false
			end
		end

		api.ControlarPersonagem = function(arg)
			if estadoCompartilhado.States.ControlCharacter then
				api.PararControlePersonagem()
				return
			end
			local valor22, valor23, valor24 = api.ObterPersonagem()
			if not (valor22 and valor23 and valor24 and valor24.Health > 0) then
				return
			end

			if arg and not arg:FindFirstChildWhichIsA("Humanoid") then
				arg = arg:FindFirstAncestorOfClass("Model")
			end

			if not arg or arg == valor22 then
				return
			end
			local parteRaizHumanoide = arg and arg:FindFirstChild("HumanoidRootPart")
			local humanoide = arg and arg:FindFirstChildWhichIsA("Humanoid")
			if not (parteRaizHumanoide and humanoide and humanoide.Health > 0) then
				return
			end

			local controlePersonagem = {
				Active = true,
				Cleaned = false,
				Character = arg,
				Root = parteRaizHumanoide,
				Humanoid = humanoide,
				LocalRoot = valor23,
				LocalHumanoid = valor24,
				ReturnCFrame = valor23.CFrame,
				CameraSubject = cameraAtual.CameraSubject,
				AutoRotate = humanoide.AutoRotate,
				Parts = {},
			}

			estadoCompartilhado.States.ControlCharacter = controlePersonagem
			estadoFuncoes.ControllingSomeone = true
			if not api.DefinirDonoRede(parteRaizHumanoide) or not controlePersonagem.Active or estadoCompartilhado.States.ControlCharacter ~= controlePersonagem then
				api.PararControlePersonagem(controlePersonagem)
				return
			end

			local function funcao21(arg2, arg3)
				for _, valor25 in arg2:QueryDescendants("BasePart") do
					controlePersonagem.Parts[valor25] = { CanCollide = valor25.CanCollide, CanQuery = valor25.CanQuery }
					valor25.CanCollide = false

					if arg3 then
						valor25.CanQuery = false
					end
				end
			end

			funcao21(valor22, false)
			funcao21(arg, true)
			humanoide.AutoRotate = false
			cameraAtual.CameraSubject = humanoide

			controlePersonagem.JumpConnection = UserInputService.JumpRequest:Connect(function()
				if controlePersonagem.Active and humanoide.Parent then
					humanoide.Jump = true
				end
			end)

			local sucesso, resultado = pcall(function()
				while true do
					if controlePersonagem.Active and not descarregado and estadoCompartilhado.States.ControlCharacter == controlePersonagem and arg.Parent and parteRaizHumanoide.Parent and humanoide.Health > 0 and valor22.Parent and valor23.Parent and valor24.Health > 0 then
						if not (not api.EhDonoDaParte(parteRaizHumanoide) and not api.DefinirDonoRede(parteRaizHumanoide, 0.2)) then
							cameraAtual.CameraSubject = humanoide
							humanoide.Sit = false
							local olharVetor = cameraAtual.CFrame.LookVector
							local vector = Vector3.new(olharVetor.X, 0, olharVetor.Z)

							if vector.Magnitude > 0.001 then
								parteRaizHumanoide.CFrame = CFrame.lookAt(parteRaizHumanoide.Position, parteRaizHumanoide.Position + vector.Unit)
