					return math.huge
				end
				local valor26 = math.rad(arg.Latitude - valor22)
				local valor27 = math.rad(arg.Longitude - valor23)
				local valor28 = math.sin(valor26 / 2)
				local valor29 = math.sin(valor27 / 2)
				return valor28 * valor28 + math.cos(valor25) * math.cos(math.rad(arg.Latitude)) * valor29 * valor29
			end

			if servidorTrocaRegiao == "Automatic" then
				servidorTrocaRegiao = api.ObterContinenteServidor(valor24)

				if not servidorTrocaRegiao and valor22 then
					local enorme = math.huge

