						local valor27 = ipairs
						local tabela16 = servidorTroca.Regions[valor26] or {}

						for _, valor28 in valor27(tabela16) do
							local valor29 = funcao21(valor28)

							if valor29 < enorme then
								enorme = valor29
								servidorTrocaRegiao = valor26
							end
						end
					end
				end
			end

			local valor26 = servidorTroca.Regions[servidorTrocaRegiao]
			if not valor26 or #valor26 == 0 then
				return
			end
			local valor27 = table.clone(valor26)

			table.sort(valor27, function(arg, arg2)
				local valor28 = funcao21(arg)
				local valor29 = funcao21(arg2)

				if valor28 == valor29 then
					local estado12 = arg.Country == valor24
					if estado12 ~= arg2.Country == valor24 then
						return estado12
					end
					return tostring(arg.City) < tostring(arg2.City)
				end

				return valor28 < valor29
			end)

			if texto5 then
				servidorTroca.ResolvedRegions[texto5] = valor27
			end

			return valor27
		end

