		api.ExpulsarServidor = function(arg)
			local expulsaoServidorEstado = estadoCompartilhado.KickServerState
			local tabela16 = {}
			if expulsaoServidorEstado.Running then
				return false
			end
			local agora3 = os.clock()

			for _, valor22 in ipairs(api.ObterAlvos(true, estadoCompartilhado.SelectedPlayers)) do
				local valor23, valor24, valor25 = api.ObterPersonagem(valor22)
				local estado12 = valor24 and valor25 and valor25.Health > 0

				if estado12 then
					estado12 = not arg

					if not estado12 then
						estado12 = agora3 - (estadoCompartilhado.KickServerCooldowns[valor22] or -math.huge) >= 15
					end
				end

				if estado12 then
					tabela16[#tabela16 + 1] = valor22
				end
			end

			if #tabela16 == 0 then
				return false
			end
			expulsaoServidorEstado.Running = true
			local tabela17 = {}
			local tabela18 = {}
			local conexao = nil

			local sucesso, resultado = pcall(function()
				opcoes.LineLagSSlider:SetValue(11)

				if not alternadores.LineLagToggle.Value then
					alternadores.LineLagToggle:SetValue(true)
				end

				alternadores.LineLagToggle:SetDisabled(true)
				local valor22, valor23, valor24 = api.ObterPersonagem()
				if not (valor23 and valor24 and valor24.Health > 0) then
					return
				end
				local posicao = valor23.Position

				conexao = RunService.Heartbeat:Connect(function()
					for k, valor25 in tabela18, nil, nil do
						if k.Parent then
							k.CFrame = valor25
							api.ZerarVelocidade(k)
						else
							tabela18[k] = nil
						end
					end
				end)

				for i, valor25 in ipairs(tabela16) do
					if not descarregado then
						local valor26, valor27, valor28 = api.ObterPersonagem(valor25)

						if valor27 and valor28 and valor28.Health > 0 then
							if arg then
								estadoCompartilhado.KickServerCooldowns[valor25] = os.clock()
							end

							if api.DefinirDonoRede(valor27) then
								local numero36 = i / #tabela16 * 3.1415926535897931 * 2
								local valor29 = tabela17
								local numero37 = #tabela17 + 1
								local valor30 = tabela18
								local cframe = CFrame.new(posicao + Vector3.new(math.cos(numero36) * 15, 15, math.sin(numero36) * 15))
								valor29[numero37] = valor27
								valor30[valor27] = cframe
								api.Teleportar(valor27, tabela18[valor27])
							end
						end

						continue
					end

					break
				end

				for i, valor25 in ipairs(tabela17) do
					local numero36 = i / #tabela17 * 3.1415926535897931 * 2
					tabela18[valor25] = CFrame.new(posicao + Vector3.new(math.cos(numero36) * 15, 15, math.sin(numero36) * 15))
				end

				RunService.Heartbeat:Wait()
			end)

			task.spawn(function()
				local numero36 = os.clock() + 3

				while not descarregado and os.clock() < numero36 do
					RunService.Heartbeat:Wait()
				end

				if conexao then
					conexao:Disconnect()
					conexao = nil
				end
			end)

			task.wait(0.15)

			for _, valor22 in ipairs(tabela17) do
				if valor22.Parent then
					api.LiberarDonoRede(valor22)
				end
			end

			for _, valor22 in ipairs(tabela17) do
				if not descarregado and valor22.Parent then
					task.spawn(api.RemoverGrudento, valor22.Parent)
				end
			end

			task.wait(6)

			if not descarregado then
				alternadores.LineLagToggle:SetDisabled(false)
				alternadores.LineLagToggle:SetValue(false)
			end

			expulsaoServidorEstado.Running = false

			if not sucesso then
				warn("[Brazuka] Target Kick Server failed: " .. tostring(resultado))
			end

			return sucesso and #tabela17 > 0
		end

