		task.spawn(function()
			local marcaDaguaFPS = 60
			local marcaDaguaPing = 0
			local marcaDaguaUltimoTexto = nil

			while Watermark and Watermark.Label and Watermark.Label.Parent do
				if descarregado then
					return
				end
				if not Watermark.Label.Visible then
					task.wait(0.5)
					continue
				end

				local atualizarVelocidade = math.clamp(tonumber(valoresConfig.WatermarkUpdateSpeed) or 1, 0.1, 5)
				local suavizacao = math.clamp(tonumber(valoresConfig.WatermarkSmoothing) or 0.2, 0, 0.9)
				local dadosPing = Estatisticas2.Network.ServerStatsItem["Data Ping"]
				marcaDaguaFPS = Estatisticas2.Workspace.Heartbeat:GetValue() * (1 - suavizacao) + marcaDaguaFPS * suavizacao
				marcaDaguaPing = dadosPing:GetValue() * (1 - suavizacao) + marcaDaguaPing * suavizacao

				local marcaDaguaPartes = {}

				if not alternadores.WatermarkVersion or alternadores.WatermarkVersion.Value then
					table.insert(marcaDaguaPartes, "Brazuka 13/22")
				end

				if not alternadores.WatermarkFPS or alternadores.WatermarkFPS.Value then
					table.insert(marcaDaguaPartes, ("%d fps"):format(math.floor(marcaDaguaFPS + 0.5)))
				end

				if not alternadores.WatermarkPing or alternadores.WatermarkPing.Value then
					table.insert(marcaDaguaPartes, ("%d ms"):format(math.floor(marcaDaguaPing + 0.5)))
				end

				if alternadores.WatermarkTime and alternadores.WatermarkTime.Value then
					table.insert(marcaDaguaPartes, os.date("%H:%M:%S"))
				end

				local marcaDaguaTexto = table.concat(marcaDaguaPartes, " | ")

				if marcaDaguaTexto ~= marcaDaguaUltimoTexto then
					marcaDaguaUltimoTexto = marcaDaguaTexto
					Watermark.SetText(Watermark, marcaDaguaTexto)
				end

				task.wait(atualizarVelocidade)
			end
		end)

