			local suporte = avatar and avatar.Holder
			local imagem = suporte and suporte:FindFirstChildWhichIsA("ImageLabel", true)
			if not imagem then return end
			for tentativa = 1, 6 do
				if descarregado or avatar.Destroyed or not imagem.Parent then return end
				local sucesso, conteudo, pronto = pcall(function()
					return Players:GetUserThumbnailAsync(jogadorLocal.UserId, Enum.ThumbnailType.AvatarBust, Enum.ThumbnailSize.Size180x180)
				end)
				if descarregado or avatar.Destroyed or not imagem.Parent then return end
				if sucesso and pronto and type(conteudo) == "string" and conteudo ~= "" then
					imagem.Image = conteudo
					imagem.ImageColor3 = Color3.new(1, 1, 1)
					imagem.ImageTransparency = 0
					imagem.ImageRectOffset = Vector2.zero
					imagem.ImageRectSize = Vector2.zero
					avatar.Image = conteudo
				end
				task.wait(math.min(tentativa * 0.5, 2))
				if descarregado or avatar.Destroyed or not imagem.Parent then return end
				if imagem.IsLoaded then return end
			end
			if not descarregado and imagem.Parent then
