			local AnimS = Animacoes:AddSlider("AnimS", { Text = "Velocidade da Animação", Default = 1, Min = 0, Max = 100 })
			local valor22 = nil
			local texto5 = "Struggle"

			local function funcao21()
				if valor22 then
					valor22:Stop()
					valor22:Destroy()
					valor22 = nil
				end
			end

			local function funcao22(arg)
				funcao21()
				if not (alternadores.AnimationToggle and alternadores.AnimationToggle.Value) then
					return
				end
				local personagem = jogadorLocal.Character
				if not personagem then
					return
				end
				local humanoide = personagem:FindFirstChildOfClass("Humanoid")
				if not humanoide then
					return
				end
				local animator = humanoide:FindFirstChildOfClass("Animator")
				if not animator then
					return
				end
				local valor23 = tabela16[arg]
				if not valor23 then
					return
				end
				local animacao = Instance.new("Animation")
				animacao.AnimationId = valor23
				valor22 = animator:LoadAnimation(animacao)
				valor22.Looped = true
				valor22:Play()
				valor22:AdjustSpeed(AnimS.Value)
				texto5 = arg
			end

			local function funcao23()
				if texto5 then
					funcao22(texto5)
				end
			end

			Animacoes:AddToggle("AnimationToggle", {
				Text = "Ativar Animação",
				Default = false,
				Callback = function(arg)
					if not arg then
						funcao21()
					else
						funcao23()
					end
				end,
			})

			AnimS:OnChanged(function()
				if valor22 then
					valor22:AdjustSpeed(AnimS.Value)
				end
			end)

			AnimacaoParaTocar:OnChanged(function(arg)
				texto5 = arg

				if alternadores.AnimationToggle and alternadores.AnimationToggle.Value then
					funcao22(AnimacaoParaTocar.Value)
				end
			end)

			jogadorLocal.CharacterAdded:Connect(function()
				task.wait(1)

				if alternadores.AnimationToggle and alternadores.AnimationToggle.Value then
					funcao21()
					funcao22(AnimacaoParaTocar.Value)
				end
			end)
		end
	end

