				task.spawn(function()
					local tabela16 = {}

					local function funcao21(descendente)
						if descendente:IsA("BasePart") and descendente.Name == "PaintPlayerPart" then
							descendente.CanTouch = not antiTinta

							if antiTinta then
								tabela16[descendente] = descendente:GetPropertyChangedSignal("CanTouch"):Connect(function()
									if not estadoFuncoes.AntiPaint then
										return
									end
									descendente.CanTouch = false
								end)
							end
						end
					end

					for _, valor20 in pairs(workspace:QueryDescendants("BasePart#PaintPlayerPart")) do
						funcao21(valor20)
					end

					if antiTinta then
						local conexao = workspace.DescendantAdded:Connect(funcao21)

						repeat
							task.wait()
						until not estadoFuncoes.AntiPaint

						conexao:Disconnect()

						for _, valor20 in pairs(tabela16) do
							valor20:Disconnect()
						end
					end
				end)
			end,
		})

