			Callback = function(arg)
				local buraco = mapa:FindFirstChild("Hole")
				local venenoGrandeBuraco = buraco and buraco:FindFirstChild("PoisonBigHole")
				buraco = buraco and buraco:FindFirstChild("PoisonSmallHole")

				for _, valor20 in pairs({ venenoGrandeBuraco, buraco }) do
					if valor20 then
						local venenoDanoParte = valor20:FindFirstChild("PoisonHurtPart")
						local tintaJogadorParte = valor20:FindFirstChild("PaintPlayerPart")

						if venenoDanoParte then
							venenoDanoParte.CanTouch = not arg
