		Diversos_2:AddToggle("WaterWalk", {
			Text = "Andar Sobre a Água",
			Default = false,
			Tooltip = "Permite andar sobre a água",
			Callback = function(arg)
				for _, filho in pairs(objetosFixosInterpolados.Ocean.Object.ObjectModel:GetChildren()) do
					local tabela16 = estadoCompartilhado.WaterPartStates[filho]

					if arg and not tabela16 then
						tabela16 = { filho.CanCollide, filho.Transparency }
						estadoCompartilhado.WaterPartStates[filho] = tabela16
					end

					if arg then
						filho.CanCollide = true

						if filho.Transparency ~= 1 and tabela16[2] ~= 1 then
							filho.Transparency = 0.5
						end
					elseif tabela16 then
						filho.CanCollide = tabela16[1]
						local transparencia

						if alternadores.CustomWaterT and alternadores.CustomWaterT.Value then
							transparencia = 1
						else
							transparencia = tabela16[2]
						end

						filho.Transparency = transparencia

						if not (alternadores.CustomWaterT and alternadores.CustomWaterT.Value) then
							estadoCompartilhado.WaterPartStates[filho] = nil
						end
					end
				end
			end,
		})

		Diversos_2:AddToggle("DeleteBarriers", {
			Text = "Atravessar Barreiras",
			Default = false,
			Callback = function(arg)
				local lotes = workspace:FindFirstChild("Plots")
				if not lotes then
					return
				end

				for _, filho in ipairs(lotes:GetChildren()) do
					local barreira = filho:FindFirstChild("Barrier")

					if barreira then
						for _, filho2 in ipairs(barreira:GetChildren()) do
							if filho2:IsA("BasePart") and filho2.Name == "PlotBarrier" then
								filho2.CanCollide = not arg
							end
						end
					end
				end
			end,
		})

		Diversos_2:AddToggle("OtherInvCollisions", {
			Text = "Anti-Arremesso [Objetos Sem Colisão]",
