				local antiExpulsaoPredefinicao = valoresConfig.AKPresetChoice or (opcoes.AKPreset and opcoes.AKPreset.Value)

				local antiExpulsaoPredefinicoes = {
					["Pickaxe on Back"] = { 0, 0.2, 1.1, 45, 0, 180 },
					["Head Katana"] = { 0, 1.6, 0, 45, 0, 0 },
					["Ass Shuriken"] = { 0, 0.4, -1, 90, 0, 0 },
					["Belt Kunai"] = { 1.2, 0.2, 0, 0, 0, 90 },
					["Pencil Penis"] = { 0, -0.4, 0.9, 0, 90, 0 },
				}
				local predefinicao = antiExpulsaoPredefinicoes[antiExpulsaoPredefinicao]

				if not predefinicao then
					return notificar("Selecione uma predefinição primeiro!")
				end

				valoresConfig.AKOffsetX, valoresConfig.AKOffsetY, valoresConfig.AKOffsetZ = predefinicao[1], predefinicao[2], predefinicao[3]
				valoresConfig.AKRotX, valoresConfig.AKRotY, valoresConfig.AKRotZ = predefinicao[4], predefinicao[5], predefinicao[6]

				if opcoes.AKOffsetXS then
					opcoes.AKOffsetXS:SetValue(predefinicao[1])
				end

				if opcoes.AKOffsetYS then
					opcoes.AKOffsetYS:SetValue(predefinicao[2])
				end

				if opcoes.AKOffsetZS then
					opcoes.AKOffsetZS:SetValue(predefinicao[3])
				end

				if opcoes.AKRotXS then
					opcoes.AKRotXS:SetValue(predefinicao[4])
				end

				if opcoes.AKRotYS then
					opcoes.AKRotYS:SetValue(predefinicao[5])
				end

				if opcoes.AKRotZS then
					opcoes.AKRotZS:SetValue(predefinicao[6])
				end

				if estadoFuncoes.AntiKick then
					aplicarAntiExpulsaoDeslocamentos()
				end
			end,
		})

		PredefinicoesAba:AddInput("AKCustomPresetName", {
			Text = "Nome da Predefinição",
			ClearTextOnFocus = false,
			Callback = function() end,
		})

		PredefinicoesAba:AddButton({
			Text = "Salvar Predefinição",
			Icon = "settings",
			Func = function()
				local predefinicaoNome = opcoes.AKCustomPresetName and opcoes.AKCustomPresetName.Value or ""

				if predefinicaoNome == "" then
					return notificar("Digite um nome para a predefinição primeiro!")
				end

				if not (writefile and makefolder and isfolder) then
					return notificar("Seu executor não suporta predefinições em arquivo.")
				end

				local sucesso = pcall(function()
					if not isfolder("Brazuka") then
						makefolder("Brazuka")
					end

					if not isfolder("Brazuka/AntiKickPresets") then
						makefolder("Brazuka/AntiKickPresets")
					end

					writefile("Brazuka/AntiKickPresets/" .. predefinicaoNome .. ".json", HttpService:JSONEncode({
						X = valoresConfig.AKOffsetX,
						Y = valoresConfig.AKOffsetY,
						Z = valoresConfig.AKOffsetZ,
						RotX = valoresConfig.AKRotX,
						RotY = valoresConfig.AKRotY,
						RotZ = valoresConfig.AKRotZ,
					}))
				end)

				notificar(sucesso and ("Predefinição salva: " .. predefinicaoNome) or "Não foi possível salvar o arquivo da predefinição.")
			end,
		})

		PredefinicoesAba:AddButton({
			Text = "Carregar Predefinição",
			Icon = "settings-2",
			Func = function()
				local predefinicaoNome = opcoes.AKCustomPresetName and opcoes.AKCustomPresetName.Value or ""

				if predefinicaoNome == "" then
					return notificar("Digite um nome para a predefinição primeiro!")
				end

				if not (readfile and isfile) then
					return notificar("Seu executor não suporta predefinições em arquivo.")
				end

				local caminho = "Brazuka/AntiKickPresets/" .. predefinicaoNome .. ".json"

				if not isfile(caminho) then
					return notificar("Predefinição não encontrada: " .. predefinicaoNome)
				end

				local sucesso, result = pcall(function()
					return HttpService:JSONDecode(readfile(caminho))
				end)

				if not sucesso or type(resultado) ~= "table" then
					return notificar("Não foi possível ler o arquivo da predefinição.")
				end

				valoresConfig.AKOffsetX = tonumber(resultado.X) or 0
				valoresConfig.AKOffsetY = tonumber(resultado.Y) or -0.3
				valoresConfig.AKOffsetZ = tonumber(resultado.Z) or 0
				valoresConfig.AKRotX = tonumber(resultado.RotX) or 90
				valoresConfig.AKRotY = tonumber(resultado.RotY) or 0
				valoresConfig.AKRotZ = tonumber(resultado.RotZ) or 0

				if opcoes.AKOffsetXS then
					opcoes.AKOffsetXS:SetValue(valoresConfig.AKOffsetX)
				end

				if opcoes.AKOffsetYS then
					opcoes.AKOffsetYS:SetValue(valoresConfig.AKOffsetY)
				end

				if opcoes.AKOffsetZS then
					opcoes.AKOffsetZS:SetValue(valoresConfig.AKOffsetZ)
				end

				if opcoes.AKRotXS then
					opcoes.AKRotXS:SetValue(valoresConfig.AKRotX)
				end

				if opcoes.AKRotYS then
					opcoes.AKRotYS:SetValue(valoresConfig.AKRotY)
				end

				if opcoes.AKRotZS then
					opcoes.AKRotZS:SetValue(valoresConfig.AKRotZ)
				end

				if estadoFuncoes.AntiKick then
					aplicarAntiExpulsaoDeslocamentos()
				end

				notificar("Predefinição carregada: " .. predefinicaoNome)
			end,
