		api.PastasOrigemBrinquedos = function()
			local loteItens = workspace:FindFirstChild("PlotItems")
			local tabela16

			if estadoFuncoes.ToysAuraOnlyPlot and loteItens then
				tabela16 = {}

				for _, filho in loteItens:GetChildren() do
					table.insert(tabela16, filho)
				end
			elseif brinquedosAuraConfiguracoes.OwnInventoryOnly then
				return { pastaBrinquedos }
			else
				tabela16 = estadoCompartilhado.Inventories
			end

			if not estadoFuncoes.ToysAuraExcludeProtected then
				return tabela16
			end

			local pastaLotes = workspace:FindFirstChild("Plots")
			local loteDonoNomes = nil

			if pastaLotes and loteItens then
				loteDonoNomes = {}

				for _, lote in pastaLotes:GetChildren() do
					local lotePlaca = lote:FindFirstChild("PlotSign")
					local loteDonos = lotePlaca and lotePlaca:FindFirstChild("ThisPlotsOwners")

					if loteDonos then
						for _, donoValor in loteDonos:GetChildren() do
							if donoValor:IsA("StringValue") then
								loteDonoNomes[lote.Name] = donoValor.Value
							end
						end
					end
				end
			end

			local function ehProtegidoDono(donoNome)
				if donoNome == jogadorLocal.Name then
					return true
				end

				local dono = Players:FindFirstChild(donoNome)

				return dono ~= nil and estadoCompartilhado.Whitelisted[dono] == true
			end

			local tabela17 = {}

			for _, valor22 in tabela16 do
				local donoNome = valor22.Name:match("^(.+)SpawnedInToys$")
				local pularPasta = false

				if donoNome then
					pularPasta = ehProtegidoDono(donoNome)
				elseif valor22 == pastaBrinquedos then
					pularPasta = true
				elseif loteDonoNomes and loteDonoNomes[valor22.Name] then
					pularPasta = ehProtegidoDono(loteDonoNomes[valor22.Name])
				end

				if not pularPasta then
					table.insert(tabela17, valor22)
				end
			end

			return tabela17
		end

		api.BrinquedoPermitido = function(arg)
			local brinquedoListaBranca = estadoCompartilhado.ToyWhitelist

			if brinquedoListaBranca and brinquedoListaBranca[arg.Name] then
				return false
			end

			return true
		end

		local function atualizarBrinquedoListaBrancaValores()
			local tabela16 = {}

			for _, valor22 in estadoCompartilhado.Inventories do
				for _, filho in valor22:GetChildren() do
					if filho:IsA("Model") then
						local nome = filho.Name

						if not tabela16[nome] then
							tabela16[nome] = true
						end
					end
				end
			end

			local tabela17 = {}

			for nome in tabela16 do
				table.insert(tabela17, nome)
			end

			table.sort(tabela17)

			if opcoes.ToyWhitelist then
				opcoes.ToyWhitelist:SetValues(tabela17)
			end
		end

