	do
		local Camera = abas.Visual:AddRightGroupbox("Câmera", "camera")

		Camera:AddToggle("DisableBlurT", {
			Text = "Desativar Desfoque de Ragdoll",
			Default = false,
			Callback = function(arg)
				local desfoque = cameraAtual.Blur

				if desfoque then
					desfoque.Enabled = not arg
				end
			end,
		})

		Camera:AddDivider()

		local thirdPersonModal = Instance.new("TextButton")
		thirdPersonModal.Name = "BrazukaThirdPersonModal"
		thirdPersonModal.BackgroundTransparency = 1
		thirdPersonModal.BorderSizePixel = 0
		thirdPersonModal.Size = UDim2.fromOffset(0, 0)
		thirdPersonModal.Text = ""
		thirdPersonModal.Active = false
		thirdPersonModal.Visible = false
		thirdPersonModal.Modal = false
		thirdPersonModal.ZIndex = -999
		thirdPersonModal.Parent = bibliotecaUI.ScreenGui

		local ultimoEstadoTP = false
		local comportamentoAntesTP = nil

		local function menuOuManualQuerCursorLivre()
			local rfW = bibliotecaUI.RFWindow
			local menuAberto = rfW and rfW.settings and rfW.settings.mouseOverride and (not rfW.hidden) and (not rfW.minimised) and (not rfW.unloaded)
			local manualLivre = alternadores.UnlockMouse and alternadores.UnlockMouse.Value == true
			return menuAberto or manualLivre
		end

		local function estaEmTerceiraPessoa()
			if descarregado then return false end
			if jogadorLocal.CameraMode == Enum.CameraMode.LockFirstPerson then
				return false
			end
			local cam = workspace.CurrentCamera
			if cam then
				return (cam.CFrame.Position - cam.Focus.Position).Magnitude > 1.5
			end
			return (alternadores.ThirdpersonT and alternadores.ThirdpersonT.Value == true) or false
		end

		local function restaurarMouseNormal()
			bibliotecaUI._thirdPersonUnlock = false
			thirdPersonModal.Visible = false
			thirdPersonModal.Modal = false
			local rfW = bibliotecaUI.RFWindow
			if rfW and rfW._syncModal then
				pcall(rfW._syncModal, rfW)
			end
			if not menuOuManualQuerCursorLivre() then
				local cam = workspace.CurrentCamera
				local emPrimeira = (jogadorLocal.CameraMode == Enum.CameraMode.LockFirstPerson) or (cam and (cam.CFrame.Position - cam.Focus.Position).Magnitude <= 1.5)
				if emPrimeira then
					UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
					UserInputService.MouseIconEnabled = bibliotecaUI.OriginalMouseIconEnabled
				elseif comportamentoAntesTP then
					UserInputService.MouseBehavior = comportamentoAntesTP
					UserInputService.MouseIconEnabled = bibliotecaUI.OriginalMouseIconEnabled
				else
					UserInputService.MouseBehavior = Enum.MouseBehavior.Default
					UserInputService.MouseIconEnabled = true
				end
			end
			comportamentoAntesTP = nil
		end

		local function sincronizarMouseTerceiraPessoa()
			local tp = estaEmTerceiraPessoa()
			local segurandoRMB = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
			if tp then
				if not ultimoEstadoTP then
					ultimoEstadoTP = true
					if not segurandoRMB then
						comportamentoAntesTP = UserInputService.MouseBehavior
					end
				end
				bibliotecaUI._thirdPersonUnlock = true
				thirdPersonModal.Visible = not segurandoRMB
				thirdPersonModal.Modal = not segurandoRMB
				if not segurandoRMB then
					if UserInputService.MouseBehavior ~= Enum.MouseBehavior.Default then
						UserInputService.MouseBehavior = Enum.MouseBehavior.Default
					end
					if not UserInputService.MouseIconEnabled then
						UserInputService.MouseIconEnabled = true
					end
				end
			else
				if ultimoEstadoTP then
					ultimoEstadoTP = false
					restaurarMouseNormal()
				else
					bibliotecaUI._thirdPersonUnlock = false
					thirdPersonModal.Visible = false
					thirdPersonModal.Modal = false
				end
			end
		end

		api._desligarMouseTerceiraPessoa = function()
			if ultimoEstadoTP then
				ultimoEstadoTP = false
				restaurarMouseNormal()
			else
				bibliotecaUI._thirdPersonUnlock = false
				thirdPersonModal.Visible = false
				thirdPersonModal.Modal = false
			end
		end

		local connCamTP = nil
		local function vincularCamTP(cam)
			if connCamTP then pcall(function() connCamTP:Disconnect() end) connCamTP = nil end
			if cam then
				connCamTP = bibliotecaUI:GiveSignal(cam:GetPropertyChangedSignal("CFrame"):Connect(function()
					if not descarregado then
						sincronizarMouseTerceiraPessoa()
					end
				end))
			end
		end
		vincularCamTP(workspace.CurrentCamera)
		bibliotecaUI:GiveSignal(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(vincularCamTP))
		bibliotecaUI:GiveSignal(jogadorLocal:GetPropertyChangedSignal("CameraMode"):Connect(sincronizarMouseTerceiraPessoa))
		bibliotecaUI:GiveSignal(UserInputService:GetPropertyChangedSignal("MouseBehavior"):Connect(function()
			if estaEmTerceiraPessoa() and not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
				UserInputService.MouseBehavior = Enum.MouseBehavior.Default
				UserInputService.MouseIconEnabled = true
			end
		end))
		bibliotecaUI:GiveSignal(UserInputService:GetPropertyChangedSignal("MouseIconEnabled"):Connect(function()
			if estaEmTerceiraPessoa() and not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) and not UserInputService.MouseIconEnabled then
				UserInputService.MouseIconEnabled = true
			end
		end))
		bibliotecaUI:GiveSignal(UserInputService.InputBegan:Connect(function(inp)
			if inp.UserInputType == Enum.UserInputType.MouseButton2 then
				sincronizarMouseTerceiraPessoa()
			end
		end))
		bibliotecaUI:GiveSignal(UserInputService.InputEnded:Connect(function(inp)
			if inp.UserInputType == Enum.UserInputType.MouseButton2 then
				sincronizarMouseTerceiraPessoa()
			end
		end))
		sincronizarMouseTerceiraPessoa()

		Camera:AddToggle("ThirdpersonT", {
			Text = "Terceira Pessoa",
			Default = false,
			Callback = function(arg)
				if arg then
					jogadorLocal.CameraMode = "Classic"
					jogadorLocal.CameraMaxZoomDistance = "inf"
					jogadorLocal.CameraMinZoomDistance = 20
					jogadorLocal.CameraMinZoomDistance = 0.5
				else
					jogadorLocal.CameraMode = "LockFirstPerson"
				end
				sincronizarMouseTerceiraPessoa()
				task.defer(sincronizarMouseTerceiraPessoa)
			end,
		}):AddKeyPicker("ThirdPersonK", {
			Text = "Terceira Pessoa",
			Default = "Three",
			Mode = "Toggle",
			NoUI = false,
			SyncToggleState = true,
		})

		Camera:AddToggle("CameraNoclip", { Text = "Câmera Sem Colisão", Default = false, Callback = api.DefinirCameraSemColisao })

		Camera:AddSlider("FOVsl", {
			Text = "Campo de Visão (FOV)",
			Default = 70,
			Min = 30,
			Max = 120,
			Callback = function(arg)
				api.DefinirCampoVisao(arg, false)
			end,
		})

		Camera:AddDivider()

		local function funcao21(localTransparenciaModificador)
			if not localTransparenciaModificador then
				return
			end
			local valor20 = api.ObterPersonagem()
			if not (valor20 and valor20:FindFirstChild("Head")) then
				return
			end

			if (cameraAtual.CFrame.Position - cameraAtual.Focus.Position).Magnitude > 1.5 then
				localTransparenciaModificador = 0
			end

			for _, filho in ipairs(valor20:GetChildren()) do
				if filho:IsA("BasePart") and filho.Name ~= "Head" and filho.Name ~= "HumanoidRootPart" and filho.Name ~= "Torso" then
					filho.LocalTransparencyModifier = localTransparenciaModificador
				end
			end
		end

		local function funcao22()
			funcao21(opcoes.RFPTransparency.Value)
		end

		Camera:AddToggleSlider("RealisticFirstPersonT", {
			Text = "Primeira Pessoa Realista",
			Default = false,
			Callback = function(arg)
				api.DefinirConexaoExecucao("RealisticFirstPerson", RunService.RenderStepped, arg, funcao22)

				if arg then
					funcao22()
				else
					funcao21(1)
				end
			end,
		}, "RFPTransparency", {
			Text = "Transparência",
			Default = 0.3,
			Min = 0,
			Max = 1,
			Rounding = 2,
			Callback = function()
				if alternadores.RealisticFirstPersonT.Value then
					funcao22()
				end
			end,
		})
	end

	do
		local Graficos = abas.Visual:AddRightGroupbox("Gráficos", "file-image")
		local numero36 = 0
		local numero37 = 0.004
		local numero38 = 128

		local function funcao21(arg)
			if os.clock() - arg < numero37 then
				return arg
			end
			RunService.Heartbeat:Wait()
			return os.clock()
		end

		local function funcao22(arg)
			local agora2 = os.clock()

			for i = #estadoCompartilhado.WaterParts, 1, -1 do
				if arg ~= numero36 then
					return false
				end
				local valor20 = estadoCompartilhado.WaterParts[i]
				local valor21 = valor20[1]
				local transparencia = valor20[2]

				if valor21 and valor21.Parent then
					local valor = alternadores.WaterWalk and alternadores.WaterWalk.Value

					if valor and transparencia ~= 1 then
						transparencia = 0.5
					end

					valor21.Transparency = transparencia

					if not valor and estadoCompartilhado.WaterPartStates[valor21] then
						valor21.CanCollide = estadoCompartilhado.WaterPartStates[valor21][1]
						estadoCompartilhado.WaterPartStates[valor21] = nil
					end
				end

				estadoCompartilhado.WaterParts[i] = nil
				agora2 = funcao21(agora2)
			end

			for i = #estadoCompartilhado.WaterRegions, 1, -1 do
				if arg ~= numero36 then
					return false
				end
				terreno:FillRegion(estadoCompartilhado.WaterRegions[i], 4, Enum.Material.Air)
				estadoCompartilhado.WaterRegions[i] = nil
				agora2 = funcao21(agora2)
			end

			table.clear(estadoCompartilhado.WaterRegions)
			table.clear(estadoCompartilhado.WaterParts)
			return true
		end

		local function funcao23(arg, arg2, arg3, arg4)
			local valor20 = Region3.new(arg, arg2):ExpandToGrid(4)
			local numero39 = valor20.CFrame.Position - valor20.Size / 2
			local numero40 = valor20.CFrame.Position + valor20.Size / 2
			local x = numero39.X

			while x < numero40.X do
				local numero41 = math.min(x + numero38, numero40.X)
				local y = numero39.Y
				local sairPara = nil

				while true do
					if not (y < numero40.Y) then
						sairPara = 1
						break
					else
						local numero42 = math.min(y + numero38, numero40.Y)
						local z = numero39.Z
						local sairPara2 = nil

						while true do
							if not (z < numero40.Z) then
								sairPara2 = 1
								break
							else
								if arg3 == numero36 then
									local numero43 = math.min(z + numero38, numero40.Z)
									local valor21 = Region3.new(Vector3.new(x, y, z), Vector3.new(numero41, numero42, numero43))
									estadoCompartilhado.WaterRegions[#estadoCompartilhado.WaterRegions + 1] = valor21
									terreno:FillRegion(valor21, 4, Enum.Material.Water)
									arg4 = funcao21(arg4)
									z = numero43
									continue
								end

								break
							end
						end

						if sairPara2 == 1 then
							y = numero42
							continue
						end
						break
					end
				end

				if sairPara == 1 then
					x = numero41
					continue
				end
				return arg4, false
			end

			return arg4, true
		end

		local function funcao24(arg)
			numero36 += 1
			local valor20 = numero36

			task.spawn(function()
				if not funcao22(valor20) or not arg then
					return
				end
				local objetoModelo = workspace.Map.AlwaysHereTweenedObjects.Ocean.Object.ObjectModel
				local vector = Vector3.new(0, valoresConfig.WaterYOffset, 0)
				local tabela16 = {}

				for _, valor21 in ipairs(objetoModelo:QueryDescendants("BasePart")) do
					local tabela17 = estadoCompartilhado.WaterPartStates[valor21]

					if not tabela17 then
						if valor21.Transparency == 1 then
							continue
						end
						tabela17 = { valor21.CanCollide, valor21.Transparency }
						estadoCompartilhado.WaterPartStates[valor21] = tabela17
					end

					if tabela17[2] ~= 1 then
						tabela16[#tabela16 + 1] = { valor21, tabela17[2], valor21.Position - valor21.Size / 2 + vector, valor21.Position + valor21.Size / 2 + vector }
					end
				end

				for _, valor21 in ipairs(tabela16) do
					local valor22 = valor21[1]

					if valor22.Parent then
						estadoCompartilhado.WaterParts[#estadoCompartilhado.WaterParts + 1] = { valor22, valor21[2] }
						valor22.Transparency = 1
					end
				end

				local agora2 = os.clock()

				for _, valor21 in ipairs(tabela16) do
					if valor20 ~= numero36 then
						return
					end
					local valor22, valor23 = funcao23(valor21[3], valor21[4], valor20, agora2)
					if not valor23 then
						return
					end
					agora2 = valor22
				end
			end)
		end

