			Callback = function(arg)
				if arg then
					local selecionadoACPoseAlvo = valoresConfig.SelectedACPoseTarget
					valoresConfig.SelectedACPoseTarget = nil
					estadoFuncoes.IndependentACPoses = true

					if api.SincronizarAlvosPoseAC then
						api.SincronizarAlvosPoseAC(selecionadoACPoseAlvo)
					end
				else
					if valoresConfig.SelectedACPoseTarget then
