		valor20:SetupDependencies({ { alternadores.IndependentACPoses, true } })

		valor20:AddDropdown("ACPoseTarget", {
			Values = {},
			Default = nil,
			Multi = false,
			Searchable = true,
			AllowNull = true,
			Text = "Editar Pose do Alvo",
			FormatListValue = api.FormatarJogador,
			FormatDisplayValue = api.FormatarJogador,
			Callback = function(arg)
				local valor21

				if type(arg) ~= "string" then
					valor21 = arg
				else
					valor21 = Players:FindFirstChild(arg)
				end

				local selecionadoACPoseAlvo = valoresConfig.SelectedACPoseTarget

				if selecionadoACPoseAlvo and selecionadoACPoseAlvo ~= valor21 then
					api.CapturarPoseAutoClique(selecionadoACPoseAlvo)
				end

				valoresConfig.SelectedACPoseTarget = valor21

				if valor21 then
					task.defer(api.CarregarPoseEditorAC, estadoCompartilhado.AutoClickerTargetPoses[valor21.UserId] or api.CapturarPoseAutoClique(valor21))
				end
			end,
		})

		api.SincronizarAlvosPoseAC = function(arg)
			if not opcoes.ACPoseTarget then
				return
			end

			if estadoFuncoes.IndependentACPoses and valoresConfig.SelectedACPoseTarget then
				api.CapturarPoseAutoClique(valoresConfig.SelectedACPoseTarget)
			end

			local tabela16 = {}

			for k in pairs(estadoCompartilhado.SelectedPlayersAC) do
				if k and k.Parent then
					tabela16[#tabela16 + 1] = k.Name

					if estadoFuncoes.IndependentACPoses and not estadoCompartilhado.AutoClickerTargetPoses[k.UserId] then
						api.CapturarPoseAutoClique(k)
					end
				end
			end

			table.sort(tabela16, function(arg2, arg3)
				return arg2:lower() < arg3:lower()
			end)

			opcoes.ACPoseTarget:SetValues(tabela16)
			local selecionadoACPoseAlvo = arg or valoresConfig.SelectedACPoseTarget

			if typeof(selecionadoACPoseAlvo) == "Instance" then
				selecionadoACPoseAlvo = selecionadoACPoseAlvo.Name
			end

			if not estadoFuncoes.IndependentACPoses then
				selecionadoACPoseAlvo = selecionadoACPoseAlvo and not table.find(tabela16, selecionadoACPoseAlvo)

				if selecionadoACPoseAlvo then
					opcoes.ACPoseTarget:SetValue(nil)
				end

				return
			end

			if not table.find(tabela16, selecionadoACPoseAlvo) then
