				if not isfolder("Brazuka") then
					makefolder("Brazuka")
				end

				if not isfolder("Brazuka/AutoClickerPresets") then
					makefolder("Brazuka/AutoClickerPresets")
				end

				for _, valor21 in ipairs(listfiles("Brazuka/AutoClickerPresets")) do
					if valor21:sub(-5) == ".json" then
						local correspondencia = valor21:match("([^/\\]+)%.json$")

						local sucesso, resultado = pcall(function()
							return HttpService:JSONDecode(readfile(valor21))
						end)

						if sucesso and typeof(resultado) == "table" then
							estadoCompartilhado.CustomACPresets[correspondencia] = resultado
						end
