				local texto6 = tostring(valoresConfig.CustomACPresetName or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("[%c<>:\"/\\|%?%*]", "")
				if texto6 == "" then
					notificar("Digite um nome para a predefinição primeiro.")
					return
				end
				local valor21 = estadoCompartilhado.CustomACPresets[texto6]
				local tabela17 = {}
				local corpoPos = {}
				local numero = tonumber(string.format("%.1f", valoresConfig.AutoClickerOffset.X))
				local numero2 = tonumber(string.format("%.1f", valoresConfig.AutoClickerOffset.Y))
				local valor22 = tonumber
				local formatar = string.format
				local z = valoresConfig.AutoClickerOffset.Z
				corpoPos[1] = numero
				corpoPos[2] = numero2

				do
					local valores_2 = table.pack(valor22(formatar("%.1f", z)))
					table.move(valores_2, 1, valores_2.n, 3, corpoPos)
				end

				tabela17.BodyPos = corpoPos
				tabela17.LimbOffsets = {}

				for k, valor23 in estadoCompartilhado.ACRotation, nil, nil do
					local tabela18 = {}
					local numero3 = tonumber(string.format("%.1f", valor23.X))
					local numero4 = tonumber(string.format("%.1f", valor23.Y))
					local valor24 = tonumber
					local formatar2 = string.format
					local z2 = valor23.Z
					tabela18[1] = numero3
					tabela18[2] = numero4

					do
						local valores_2 = table.pack(valor24(formatar2("%.1f", z2)))
						table.move(valores_2, 1, valores_2.n, 3, tabela18)
					end

					tabela17[k] = tabela18
				end

				for k, valor23 in estadoCompartilhado.ACOffset, nil, nil do
					local membroDeslocamentos = tabela17.LimbOffsets
					local tabela18 = {}
					local numero3 = tonumber(string.format("%.1f", valor23.X))
					local numero4 = tonumber(string.format("%.1f", valor23.Y))
					local valor24 = tonumber
					local formatar2 = string.format
					local z2 = valor23.Z
					tabela18[1] = numero3
					tabela18[2] = numero4

					do
						local valores_2 = table.pack(valor24(formatar2("%.1f", z2)))
						table.move(valores_2, 1, valores_2.n, 3, tabela18)
					end

					membroDeslocamentos[k] = tabela18
				end

				estadoCompartilhado.CustomACPresets[texto6] = tabela17
				local valor23, value24 = api.SalvarPredefinicoesPersonalizadasAC(texto6, tabela17)

				if not valor23 then
					estadoCompartilhado.CustomACPresets[texto6] = valor21
					notificar("Não foi possível salvar a predefinição: " .. valor24)
					return
				end

				api.SincronizarPredefinicoesAC(texto6)
