	api.AdicionarAtalho = function(arg, arg2, arg3, arg4, arg5, arg6)
		arg:AddLabel(arg3):AddKeyPicker(arg2, { Text = arg3, Default = arg4, NoUI = true, Mode = arg5, Callback = arg6 })

		if arg5 == "Toggle" then
			estadoCompartilhado.ToggleStates[arg3] = false
		end

		local iconeBotao = ICONES_BOTOES_MOBILE[arg2] or "circle-dot"
		local entry = {
			id = arg2,
			name = arg3,
			mode = arg5,
			icon = iconeBotao,
			defaultPos = nil,
			customPos = nil,
			created = false,
			instance = nil,
			callback = nil,
		}

		local function executarAcao()
			if arg5 == "Toggle" then
				estadoCompartilhado.ToggleStates[arg3] = not estadoCompartilhado.ToggleStates[arg3]
				local ativoAgora = estadoCompartilhado.ToggleStates[arg3]
				if entry.instance and entry.instance.SetActive then
					entry.instance:SetActive(ativoAgora)
				end
				arg6(ativoAgora)
			else
				arg6(true)
			end
		end

		entry.callback = executarAcao
		estadoCompartilhado.MobileButtonConfigs[arg2] = entry
		estadoCompartilhado.MobileButtonByName[arg3] = entry
		estadoCompartilhado.MobileButtonIconImages[arg3] = iconeBotao
		estadoCompartilhado.RegisteredKeybinds[arg3] = executarAcao
		table.insert(estadoCompartilhado.KeybindNames, arg3)
	end

	api.AdicionarBotaoMobile = function(arg, posicao)
		local entry = obterConfigBotaoMobile(arg)
		if not entry then
			return nil
		end
		if entry.created or estadoCompartilhado.ActiveDraggableButtons[entry.name] then
			notificar(string.format("O botão %q já foi criado na tela.", tostring(entry.name)))
			return entry.instance or estadoCompartilhado.ActiveDraggableButtons[entry.name]
		end

		local valor20 = bibliotecaUI:AddDraggableButton({
			Id = entry.id,
			Name = entry.name,
			Icon = entry.icon,
			Mode = entry.mode,
			Active = (entry.mode == "Toggle" and estadoCompartilhado.ToggleStates[entry.name] == true),
			Position = posicao or entry.customPos or entry.defaultPos,
			OnPositionChanged = function(_, norm)
				entry.customPos = norm
			end,
		}, function()
			if entry.callback then
				entry.callback()
			end
		end)

		entry.created = true
		entry.instance = valor20
		if not entry.defaultPos and valor20.GetNormalizedPos then
			entry.defaultPos = valor20:GetNormalizedPos()
		end
		estadoCompartilhado.ActiveDraggableButtons[entry.name] = valor20
		return valor20
	end

	api.RemoverBotaoMobile = function(arg)
		local entry = obterConfigBotaoMobile(arg)
		local nomeChave = entry and entry.name or arg
		local valor20 = (entry and entry.instance) or estadoCompartilhado.ActiveDraggableButtons[nomeChave]
		if valor20 and valor20.Destroy then
			valor20:Destroy()
		end
		if entry then
			entry.created = false
			entry.instance = nil
			entry.customPos = nil
			entry.defaultPos = nil
		end
		estadoCompartilhado.ActiveDraggableButtons[nomeChave] = nil
	end

