		local cliqueTPAlvo = nil

		api.AdicionarAtalho(JogadorLocal, "ClickTPKey", "Teleporte no Clique", "Z", "Press", function()
			if not api.ObterAlvo() then
				return
			end
			local valor21, conjuntoRaizParte = api.ObterPersonagem()
			conjuntoRaizParte = conjuntoRaizParte and conjuntoRaizParte.AssemblyRootPart
			local valor22 = api.ObterPontoImpacto()
			if not conjuntoRaizParte or not valor22 then
				return
			end
			local numero37 = valor22.Position + Vector3.new(0, 3, 0)
			local numero38 = conjuntoRaizParte.CFrame - conjuntoRaizParte.Position

			if not estadoFuncoes.SmoothClickTP then
				api.Teleportar(conjuntoRaizParte, CFrame.new(numero37) * numero38)
				return
			end

			if not cliqueTPDeslizando then
				cliqueTPDeslizando = true
				cliqueTPAlvo = numero37
				numero36 += 1

				task.spawn(function()
					local valor20 = numero36
					local posicao = conjuntoRaizParte.Position
					local agora2 = tick()

					while true do
					if valor20 ~= numero36 or not conjuntoRaizParte.Parent then
