					while task.wait(0.5) and estadoFuncoes.GradientLine and not descarregado do
						local atualizarLinhaCoresEvento = ReplicatedStorage.DataEvents.UpdateLineColorsEvent
						local dispararServidor = atualizarLinhaCoresEvento.FireServer
						local corSequencia = ColorSequence.new
						local tabela17 = {}
						local valor20 = ColorSequenceKeypoint.new(0, gradientes.Color1)
						local valor21 = ColorSequenceKeypoint.new(0.125, gradientes.Color2)
						local valor22 = ColorSequenceKeypoint.new(0.25, gradientes.Color3)
						local valor23 = ColorSequenceKeypoint.new(0.375, gradientes.Color4)
						local valor24 = ColorSequenceKeypoint.new(0.5, gradientes.Color5)
						local valor25 = ColorSequenceKeypoint.new(0.625, gradientes.Color6)
						local valor26 = ColorSequenceKeypoint.new(0.75, gradientes.Color7)
						local valor27 = ColorSequenceKeypoint.new(0.875, gradientes.Color8)
						local novo = ColorSequenceKeypoint.new
						local pontoCor = gradientes.DotColor
						tabela17[1] = valor20
						tabela17[2] = valor21
						tabela17[3] = valor22
						tabela17[4] = valor23
						tabela17[5] = valor24
						tabela17[6] = valor25
						tabela17[7] = valor26
						tabela17[8] = valor27

						do
							local valores_2 = table.pack(novo(1, pontoCor))
							table.move(valores_2, 1, valores_2.n, 9, tabela17)
						end

						local cor1 = gradientes.Color1
						local cor2 = gradientes.Color2
						local cor3 = gradientes.Color3
						local cor4 = gradientes.Color4
						local cor5 = gradientes.Color5
						local cor6 = gradientes.Color6
						local cor7 = gradientes.Color7
						local cor8 = gradientes.Color8
						local pontoCor2 = gradientes.DotColor
						dispararServidor(atualizarLinhaCoresEvento, corSequencia(tabela17), cor1, cor2, cor3, cor4, cor5, cor6, cor7, cor8, pontoCor2)
					end
				end)
			end,
		})

