		local tabela16 = {}

			for _, valor20 in estadoCompartilhado.PlayerList, nil, nil do
				if valor20 ~= jogadorLocal then
					local valor21, valor22, valor23 = api.ObterPersonagem(valor20)
					local funcao21, ragdollTocadoCaixaColisao, dispararJogadorParte, valor24, valor25

					if valor23 then
						local assentoParte = valor23.SeatPart

						if assentoParte then
							local assentoSolda = assentoParte:FindFirstChild("SeatWeld")

							if not assentoSolda or not assentoSolda.Enabled then
								tabela16[valor20] = "Usando Gucci"
							elseif valor22 then
								funcao21 = function(arg)
									if not arg or not arg.Parent then
										return
									end

									for _, valor26 in arg:GetConnectedParts() do
										if valor26.Name == "StickyPart" then
											return true
										end
									end
								end

								ragdollTocadoCaixaColisao = valor22:FindFirstChild("RagdollTouchedHitbox")
								dispararJogadorParte = valor22:FindFirstChild("FirePlayerPart")
								valor24 = funcao21(valor22) or funcao21(ragdollTocadoCaixaColisao)
								valor25 = valor24 or funcao21(dispararJogadorParte)

								if valor25 then
									tabela16[valor20] = "Shuriken no HRP (Anti-Kick)"
								end
							end
						elseif valor22 then
							funcao21 = function(arg)
								if not arg or not arg.Parent then
									return
								end

								for _, valor26 in arg:GetConnectedParts() do
									if valor26.Name == "StickyPart" then
										return true
									end
								end
							end

							ragdollTocadoCaixaColisao = valor22:FindFirstChild("RagdollTouchedHitbox")
							dispararJogadorParte = valor22:FindFirstChild("FirePlayerPart")
							valor24 = funcao21(valor22) or funcao21(ragdollTocadoCaixaColisao)
							valor25 = valor24 or funcao21(dispararJogadorParte)

							if valor25 then
								tabela16[valor20] = "Shuriken no HRP (Anti-Kick)"
							end
						end
					elseif valor22 then
						funcao21 = function(arg)
							if not arg or not arg.Parent then
								return
							end

							for _, valor26 in arg:GetConnectedParts() do
								if valor26.Name == "StickyPart" then
									return true
								end
							end
						end

						ragdollTocadoCaixaColisao = valor22:FindFirstChild("RagdollTouchedHitbox")
						dispararJogadorParte = valor22:FindFirstChild("FirePlayerPart")
						valor24 = funcao21(valor22) or funcao21(ragdollTocadoCaixaColisao)
						valor25 = valor24 or funcao21(dispararJogadorParte)

						if valor25 then
							tabela16[valor20] = "Shuriken no HRP (Anti-Kick)"
						end
					end
				end
			end

		return tabela16
	end

	local function relatarTrapaceiros(tabela16)
		if not next(tabela16) then
			return notificar("Nenhum trapaceiro encontrado!")
		end
		local texto5 = "Cheaters Found\n\n"

		for k, valor20 in pairs(tabela16) do
			texto5 ..= ("[%*]\n%*\n\n"):format(api.FormatarJogador(k), valor20)
		end

		notificar(texto5:sub(1, -3))
	end

	Trapaceiros:AddButton({
		Text = "Procurar Trapaceiros",
		Icon = "eye",
		Func = function()
			relatarTrapaceiros(coletarTrapaceiros())
		end,
	})

	local autoEncontrarUltimo = {}
	local proximoAutoEncontrar = 0
	local autoEncontrarIntervalo = 15

	Trapaceiros:AddToggle("AutoFindCheaters", {
		Text = "Detectar Trapaceiros Auto",
		Default = false,
		Tooltip = "Verifica jogadores automaticamente em busca de trapaças e avisa quando encontrar",
		Callback = function(autoEncontrar)
			if autoEncontrar then
				proximoAutoEncontrar = 0
			end
		end,
	})

	Trapaceiros:AddSlider("AutoFindInterval", {
		Text = "Intervalo de Verificação",
		Default = 15,
		Min = 5,
		Max = 60,
		Rounding = 0,
		Compact = true,
		Suffix = " segundos",
		Callback = function(verificarIntervalo)
			autoEncontrarIntervalo = verificarIntervalo
		end,
	})

	task.spawn(function()
		while task.wait(1) do
			if descarregado then
				return
			end

			if not alternadores.AutoFindCheaters or not alternadores.AutoFindCheaters.Value then
				continue
			end

			if os.clock() < proximoAutoEncontrar then
				continue
			end

			proximoAutoEncontrar = os.clock() + math.clamp(autoEncontrarIntervalo, 5, 60)
			local atualTrapaceiros = coletarTrapaceiros()

			for jogador, motivo in atualTrapaceiros do
				if autoEncontrarUltimo[jogador] ~= motivo then
					autoEncontrarUltimo[jogador] = motivo
					notificarSistema(("Trapaceiro detectado: %s (%s)"):format(api.FormatarJogador(jogador), motivo))
				end
			end

			for jogador in autoEncontrarUltimo do
				if not atualTrapaceiros[jogador] then
					autoEncontrarUltimo[jogador] = nil
				end
			end
		end
	end)

