	do
		local function funcao21(arg)
			if typeof(arg) ~= "UDim2" then
				return
			end
			return { arg.X.Scale, arg.X.Offset, arg.Y.Scale, arg.Y.Offset }
		end

		local function funcao22(arg)
			if typeof(arg) ~= "table" then
				return
			end

			for i = 1, 4 do
				if typeof(arg[i]) ~= "number" then
					return
				end
			end

			return UDim2.new(arg[1], arg[2], arg[3], arg[4])
		end

		local function funcao23(arg)
			local areaVisaoTamanho = cameraAtual.ViewportSize
			local numero36 = arg.AbsolutePosition + arg.AbsoluteSize / 2
			local tabela16 = {}
			local numero37 = numero36.X / math.max(areaVisaoTamanho.X, 1)
			local numero38 = numero36.Y / math.max(areaVisaoTamanho.Y, 1)
			tabela16[1] = numero37
			tabela16[2] = numero38
			return tabela16
		end

		local function funcao24(arg, arg2, posicao)
			if not arg or not arg.Parent then
				return
			end

			if posicao then
				arg.Position = posicao
			end

			local areaVisaoTamanho = cameraAtual.ViewportSize
			local absolutoTamanho = arg.AbsoluteSize
			local x = arg.AbsolutePosition.X
			local y = arg.AbsolutePosition.Y

			if typeof(arg2) == "table" and typeof(arg2[1]) == "number" and typeof(arg2[2]) == "number" then
				x = arg2[1] * areaVisaoTamanho.X - absolutoTamanho.X / 2
				y = arg2[2] * areaVisaoTamanho.Y - absolutoTamanho.Y / 2
			end

			local numero36 = math.clamp(x, 6, math.max(6, areaVisaoTamanho.X - absolutoTamanho.X - 6))
			local numero37 = math.clamp(y, 6, math.max(6, areaVisaoTamanho.Y - absolutoTamanho.Y - 6))
			local absolutoPosicao

			if arg.Parent:IsA("GuiObject") then
				absolutoPosicao = arg.Parent.AbsolutePosition
			else
				absolutoPosicao = Vector2.zero
			end

			arg.Position = UDim2.fromOffset(math.round(numero36 - absolutoPosicao.X + arg.AnchorPoint.X * absolutoTamanho.X), math.round(numero37 - absolutoPosicao.Y + arg.AnchorPoint.Y * absolutoTamanho.Y))
		end

		local function funcao25(arg, arg2)
			if not arg or not arg.Parent or not arg2 then
				return
			end
			local areaVisaoTamanho = cameraAtual.ViewportSize
			local absolutoTamanho

			if arg.Parent:IsA("GuiObject") then
				absolutoTamanho = arg.Parent.AbsoluteSize
			else
				absolutoTamanho = areaVisaoTamanho
			end

			local uiEscala = arg:FindFirstChildOfClass("UIScale")
			uiEscala = uiEscala and uiEscala.Scale or 1
			local numero36 = (absolutoTamanho.Y * arg2.Y.Scale + arg2.Y.Offset) * uiEscala
			local numero37 = math.min(1, (areaVisaoTamanho.X - 12) / math.max((absolutoTamanho.X * arg2.X.Scale + arg2.X.Offset) * uiEscala, 1), (areaVisaoTamanho.Y - 12) / math.max(numero36, 1))
			local numero38 = arg2.Y.Scale * numero37
			local arredondar = math.round
			local numero39 = arg2.Y.Offset * numero37
			arg.Size = UDim2.new(arg2.X.Scale * numero37, math.round(arg2.X.Offset * numero37), numero38, arredondar(numero39))
		end

		local function funcao26()
			local principalQuadro = janela.MainFrame
			local barraLateralLargura = janela:GetSidebarWidth()

