			for _, valor21 in ipairs(valor20) do
				if not table.find(valor21.Dropdown.Values, jogador) then
					valor21.Dropdown:AddValues({ jogador })
				end

				if valor21.Multi == false then
					valor21.Dropdown:SetValue(jogador)
					table.clear(valor21.Values)
					valor21.Values[jogador] = true
					table.clear(valor21.Selected)
					valor21.Selected[jogador] = true
				else
					local tabela17 = {}

					for k, valor22 in pairs(valor21.Selected) do
						tabela17[k] = valor22
					end

					tabela17[jogador] = true
					valor21.Dropdown:SetValue(tabela17)
					table.clear(valor21.Values)

					for k, valor22 in pairs(tabela17) do
						valor21.Values[k] = valor22
					end

					valor21.Selected[jogador] = true
				end
			end

			api.NotificarEvento("Player Rejoined", { rejoinedPlayer = api.FormatarJogador(jogador), listCount = #valor20 }, "Jogador Reentrou")
		end)
	end

	notificar("Script carregado em " .. math.round((tick() - getgenv().LoadTime) * 100) / 100 .. " segundos", "Brazuka", 71450094482101)
	getgenv().LoadTime = nil

	return {
		copyright = "Copyright (c) 2026 Project Brazuka. All rights reserved.",
	}
end
]=]
bundle["Launcher"] = [[
local pacote = ...
local ambiente = getgenv and getgenv() or _G
if ambiente.BrazukaRunning or ambiente.BrazukaStarting then
    warn("O Brazuka já está em execução ou iniciando")
    return
end
assert(type(loadstring) == "function", "This executor does not support loadstring")
assert(type(getgenv) == "function", "This executor does not support getgenv")
ambiente.BrazukaStarting = true
local limpeza
local function registrarLimpeza(fn) limpeza = fn end
local cache = {}
local carregando = {}
local function importarModulo(nome)
    if cache[nome] then return cache[nome] end
    assert(not carregando[nome], "Circular module dependency: " .. tostring(nome))
    assert(type(pacote[nome]) == "string", "Missing module: " .. tostring(nome))
    carregando[nome] = true
    local trecho, mensagem = loadstring(pacote[nome], "@Brazuka/" .. nome)
    assert(trecho, mensagem)
    local sucesso, resultado = pcall(trecho, importarModulo)
    carregando[nome] = nil
    assert(sucesso, resultado)
    assert(type(resultado) == "table", "Invalid module: " .. nome)
    cache[nome] = resultado
    return resultado
end
local caminhoRecarga
local sucesso, resultado = xpcall(function()
    caminhoRecarga = nil
    local trecho, mensagem = loadstring(pacote.Runtime, "@Brazuka/Runtime")
    assert(trecho, mensagem)
    return trecho(importarModulo, caminhoRecarga, registrarLimpeza)
end, function(mensagem)
    if debug and debug.traceback then return debug.traceback(tostring(mensagem), 2) end
    return tostring(mensagem)
end)
ambiente.BrazukaStarting = false
if not sucesso then
    if limpeza then pcall(limpeza) end
    ambiente.BrazukaRunning = false
    warn("Falha na inicialização do Brazuka: " .. tostring(resultado))
    return nil, resultado
end
return resultado
]]
